import React from "react";
import { Dialog, DialogContent } from "@mui/material";
import PersonFormPanel from "../Shared/Person/PersonFormPanel";
import FAlert from "../Popups/FailedAlert";
export default function AddPerson({ open, onClose, onSave }) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <PersonFormPanel mode="add" onClose={onClose} onSave={onSave} />
      </DialogContent>
    </Dialog>
  );
}
