const SESSION_KEY = "dvld_session";

// يُستدعى فور نجاح تسجيل الدخول (وجلب currentUser + currentPerson كاملين)
export function saveSession(user, person) {
  try {
    localStorage.setItem(SESSION_KEY, JSON.stringify({ user, person }));
  } catch (err) {
    console.error("Failed to save session:", err);
  }
}

// يُستدعى مرة وحدة عند تحميل التطبيق (store/index.js) لإعادة تعبئة الجلسة
export function loadSession() {
  try {
    const raw = localStorage.getItem(SESSION_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch (err) {
    console.error("Failed to load session:", err);
    return null;
  }
}

// يُستدعى عند Sign Out (مستخدم أصلاً بـ TopBarButtons.jsx)
export function clearSession() {
  try {
    localStorage.removeItem(SESSION_KEY);
  } catch (err) {
    console.error("Failed to clear session:", err);
  }
}
