import React from "react";
import { Box, Typography, TextField } from "@mui/material";
import BadgeIcon from "@mui/icons-material/Badge";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import AttachMoneyIcon from "@mui/icons-material/AttachMoney";
import PersonIcon from "@mui/icons-material/Person";
import LockClockIcon from "@mui/icons-material/LockClock";

function Field({ icon: Icon, label, value }) {
  const isEmpty = value === undefined || value === null || value === "";
  return (
    <Box className="license-info-field">
      <Box className="license-info-field-label">
        {Icon && <Icon className="license-info-field-icon" />}
        {label}
      </Box>
      <Typography
        className={
          isEmpty
            ? "license-info-field-value license-info-field-value-empty"
            : "license-info-field-value"
        }
      >
        {isEmpty ? "Not searched yet" : value}
      </Typography>
    </Box>
  );
}

// ✅ مكوّن "Detain Info" القابل لإعادة الاستخدام — بطاقة منظّمة
// variant="full"    → كل الحقول
// variant="compact" → Fine Fees قابل للتعديل فقط
export default function DetainInfoPanel({
  variant = "full",
  detainInfo,
  fineFees,
  onFineFeesChange,
  fineFeesError,
}) {
  return (
    <Box className="detain-info-card">
      <Box className="detain-info-card-header">
        <LockClockIcon className="license-info-card-header-icon" />
        <Typography className="license-info-card-title">DETAIN INFO</Typography>
      </Box>

      <Box className="detain-info-fields-grid">
        <Field
          icon={BadgeIcon}
          label="Detain ID"
          value={detainInfo?.detainId}
        />
        <Field
          icon={BadgeIcon}
          label="License ID"
          value={detainInfo?.licenseId}
        />
        <Field
          icon={CalendarTodayIcon}
          label="Detain Date"
          value={detainInfo?.detainDate}
        />
        <Field
          icon={PersonIcon}
          label="Created By"
          value={detainInfo?.createdBy}
        />

        {variant === "full" && (
          <>
            <Field
              icon={AttachMoneyIcon}
              label="Application Fees"
              value={detainInfo?.applicationFees}
            />
            <Field
              icon={AttachMoneyIcon}
              label="Fine Fees"
              value={detainInfo?.fineFees}
            />
            <Field
              icon={AttachMoneyIcon}
              label="Total Fees"
              value={detainInfo?.totalFees}
            />
            <Field
              icon={BadgeIcon}
              label="Application ID"
              value={detainInfo?.applicationId}
            />
          </>
        )}

        {variant === "compact" && (
          <Box className="license-info-field">
            <Box className="license-info-field-label">
              <AttachMoneyIcon className="license-info-field-icon" />
              Fine Fees
            </Box>
            <TextField
              size="small"
              type="number"
              placeholder="0.00"
              value={fineFees}
              onChange={onFineFeesChange}
              error={!!fineFeesError}
              helperText={fineFeesError}
              className="detain-fine-fees-input"
            />
          </Box>
        )}
      </Box>
    </Box>
  );
}
