import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  detainStatus: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  error: null,
};

export const getDetainedLicenses = createAsyncThunk(
  "DetainedLicenses/getDetainedLicenses",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/DetainedLicenses",
    );
    return response.data;
  },
  {
    condition: (_, { getState }) => {
      const { DetainedLicenses } = getState();
      if (
        DetainedLicenses.status === "loading" ||
        DetainedLicenses.list.length > 0
      ) {
        return false;
      }
      return true;
    },
  },
);

// ✅ إصدار Detain جديد
export const detainLicense = createAsyncThunk(
  "DetainedLicenses/detainLicense",
  async (payload, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/DetainedLicenses",
        payload,
      );
      return response.data; // الـ object الكامل مع detainID الحقيقي بعد الإصدار
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Detain failed",
      );
    }
  },
);

const detainedLicensesSlice = createSlice({
  name: "DetainedLicenses",
  initialState,
  reducers: {
    addDetainedLicense: (state, action) => {
      state.list.push(action.payload);
    },
    resetDetainStatus: (state) => {
      state.detainStatus = "idle";
    },
    markDetainReleasedLocally: (state, action) => {
      const { detainID, releasedByUserId } = action.payload;
      const index = state.list.findIndex((d) => d.detainID === detainID);
      if (index !== -1) {
        state.list[index] = {
          ...state.list[index],
          isReleased: true,
          releaseDate: new Date().toISOString(),
          releasedByUserID: releasedByUserId,
        };
      }
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(getDetainedLicenses.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getDetainedLicenses.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.list = action.payload;
      })
      .addCase(getDetainedLicenses.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })

      .addCase(detainLicense.pending, (state) => {
        state.detainStatus = "loading";
        state.error = null;
      })
      .addCase(detainLicense.fulfilled, (state, action) => {
        state.detainStatus = "succeeded";
        state.list.push(action.payload);
      })
      .addCase(detainLicense.rejected, (state, action) => {
        state.detainStatus = "failed";
        state.error = action.payload;
      });
  },
});

export const {
  addDetainedLicense,
  resetDetainStatus,
  markDetainReleasedLocally,
} = detainedLicensesSlice.actions;
export default detainedLicensesSlice.reducer;
