import React, { useEffect, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { Box, Typography, Link } from "@mui/material";
import DescriptionIcon from "@mui/icons-material/Description";
import CardMembershipIcon from "@mui/icons-material/CardMembership";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import BadgeIcon from "@mui/icons-material/Badge";
import FlagIcon from "@mui/icons-material/Flag";
import AttachMoneyIcon from "@mui/icons-material/AttachMoney";
import CategoryIcon from "@mui/icons-material/Category";
import PersonIcon from "@mui/icons-material/Person";
import EventIcon from "@mui/icons-material/Event";
import EventAvailableIcon from "@mui/icons-material/EventAvailable";
import PersonPinIcon from "@mui/icons-material/PersonPin";

import InfoCard from "../InfoCard";
import Field from "../Field";
import ShowLicenseInfo from "../License/Showlicenseinfo";
import { getLocalDrivingLicenseById } from "../../Store/features/LocalDrivingLicense/LocalDrivingLicenseSlice";
import { getApplicationByApplicationId } from "../../Store/features/Application/ApplicationSlice";
import { getLicenseClassByID } from "../../Store/features/licenseClass/licenseClassSlice";
import { getAllUsers } from "../../Store/features/Users/userSlice";

const ShowApplicationInfo = ({ localApplicationId }) => {
  const lastFetchedId = useRef(null);
  const [isLicenseInfoOpen, setIsLicenseInfoOpen] = useState(false);
  const dispatch = useDispatch();

  const selectedInfo = useSelector(
    (state) => state.LocalDrivingLicense.selectedInfo,
  );
  const application = useSelector((state) =>
    state.applications.list.find(
      (a) => a.applicationID === selectedInfo?.applicationID,
    ),
  );
  const licenseClass = useSelector((state) =>
    state.LicenseClass.list.find(
      (c) => c.license_class_id === selectedInfo?.licenseClassID,
    ),
  );
  const User = useSelector((state) =>
    state.users.list.find((u) => u.user_id === selectedInfo?.createdByUserID),
  );
  const listRow = useSelector((state) =>
    state.LocalDrivingLicense.list.find(
      (l) => l.local_driving_license_application_id === localApplicationId,
    ),
  );
  const licensesList = useSelector((state) => state.licenses.list);
  const matchedLicense = licensesList.find(
    (l) => l.application_id === selectedInfo?.applicationID,
  );
  const licenseId = matchedLicense?.license_id ?? null;

  useEffect(() => {
    if (localApplicationId && lastFetchedId.current !== localApplicationId) {
      lastFetchedId.current = localApplicationId;
      dispatch(getLocalDrivingLicenseById(localApplicationId));
    }
  }, [localApplicationId, dispatch]);

  useEffect(() => {
    if (selectedInfo?.applicationID) {
      dispatch(getApplicationByApplicationId(selectedInfo.applicationID));
    }
  }, [selectedInfo?.applicationID, dispatch]);

  useEffect(() => {
    if (selectedInfo?.licenseClassID) {
      dispatch(getLicenseClassByID(selectedInfo.licenseClassID));
    }
  }, [selectedInfo?.licenseClassID, dispatch]);

  useEffect(() => {
    dispatch(getAllUsers());
  }, [dispatch]);

  if (!selectedInfo) {
    return (
      <Box sx={{ p: 2 }}>
        <Typography>Loading...</Typography>
      </Box>
    );
  }

  const passedTestsCount = listRow?.passed_test_count ?? "-";
  const statusText = listRow?.application_status ?? selectedInfo.statusText;
  const fees = application?.paidFees ?? selectedInfo.paidFees;
  const statusDate = (
    application?.lastStatusDate ?? selectedInfo.lastStatusDate
  )?.split("T")[0];
  const applicationDate = (
    application?.applicationDate ?? selectedInfo.applicationDate
  )?.split("T")[0];

  return (
    <>
      <InfoCard icon={DescriptionIcon} title="DRIVING LICENSE APPLICATION INFO">
        <Field
          icon={DescriptionIcon}
          label="D.L.App ID"
          value={selectedInfo.localDrivingLicenseApplicationID}
        />
        <Field
          icon={CardMembershipIcon}
          label="Applied For License"
          value={licenseClass?.class_name}
        />
        <Field
          icon={CheckCircleIcon}
          label="Passed Tests"
          value={`${passedTestsCount}/3`}
        />

        {licenseId && (
          <Box className="license-info-field">
            <Link
              component="button"
              underline="hover"
              onClick={() => setIsLicenseInfoOpen(true)}
              className="profile-edit-link"
            >
              Show License Info
            </Link>
          </Box>
        )}
      </InfoCard>

      <InfoCard icon={BadgeIcon} title="APPLICATION BASIC INFO">
        <Field icon={BadgeIcon} label="ID" value={selectedInfo.applicationID} />
        <Field icon={EventIcon} label="Date" value={applicationDate} />
        <Field icon={FlagIcon} label="Status" value={statusText} />
        <Field
          icon={EventAvailableIcon}
          label="Status Date"
          value={statusDate}
        />
        <Field icon={AttachMoneyIcon} label="Fees" value={fees} />
        <Field icon={PersonIcon} label="Created By" value={User?.user_name} />
        <Field
          icon={CategoryIcon}
          label="Type"
          value="New Local Driving License Service"
        />
        <Field
          icon={PersonPinIcon}
          label="Applicant"
          value={selectedInfo.applicantFullName}
        />
      </InfoCard>

      <ShowLicenseInfo
        licenseId={licenseId}
        open={isLicenseInfoOpen}
        onClose={() => setIsLicenseInfoOpen(false)}
      />
    </>
  );
};

export default React.memo(ShowApplicationInfo);
