import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import AutorenewIcon from "@mui/icons-material/Autorenew";

import LicenseFilter from "../License/LicenseFilter";
import { LicenseInfoContent } from "../License/Showlicenseinfo";
import ApplicationNewLicenseInfo from "./ApplicationNewLicenseInfo";
import {
  getLicenses,
  renewLicense,
} from "../../Store/features/Licenses/LicensesSlice";
import { getApplicationTypes } from "../../Store/features/ApplicationType/ApplicationTypeSlice";
import { getLicenseClasses } from "../../Store/features/licenseClass/licenseClassSlice"; // ⚠️ عدّل المسار حسب مكان الملف عندك

const RENEW_APPLICATION_TYPE_ID = 2;
const FALLBACK_APPLICATION_FEES = 150;

export default function RenewLicenseModal({ open, onClose }) {
  const dispatch = useDispatch();

  const [filterInput, setFilterInput] = useState("");
  const [committedLicenseId, setCommittedLicenseId] = useState(null);
  const [searchError, setSearchError] = useState(null);
  const [notes, setNotes] = useState("");
  const [renewedResult, setRenewedResult] = useState(null);

  const currentUser = useSelector((state) => state.users.currentUser);
  const licensesList = useSelector((state) => state.licenses.list);
  const applicationTypes = useSelector((state) => state.ApplicationType.list);
  const licenseClasses = useSelector((state) => state.LicenseClass.list);
  const renewStatus = useSelector((state) => state.licenses.renewStatus);
  const renewError = useSelector((state) => state.licenses.error);

  const selectedLicense = licensesList.find(
    (l) => l.license_id === committedLicenseId,
  );

  const matchedLicenseClass = licenseClasses.find((c) => {
    const cId = c.license_class_id ?? c.licenseClassID;
    return Number(cId) === Number(selectedLicense?.license_class);
  });
  const licenseFeesPreview = matchedLicenseClass?.class_fees ?? null;

  const isLoading = renewStatus === "loading";
  const alreadyRenewed = Boolean(renewedResult);

  const isExpired =
    selectedLicense?.expiration_date &&
    new Date(selectedLicense.expiration_date) < new Date();

  const canRenew =
    Boolean(committedLicenseId) &&
    isExpired &&
    notes.trim().length > 0 &&
    !isLoading &&
    !alreadyRenewed;

  const applicationFees =
    applicationTypes.find(
      (t) => t.application_type_id === RENEW_APPLICATION_TYPE_ID,
    )?.application_fees ?? FALLBACK_APPLICATION_FEES;

  useEffect(() => {
    if (!open) return;
    dispatch(getLicenses());
    dispatch(getApplicationTypes());
    dispatch(getLicenseClasses());
  }, [open, dispatch]);

  const resetAll = () => {
    setFilterInput("");
    setCommittedLicenseId(null);
    setSearchError(null);
    setNotes("");
    setRenewedResult(null);
  };

  const handleClose = () => {
    resetAll();
    onClose();
  };

  const handleSearch = () => {
    const idNum = Number(filterInput);
    if (!idNum) {
      setSearchError("الرجاء إدخال رقم رخصة صحيح");
      setCommittedLicenseId(null);
      return;
    }

    const foundLicense = licensesList.find((l) => l.license_id === idNum);

    if (!foundLicense) {
      setSearchError("لا توجد رخصة بهذا الرقم");
      setCommittedLicenseId(null);
      return;
    }

    if (!foundLicense.is_active) {
      setSearchError(
        "هذه الرخصة غير مفعّلة (Inactive) — الرجاء اختيار رخصة Active فقط",
      );
      setCommittedLicenseId(null);
      return;
    }

    const stillValid =
      foundLicense.expiration_date &&
      new Date(foundLicense.expiration_date) >= new Date();

    if (stillValid) {
      setSearchError("هذه الرخصة لم تنتهِ صلاحيتها بعد — لا يمكن تجديدها الآن");
      setCommittedLicenseId(idNum);
      setRenewedResult(null);
      return;
    }

    setSearchError(null);
    setCommittedLicenseId(idNum);
    setRenewedResult(null);
  };

  const handleRenew = async () => {
    if (!committedLicenseId) return;
    try {
      const result = await dispatch(
        renewLicense({
          licenseId: committedLicenseId,
          notes,
          createdByUserId: currentUser?.userID,
        }),
      ).unwrap();
      setRenewedResult(result);
    } catch (err) {
      console.error("Renew license failed:", err);
    }
  };

  useEffect(() => {
    if (renewStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [renewStatus]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          Renew License Application
        </Typography>

        <LicenseFilter
          value={filterInput}
          onChange={(e) => setFilterInput(e.target.value)}
          onSearch={handleSearch}
          error={searchError}
        />

        {committedLicenseId ? (
          <Box className="replace-license-license-info">
            <LicenseInfoContent licenseId={committedLicenseId} />
          </Box>
        ) : (
          <Typography className="replace-license-placeholder">
            ابحث برقم الرخصة أولاً
          </Typography>
        )}

        {committedLicenseId && (
          <ApplicationNewLicenseInfo
            applicationID={renewedResult?.applicationID}
            renewedLicenseID={renewedResult?.licenseID}
            oldLicenseID={committedLicenseId}
            applicationDate={renewedResult ? new Date().toISOString() : null}
            issueDate={renewedResult?.issueDate}
            expirationDate={renewedResult?.expirationDate}
            applicationFees={applicationFees}
            licenseFees={renewedResult?.paidFees ?? licenseFeesPreview}
            createdByLabel={currentUser?.user_name ?? currentUser?.userID}
            notes={renewedResult?.notes ?? notes}
            onNotesChange={setNotes}
            notesReadOnly={alreadyRenewed}
          />
        )}

        {renewStatus === "succeeded" && (
          <Alert severity="success" variant="filled" sx={{ mt: 2 }}>
            License renewed successfully ✅
          </Alert>
        )}

        {renewStatus === "failed" && renewError && (
          <Alert severity="error" variant="filled" sx={{ mt: 2 }}>
            {typeof renewError === "string" ? renewError : "فشل تجديد الرخصة"}
          </Alert>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button
          variant="contained"
          color="error"
          startIcon={<CloseIcon />}
          onClick={handleClose}
          className="modal-btn-cancel"
        >
          Close
        </Button>
        <Button
          variant="contained"
          startIcon={
            isLoading ? (
              <CircularProgress size={16} color="inherit" />
            ) : (
              <AutorenewIcon />
            )
          }
          onClick={handleRenew}
          disabled={!canRenew}
          className="modal-btn-save"
        >
          Renew
        </Button>
      </DialogActions>
    </Dialog>
  );
}
