import React, { useState, useCallback } from "react";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Button,
  Typography,
} from "@mui/material";

import DriverLicenseInfoPanel from "../Shared/License/DriverLicenseInfoPanel";
import DetainInfoPanel from "../Shared/Application/DetainInfoPanel";
import { validateRequired } from "../validations/validation";

// شاشة "Detain License" — تبحث عن رخصة برقمها ثم تسمح بإدخال Fine Fees
// findLicenseById لازم توصل لاحقًا من الـ API؛ حاليًا بلا مصدر بيانات حقيقي
// (بانتظار ربط RESTful API)، لذلك أي بحث سيُرجع "لم يتم العثور عليها"
export default function AddDetainedLicense({ open, onClose, findLicenseById }) {
  const [licenseId, setLicenseId] = useState("");
  const [license, setLicense] = useState(null);
  const [searchError, setSearchError] = useState("");
  const [fineFees, setFineFees] = useState("");
  const [fineFeesError, setFineFeesError] = useState("");

  const handleSearch = useCallback(() => {
    const found = findLicenseById ? findLicenseById(licenseId) : null;
    if (!found) {
      setSearchError("License not found");
      setLicense(null);
      return;
    }
    setSearchError("");
    setLicense(found);
  }, [licenseId, findLicenseById]);

  const handleClose = useCallback(() => {
    setLicenseId("");
    setLicense(null);
    setSearchError("");
    setFineFees("");
    setFineFeesError("");
    onClose();
  }, [onClose]);

  const handleSave = useCallback(() => {
    if (!license) return;
    const error = validateRequired(fineFees, "Fine Fees");
    if (error) {
      setFineFeesError(error);
      return;
    }
    const payload = { licenseId: license.id, fineFees };
    // لاحقاً هنا فقط: dispatch(detainLicense(payload))
    console.log("Detain license:", payload);
    handleClose();
  }, [license, fineFees, handleClose]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          Detain License
        </Typography>

        {searchError && (
          <Typography className="modal-error-text">{searchError}</Typography>
        )}

        <DriverLicenseInfoPanel
          licenseId={licenseId}
          onLicenseIdChange={(e) => setLicenseId(e.target.value)}
          onSearch={handleSearch}
          license={license}
          personName={license?.personName}
        />

        <DetainInfoPanel
          variant="compact"
          fineFees={fineFees}
          onFineFeesChange={(e) => {
            setFineFees(e.target.value);
            setFineFeesError("");
          }}
          fineFeesError={fineFeesError}
        />
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button onClick={handleClose} className="modal-btn-cancel">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          className="modal-btn-save"
          variant="contained"
          disabled={!license}
        >
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
}
