import React, { useState, useEffect } from "react";
import Dialog from "@mui/material/Dialog";
import DialogTitle from "@mui/material/DialogTitle";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import Button from "@mui/material/Button";
import TextField from "@mui/material/TextField";
import Radio from "@mui/material/Radio";
import RadioGroup from "@mui/material/RadioGroup";
import FormControlLabel from "@mui/material/FormControlLabel";
import Alert from "@mui/material/Alert";
import { useDispatch, useSelector } from "react-redux";
import { addTest } from "../../Store/features/tests/testsSlice";
import { incrementPassedTestCount } from "../../Store/features/LocalDrivingLicense/LocalDrivingLicenseSlice";

const TestResultModal = ({
  open,
  onClose,
  appointment,
  section,
  localDrivingLicenseApplicationID,
}) => {
  const dispatch = useDispatch();
  const currentUserID = useSelector(
    (state) => state.users?.currentUser?.userID,
  );

  const [result, setResult] = useState("pass");
  const [notes, setNotes] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const [saveSucceeded, setSaveSucceeded] = useState(false);

  useEffect(() => {
    if (open) {
      setResult("pass");
      setNotes("");
      setError("");
      setSaveSucceeded(false);
    }
  }, [open, appointment]);

  const handleCancel = () => {
    onClose();
  };

  const handleSave = async () => {
    if (!appointment) return;

    const payload = {
      testAppointmentID: appointment.test_appointment_id,
      testResult: result === "pass",
      notes,
      createdByUserID: currentUserID,
    };

    setIsSaving(true);
    try {
      await dispatch(addTest(payload)).unwrap();
      if (result === "pass" && localDrivingLicenseApplicationID) {
        dispatch(incrementPassedTestCount(localDrivingLicenseApplicationID));
      }
      setIsSaving(false);
      setSaveSucceeded(true);
    } catch (err) {
      setIsSaving(false);
      setError("Failed to save the result. Please try again.");
    }
  };

  // ✅ إغلاق تلقائي بعد النجاح (نفس نمط باقي الشاشات) — يرجّع تلقائيًا
  // لـ ShowAppointment لأنها الديالوج الأب
  useEffect(() => {
    if (saveSucceeded) {
      const timer = setTimeout(() => {
        onClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [saveSucceeded]);

  const Icon = section?.icon;

  return (
    <Dialog open={open} onClose={handleCancel} maxWidth="sm" fullWidth>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          p: 1,
        }}
      >
        <DialogTitle
          sx={{ p: 1, display: "flex", alignItems: "center", gap: 1 }}
        >
          {Icon && <Icon color="primary" />}
          {section?.label ?? "Test Result"}
        </DialogTitle>
        <IconButton onClick={handleCancel} size="small" disabled={isSaving}>
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>

      <DialogContent>
        {saveSucceeded && (
          <Alert severity="success" variant="filled" sx={{ mb: 2 }}>
            Test result saved successfully ✅
          </Alert>
        )}

        <Box sx={{ display: "flex", alignItems: "center", gap: 2, mb: 2 }}>
          <Typography sx={{ fontWeight: 600 }}>Result:</Typography>
          <RadioGroup
            row
            value={result}
            onChange={(e) => setResult(e.target.value)}
          >
            <FormControlLabel
              value="pass"
              control={<Radio />}
              label="Pass"
              disabled={saveSucceeded}
            />
            <FormControlLabel
              value="fail"
              control={<Radio />}
              label="Fail"
              disabled={saveSucceeded}
            />
          </RadioGroup>
        </Box>

        <Typography sx={{ fontWeight: 600, mb: 1 }}>Notes:</Typography>
        <TextField
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          multiline
          rows={5}
          fullWidth
          disabled={isSaving || saveSucceeded}
        />

        {error && (
          <Alert severity="error" variant="filled" sx={{ mt: 2 }}>
            {error}
          </Alert>
        )}
      </DialogContent>

      <DialogActions sx={{ justifyContent: "center", gap: 2, p: 2 }}>
        <Button
          variant="outlined"
          onClick={handleCancel}
          disabled={isSaving || saveSucceeded}
        >
          Cancel
        </Button>
        <Button
          variant="contained"
          onClick={handleSave}
          disabled={isSaving || saveSucceeded}
        >
          {isSaving ? "Saving..." : "Save"}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default TestResultModal;
