import React, { useEffect } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
} from "@mui/material";
import { useSelector, useDispatch } from "react-redux";
import {
  DeletPerson,
  resetDeleteStatus,
} from "../Store/features/people/peopleSlice";
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
import Alert from "@mui/material/Alert";

// Dialog تأكيد حذف شخص — يتابع deletingstatus من Redux ويعرض الحالة المناسبة:
// idle: تأكيد الحذف | loading: دائرة تحميل | failed: رسالة خطأ | succeeded: Alert أخضر ثم إغلاق كل شيء
export default function DeletePerson({ open, onClose, personId }) {
  const dispatch = useDispatch();
  const deletingstatus = useSelector((state) => state.people.deletingstatus);
  const error = useSelector((state) => state.people.error);

  const handleDelete = () => {
    dispatch(DeletPerson(personId));
  };

  // بعد نجاح الحذف: نستنى شوية عشان يشوف المستخدم رسالة النجاح، ثم نقفل كل شيء
  useEffect(() => {
    if (deletingstatus === "succeeded") {
      const timer = setTimeout(() => {
        onClose();
        dispatch(resetDeleteStatus());
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [deletingstatus, onClose, dispatch]);

  const handleClose = () => {
    // منع الإغلاق أثناء التحميل
    if (deletingstatus === "loading") return;
    onClose();
    dispatch(resetDeleteStatus());
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullWidth
      maxWidth="xs"
      className="modal-dialog"
    >
      <DialogTitle className="modal-title">Delete Person</DialogTitle>

      <DialogContent className="modal-content">
        {deletingstatus === "loading" && (
          <Box sx={{ display: "flex", justifyContent: "center", py: 2 }}>
            <CircularProgress />
          </Box>
        )}

        {deletingstatus === "failed" && (
          <FeildAlert>
            {error || "Failed to delete this record, please try again"}
          </FeildAlert>
        )}

        {deletingstatus === "succeeded" && (
          <Alert severity="success" variant="outlined">
            Person deleted successfully ✅
          </Alert>
        )}

        {(deletingstatus === "idle" || !deletingstatus) && (
          <Typography>Are you sure you want to delete this record?</Typography>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        {deletingstatus !== "succeeded" && (
          <>
            <Button
              onClick={handleClose}
              className="modal-btn-cancel"
              disabled={deletingstatus === "loading"}
            >
              Cancel
            </Button>
            <Button
              onClick={handleDelete}
              className="modal-btn-save"
              variant="contained"
              color="error"
              disabled={deletingstatus === "loading"}
            >
              Delete
            </Button>
          </>
        )}
      </DialogActions>
    </Dialog>
  );
}
