import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import TodayIcon from "@mui/icons-material/Today";
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { getTestAppointments } from "../Store/features/TestAppointments/TestAppointmentsSlice";
import Filter from "../Shared/Filter";

const FILTER_FIELD_MAP = {
  Appointmentsid: "Appointmentsid",
  L_A_ID: "L_A_ID",
  FullName: "FullName",
  Fulfilled: "Fulfilled",
};
// شاشة Manage All Appointments — Component عرض فقط، بلا بيانات وهمية
export default function ManageAllAppointmentsScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");

  const dispatch = useDispatch();

  // useSelector: بيقرأ فقط الجزء الخاص بـ people من الـ state الكلي
  const Appointments = useSelector((state) => state.testAppointments.list);
  const status = useSelector((state) => state.testAppointments.status);
  const error = useSelector((state) => state.testAppointments.error);

  useEffect(() => {
    dispatch(getTestAppointments());
  }, [dispatch]);

  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }
  const rows = Appointments.map((appointment) => ({
    Appointmentsid: appointment.test_appointment_id,
    L_A_ID: appointment.local_driving_license_application_id,
    FullName: appointment.full_name,
    title: appointment.test_type_title,
    className: appointment.class_name,
    Date: appointment.appointment_date,
    Fees: appointment.paid_fees,
    Fulfilled: appointment.is_locked ? "Yes" : "No",
  }));
  const filteredRows =
    filterBy === "None" || !searchValue
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "FullName"
          const cellValue = row[filterBy]; // نفس الاسم بالظبط لأن keys في rows مطابقة لـ FILTER_FIELD_MAP
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.toLowerCase());
        });
  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <Box className="people-header-wrapper">
          <Box className="people-header-icon-wrapper">
            <TodayIcon className="people-header-icon" />
          </Box>
          <Typography variant="h4" className="people-header-title">
            Manage All Appointments
          </Typography>
        </Box>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue("");
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">ID</TableCell>
                <TableCell className="people-table-head-cell">
                  L_A_ID.
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">title</TableCell>
                <TableCell className="people-table-head-cell">
                  className{" "}
                </TableCell>
                <TableCell className="people-table-head-cell">Date</TableCell>
                <TableCell className="people-table-head-cell">Fees </TableCell>
                <TableCell className="people-table-head-cell">
                  Fulfilled
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow key={row.Appointmentsid} className="people-table-row">
                  <TableCell className="people-table-cell-id">
                    {row.Appointmentsid}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.L_A_ID}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.FullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.title}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.className}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.Date}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.Fees}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.Fulfilled}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {rows.length}
          </Typography>
        </Box>
      </Paper>
    </Box>
  );
}
