import React from "react";
import { Box, Typography } from "@mui/material";

// ✅ بطاقة موحّدة لأي قسم "Info" يُعرض تحت الرخصة (Detain, DTN, Renew,
// International...) — نفس ستايل DetainInfoPanel بالضبط، بس عامة وقابلة
// لإعادة الاستخدام بدل تكرار نفس الـ header/grid بكل مكوّن
export default function InfoCard({ icon: Icon, title, children }) {
  return (
    <Box className="detain-info-card">
      <Box className="detain-info-card-header">
        {Icon && <Icon className="license-info-card-header-icon" />}
        <Typography className="license-info-card-title">{title}</Typography>
      </Box>
      <Box className="detain-info-fields-grid">{children}</Box>
    </Box>
  );
}
