import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Avatar,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import BadgeIcon from "@mui/icons-material/Badge";
import DirectionsCarIcon from "@mui/icons-material/DirectionsCar";
import PersonIcon from "@mui/icons-material/Person";
import FingerprintIcon from "@mui/icons-material/Fingerprint";
import WcIcon from "@mui/icons-material/Wc";
import EventIcon from "@mui/icons-material/Event";
import EventBusyIcon from "@mui/icons-material/EventBusy";
import AssignmentIcon from "@mui/icons-material/Assignment";
import NoteIcon from "@mui/icons-material/Note";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import CakeIcon from "@mui/icons-material/Cake";
import BadgeOutlinedIcon from "@mui/icons-material/BadgeOutlined";

import Field from "../Field";
import { getLicenses } from "../../Store/features/Licenses/LicensesSlice";
import { getApplicationByApplicationId } from "../../Store/features/Application/ApplicationSlice";
import { getPeople } from "../../Store/features/people/peopleSlice";
import { getLicenseClasses } from "../../Store/features/licenseClass/licenseClassSlice";
import { getApplicationTypes } from "../../Store/features/ApplicationType/ApplicationTypeSlice";
import { getDetainedLicenses } from "../../Store/features/DetainedLicenses/DetainedLicensesSlice"; // ⚠️ عدّل المسار حسب مكان الملف عندك

const formatDate = (isoDate) => {
  if (!isoDate) return "";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

// ✅ نفس منطق البيانات القديم بالضبط — بس الآن بتصميم البطاقة الموحّد
export function LicenseInfoContent({ licenseId }) {
  const dispatch = useDispatch();

  const license = useSelector((state) =>
    state.licenses.list.find((l) => l.license_id === licenseId),
  );

  const applications = useSelector((state) => state.applications.list);
  const application = applications.find(
    (a) => a.applicationID === license?.application_id,
  );

  const people = useSelector((state) => state.people.list);
  const person = people.find(
    (p) => p.person_id === application?.applicantPersonID,
  );

  const licenseClasses = useSelector((state) => state.LicenseClass.list);
  const licenseClass = licenseClasses.find((c) => {
    const cId = c.license_class_id ?? c.licenseClassID;
    return Number(cId) === Number(license?.license_class);
  });
  const licenseClassName = licenseClass?.class_name ?? licenseClass?.className;

  const applicationTypes = useSelector((state) => state.ApplicationType.list);
  const issueReason = applicationTypes.find(
    (t) => t.application_type_id === license?.issue_reason,
  );

  const detainedList = useSelector((state) => state.DetainedLicenses.list); // ⚠️ عدّل اسم الـ slice لو مختلف
  const isDetained = detainedList.some(
    (d) => d.licenseID === licenseId && !d.isReleased,
  );

  useEffect(() => {
    if (!licenseId) return;
    dispatch(getLicenses());
    dispatch(getLicenseClasses());
    dispatch(getPeople());
    dispatch(getApplicationTypes());
    dispatch(getDetainedLicenses());
  }, [licenseId, dispatch]);

  useEffect(() => {
    if (!license?.application_id || application) return;
    dispatch(getApplicationByApplicationId(license.application_id));
  }, [license?.application_id, application, dispatch]);

  const fullName = person
    ? [
        person.first_name,
        person.second_name,
        person.third_name,
        person.last_name,
      ]
        .filter(Boolean)
        .join(" ")
    : "";

  return (
    <Box className="license-info-card">
      <Box className="license-info-card-header">
        <BadgeOutlinedIcon className="license-info-card-header-icon" />
        <Typography className="license-info-card-title">
          DRIVER LICENSE INFO
        </Typography>
      </Box>

      <Box className="license-info-body">
        <Box className="license-info-fields-grid">
          <Field
            icon={DirectionsCarIcon}
            label="Class"
            value={licenseClassName}
          />
          <Field icon={PersonIcon} label="Name" value={fullName} />
          <Field
            icon={BadgeIcon}
            label="License ID"
            value={license?.license_id}
          />
          <Field
            icon={CheckCircleIcon}
            label="Is Active?"
            value={license ? (license.is_active ? "Yes" : "No") : undefined}
          />
          <Field
            icon={FingerprintIcon}
            label="National No"
            value={person?.national_no}
          />
          <Field icon={WcIcon} label="Gendor" value={person?.gendor_caption} />
          <Field
            icon={CakeIcon}
            label="Date Of Birth"
            value={formatDate(person?.date_of_birth)}
          />
          <Field
            icon={BadgeIcon}
            label="Driver ID"
            value={license?.driver_id}
          />
          <Field
            icon={EventIcon}
            label="Issue Date"
            value={formatDate(license?.issue_date)}
          />
          <Field
            icon={EventBusyIcon}
            label="Expiration Date"
            value={formatDate(license?.expiration_date)}
          />
          <Field
            icon={AssignmentIcon}
            label="Issue Reason"
            value={issueReason?.application_type_title}
          />
          <Field
            icon={CheckCircleIcon}
            label="Is Detained?"
            value={license ? (isDetained ? "Yes" : "No") : undefined}
          />
          <Field icon={NoteIcon} label="Notes" value={license?.notes} />
        </Box>

        <Avatar src={person?.image_path} className="license-info-avatar">
          {!person?.image_path && (
            <PersonIcon className="license-info-avatar-icon" />
          )}
        </Avatar>
      </Box>
    </Box>
  );
}

// ✅ الاستخدام القديم كـ Dialog كامل — بنفس تصميم modal-dialog الموحّد الآن
export default function ShowLicenseInfo({ open, onClose, licenseId }) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          Driver License Info
        </Typography>

        <LicenseInfoContent licenseId={open ? licenseId : null} />
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button
          variant="contained"
          startIcon={<CloseIcon />}
          onClick={onClose}
          className="modal-btn-cancel"
        >
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}
