import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  TextField,
  Radio,
  RadioGroup,
  FormControlLabel,
  Select,
  MenuItem,
  Avatar,
  Button,
} from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import PinIcon from "@mui/icons-material/Pin";
import MaleIcon from "@mui/icons-material/Male";
import FemaleIcon from "@mui/icons-material/Female";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import PhoneIcon from "@mui/icons-material/Phone";
import AlternateEmailIcon from "@mui/icons-material/AlternateEmail";
import PublicIcon from "@mui/icons-material/Public";
import HomeIcon from "@mui/icons-material/Home";
import { useSelector } from "react-redux";
import {
  updatePersonLocally,
  addPersonTolist,
  AddPerson,
  UpdatePerson,
} from "../../Store/features/people/peopleSlice";
import { useDispatch } from "react-redux";
import FeildAlert from "../../Popups/FailedAlert";
import { validatePersonForm } from "../../validations/validation";

export default function PersonFormPanel({
  mode = "add",
  person,
  onClose,
  onSave,
  onPhotoChange,
}) {
  const dispatch = useDispatch();
  const COUNTRIES = useSelector((state) => state.Country.list);
  const peopleList = useSelector((state) => state.people.list);

  const isUpdate = mode === "update";

  const [form, setForm] = useState({
    firstName: "",
    secondName: "",
    thirdName: "",
    lastName: "",
    nationalNo: "",
    dateOfBirth: "",
    gender: "Male",
    phone: "",
    email: "",
    country: "",
    address: "",
    photoUrl: "",
  });

  const [errors, setErrors] = useState({});
  const [touched, setTouched] = useState({});

  useEffect(() => {
    if (isUpdate && person) {
      setForm({
        personId: person.person_id ?? "—",
        firstName: person.first_name || "",
        secondName: person.second_name || "",
        thirdName: person.third_name || "",
        lastName: person.last_name || "",
        nationalNo: person.national_no || "",
        dateOfBirth: person.date_of_birth || "",
        gender: person.gendor_caption || "Male",
        phone: person.phone || "",
        email: person.email || "",
        country: person.nationality_country_id ?? "", // اسم الحقل الصحيح القادم من الـ API
        address: person.address || "",
        photoUrl: person.image_path || "",
      });
    }
  }, [isUpdate, person]);

  // بيانات موجودة مسبقاً لفحص التكرار — نجهزها بالشكل اللي validation.js متوقعه (id / nationalNo)
  const existingPeopleForValidation = peopleList
    .filter((p) => !isUpdate || p.person_id !== person?.person_id)
    .map((p) => ({
      id: p.person_id,
      nationalNo: p.national_no,
    }));

  // إعادة تشغيل التحقق فوراً مع أي تغيير في الفورم (real-time)
  useEffect(() => {
    const validationErrors = validatePersonForm(
      {
        ...form,
        nationality: form.country,
        id: isUpdate ? person?.person_id : null,
      },
      existingPeopleForValidation,
    );
    setErrors(validationErrors);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form]);

  const isFormValid = Object.keys(errors).length === 0;

  const handleChange = (field) => (e) => {
    setForm((prev) => ({ ...prev, [field]: e.target.value }));
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const handleSetImage = () => {
    if (onPhotoChange) onPhotoChange();
  };

  const showError = (field) => Boolean(touched[field] && errors[field]);
  const errorText = (field) => (touched[field] ? errors[field] || "" : "");

  const handleSave = () => {
    if (!isFormValid) {
      return <FeildAlert>Compleat All the Sentest</FeildAlert>;
    }

    const localPayload = {
      person_id: form.personId,
      first_name: form.firstName,
      second_name: form.secondName,
      third_name: form.thirdName,
      last_name: form.lastName,
      national_no: form.nationalNo,
      date_of_birth: form.dateOfBirth,
      gendor_caption: form.gender,
      phone: form.phone,
      email: form.email,
      country_name: form.country,
      address: form.address,
      image_path: form.photoUrl,
    };
    const apiPayload = {
      personID: form.personId || 0,
      firstName: form.firstName,
      secondName: form.secondName,
      thirdName: form.thirdName,
      lastName: form.lastName,
      nationalNo: form.nationalNo,
      dateOfBirth: form.dateOfBirth,
      gendor: form.gender === "Male" ? 1 : 2, // تأكد من القيم الصحيحة حسب الـ backend
      address: form.address,
      phone: form.phone,
      email: form.email,
      nationalityCountryID: form.country, // رقم دايمًا بكلا الحالتين add و update
      imagePath: form.photoUrl,
    };
    if (isUpdate) {
      dispatch(updatePersonLocally(localPayload));
      dispatch(UpdatePerson(apiPayload));
    } else {
      dispatch(addPersonTolist(localPayload));
      dispatch(AddPerson(apiPayload));
    }

    if (onSave) {
      onSave(form);
    }

    if (onClose) {
      onClose();
    }
  };

  if (!COUNTRIES) {
    return <div>Loading...</div>;
  }

  return (
    <Box>
      <Typography className="person-details-title" variant="h5" align="center">
        {isUpdate ? "Update Person" : "Add New Person"}
      </Typography>

      <Box
        className="profile-readonly-row"
        sx={{ justifyContent: "center", mb: 2 }}
      >
        <PinIcon className="profile-readonly-icon" />
        <Typography className="profile-readonly-label">Person ID :</Typography>
        <Typography className="profile-readonly-value">
          {isUpdate ? (person?.person_id ?? "—") : "N/A"}
        </Typography>
      </Box>

      <Box className="person-form-grid">
        <Box className="person-form-fields">
          <Box>
            <Typography className="person-form-label">Name:</Typography>
            <Box className="person-form-row">
              <PersonIcon className="submenu-accent-icon" />
              <TextField
                className="modal-textfield"
                label="First"
                value={form.firstName}
                onChange={handleChange("firstName")}
                error={showError("firstName")}
                helperText={errorText("firstName")}
                fullWidth
                size="small"
              />
              <TextField
                className="modal-textfield"
                label="Second"
                value={form.secondName}
                onChange={handleChange("secondName")}
                error={showError("secondName")}
                helperText={errorText("secondName")}
                fullWidth
                size="small"
              />
              <TextField
                className="modal-textfield"
                label="Third"
                value={form.thirdName}
                onChange={handleChange("thirdName")}
                fullWidth
                size="small"
              />
              <TextField
                className="modal-textfield"
                label="Last"
                value={form.lastName}
                onChange={handleChange("lastName")}
                fullWidth
                size="small"
              />
            </Box>
          </Box>

          <Box className="person-form-row">
            <PinIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="National No"
              value={form.nationalNo}
              onChange={handleChange("nationalNo")}
              error={showError("nationalNo")}
              helperText={errorText("nationalNo")}
              fullWidth
              size="small"
            />

            <CalendarTodayIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="Date Of Birth"
              type="date"
              InputLabelProps={{ shrink: true }}
              value={form.dateOfBirth}
              onChange={handleChange("dateOfBirth")}
              error={showError("dateOfBirth")}
              helperText={errorText("dateOfBirth")}
              fullWidth
              size="small"
            />
          </Box>

          <Box className="person-form-row">
            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
              {form.gender === "Female" ? (
                <FemaleIcon className="submenu-accent-icon" />
              ) : (
                <MaleIcon className="submenu-accent-icon" />
              )}
              <RadioGroup
                row
                value={form.gender}
                onChange={handleChange("gender")}
                sx={{ flexWrap: "nowrap" }}
              >
                <FormControlLabel
                  value="Male"
                  control={<Radio size="small" />}
                  label="Male"
                />
                <FormControlLabel
                  value="Female"
                  control={<Radio size="small" />}
                  label="Female"
                />
              </RadioGroup>
            </Box>

            <PhoneIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="Phone"
              type="tel"
              value={form.phone}
              onChange={handleChange("phone")}
              error={showError("phone")}
              helperText={errorText("phone")}
              size="small"
              fullWidth
              sx={{ maxWidth: 180 }}
            />
          </Box>

          <Box className="person-form-row">
            <AlternateEmailIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="Email"
              value={form.email}
              onChange={handleChange("email")}
              error={showError("email")}
              helperText={errorText("email")}
              fullWidth
              size="small"
            />

            <PublicIcon className="submenu-accent-icon" />
            <Select
              className="modal-textfield"
              value={form.country}
              onChange={handleChange("country")}
              displayEmpty
              fullWidth
              size="small"
              error={showError("nationality")}
            >
              <MenuItem value="">
                <em>Country</em>
              </MenuItem>
              {COUNTRIES.map((c) => (
                <MenuItem key={c.country_id} value={c.country_id}>
                  {c.country_name}
                </MenuItem>
              ))}
            </Select>
          </Box>

          <Box>
            <Typography className="person-form-label">
              <HomeIcon
                className="submenu-accent-icon"
                sx={{ fontSize: "1rem", verticalAlign: "middle", mr: 0.5 }}
              />
              Address:
            </Typography>
            <TextField
              className="modal-textfield"
              value={form.address}
              onChange={handleChange("address")}
              fullWidth
              multiline
              rows={3}
            />
          </Box>
        </Box>

        <Box className="person-form-photo-col">
          <Avatar className="person-form-avatar" src={form.photoUrl}>
            <PersonIcon className="person-form-avatar-icon" />
          </Avatar>
          <Button
            className="person-form-set-image-btn"
            onClick={handleSetImage}
          >
            Set Image
          </Button>
        </Box>
      </Box>

      <Box
        className="modal-actions"
        sx={{ display: "flex", justifyContent: "flex-end", gap: 2 }}
      >
        <Button onClick={onClose} className="modal-btn-cancel">
          Close
        </Button>
        <Button
          onClick={handleSave}
          className="modal-btn-save"
          variant="contained"
          disabled={!isFormValid}
        >
          Save
        </Button>
      </Box>
    </Box>
  );
}
