import React from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";

// TODO: سيُبنى المحتوى الكامل (الفورم + الحفظ عبر Redux/API) لاحقًا
// حاليًا Component فقط بلا منطق، بانتظار ربط الـ RESTful API
export default function AddLocalDrivingLicenseApplication({ open, onClose }) {
  const handleSave = () => {
    // لاحقاً هنا فقط: dispatch(...)
    onClose();
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="sm"
      className="modal-dialog"
    >
      <DialogTitle className="modal-title">
        New Local Driving License Application
      </DialogTitle>
      <DialogContent className="modal-content">
        {/* الفورم يُبنى لاحقًا */}
      </DialogContent>
      <DialogActions className="modal-actions">
        <Button onClick={onClose} className="modal-btn-cancel">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          className="modal-btn-save"
          variant="contained"
        >
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
}
