import React from "react";
import {
  Box,
  Typography,
  Select,
  MenuItem,
  FormControl,
  TextField,
} from "@mui/material";

export default function Filter({
  label = "Filter By:",
  fieldMap = {},
  value,
  onChange,
  searchValue,
  onSearchChange,
}) {
  return (
    <Box
      className="people-filter-wrapper"
      sx={{ display: "flex", gap: 2, alignItems: "center" }}
    >
      <Typography className="people-filter-label">{label}</Typography>
      <FormControl size="small">
        <Select
          value={value}
          onChange={onChange}
          className="people-filter-select"
        >
          <MenuItem value="None">None</MenuItem>
          {Object.keys(fieldMap).map((key) => (
            <MenuItem key={key} value={key}>
              {key}
            </MenuItem>
          ))}
        </Select>
      </FormControl>

      {/* التكست بوكس بيظهر بس لو المستخدم اختار حقل فعلي */}
      {value !== "None" && (
        <TextField
          size="small"
          placeholder={`Search by ${value}...`}
          value={searchValue}
          onChange={onSearchChange}
        />
      )}
    </Box>
  );
}
