import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import PublicIcon from "@mui/icons-material/Public";
import { Box as MuiBox, Typography } from "@mui/material";
//*************Loading Tools */
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
//*************Loading Tools */

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { getAllInternationalDrivingLicenses } from "../Store/features/InternationalDrivingLicense/InternationalDrivingLicenseSlice";

import Filter from "../Shared/Filter";
import IssueInternationalLicenseModal from "../Shared/Application/IssueInternationalLicenseModal";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  AppID: "id",
  ApplicationID: "applicationId",
  DriverID: "driverId",
  LicenseID: "licenseid",
  IsActive: "isactive",
};

// شاشة Manage International License Applications — Component عرض فقط (صفحة كاملة، ليست Dialog)
export default function ManageInternationalLicenseApplicationsScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");
  const dispatch = useDispatch();
  const [isIssueInternationalOpen, setIsIssueInternationalOpen] =
    useState(false);
  // useSelector: بيقرأ فقط الجزء الخاص بـ InternationalDrivingLicense من الـ state الكلي
  const InternationalDrivingLicense = useSelector(
    (state) => state.InternationalDrivingLicense.list,
  );
  const status = useSelector(
    (state) => state.InternationalDrivingLicense.status,
  );
  const error = useSelector((state) => state.InternationalDrivingLicense.error);

  useEffect(() => {
    dispatch(getAllInternationalDrivingLicenses());
  }, [dispatch]);

  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }

  const rows = InternationalDrivingLicense.map((license) => ({
    id: license.international_license_id,
    driverId: license.driver_id,
    applicationId: license.application_id,
    licenseid: license.license_id,
    issueDate: license.issue_date,
    expirationDate: license.expiration_date,
    isactive: license.is_active ? "Yes" : "No",
    createdbyuser: license.created_by_user_id,
  }));

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "driverId"
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <MuiBox className="people-header-wrapper">
          <MuiBox className="people-header-icon-wrapper">
            <PublicIcon className="people-header-icon" />
          </MuiBox>
          <Typography variant="h4" className="people-header-title">
            International License Applications
          </Typography>
        </MuiBox>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setIsIssueInternationalOpen(true)}
            className="people-add-btn"
          >
            New Application
          </Button>
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  I.L.AppID
                </TableCell>

                <TableCell className="people-table-head-cell">
                  Application ID
                </TableCell>

                <TableCell className="people-table-head-cell">
                  Driver ID
                </TableCell>

                <TableCell className="people-table-head-cell">
                  License ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Issue Date
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Expiration Date
                </TableCell>

                <TableCell className="people-table-head-cell">
                  Is Active
                </TableCell>

                <TableCell className="people-table-head-cell">
                  Created By User
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow key={row.id} className="people-table-row">
                  <TableCell className="people-table-cell-id">
                    {row.id}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.applicationId}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.driverId}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.licenseid}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.issueDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.expirationDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.isactive}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.createdbyuser}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>
      </Paper>

      <IssueInternationalLicenseModal
        open={isIssueInternationalOpen}
        onClose={() => setIsIssueInternationalOpen(false)}
      />
    </Box>
  );
}
