import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  error: null,
};

export const getTestTypes = createAsyncThunk(
  "TestTypes/getTestTypes",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/TestTypes",
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { TestTypes } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (TestTypes.status === "loading" || TestTypes.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);
export const getTestTypesById = createAsyncThunk(
  "TestTypes/getTestTypesById",
  async (testTypeId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/TestTypes/${testTypeId}`,
    );
    return response.data; // الـ response عبارة عن object حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { TestTypes } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (TestTypes.status === "loading" || TestTypes.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);

const testTypesSlice = createSlice({
  name: "TestTypes",
  initialState,
  reducers: {},
  // extraReducers: هون بنتعامل مع الأكشنز اللي جاية من الـ thunk (خارجية عن reducers العادية)
  extraReducers: (builder) => {
    builder
      .addCase(getTestTypes.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getTestTypes.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getTestTypes.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(getTestTypesById.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getTestTypesById.fulfilled, (state, action) => {
        state.status = "succeeded";
        const index = state.list.findIndex(
          (t) => t.testTypeID === action.payload.testTypeID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        } else {
          state.list.push(action.payload);
        } // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getTestTypesById.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

export default testTypesSlice.reducer;
