import React, { useState, useEffect, memo } from "react";
import Dialog from "@mui/material/Dialog";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import Button from "@mui/material/Button";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import { useSelector, useDispatch } from "react-redux";
import ShowAppointment from "../Shared//Appointment/ShowAppointment";
import ShowApplicationInfo from "../Shared/Application/Showapplicationinfo";
import IssueDrivingLicense from "../Shared/License/IssueDrivingLicense";
import ShowLicenseInfo from "../Shared/License/Showlicenseinfo";
import AddTest from "../Add/AddTest";
import { getLicenses } from "../Store/features/Licenses/LicensesSlice";
import { Link } from "react-router-dom";
import Alert from "@mui/material/Alert";

import { deleteLocalDrivingLicenseApplication } from "../Store/features/LocalDrivingLicense/LocalDrivingLicenseSlice";
import { CanseldApplicationStatus } from "../Store/features/Application/ApplicationSlice";

// ⚠️ عدّل هذا الرقم حسب القيمة الفعلية لحالة "Cancelled" بالـ backend عندك
const CANCELLED_STATUS_VALUE = 2;

const LocalDrivingLicenseApplicationDetailsModal = ({
  localApplicationId,
  open,
  onClose,
}) => {
  const dispatch = useDispatch();

  const listRow = useSelector((state) =>
    state.LocalDrivingLicense.list.find(
      (l) => l.local_driving_license_application_id === localApplicationId,
    ),
  );

  const selectedInfo = useSelector(
    (state) => state.LocalDrivingLicense.selectedInfo,
  );

  const licensesList = useSelector((state) => state.licenses.list);

  const passedTests = listRow?.passed_test_count ?? 0;
  const isCompleted = passedTests >= 3;

  // ✅ فحص جديد: هل الطلب ملغى (Cancelled)؟
  // ⚠️ عدّل اسم الحقل (application_status) والقيمة لو مختلفين عندك
  const isCancelled =
    listRow?.application_status === CANCELLED_STATUS_VALUE ||
    selectedInfo?.applicationStatus === CANCELLED_STATUS_VALUE;

  const matchedLicense = licensesList.find(
    (l) => l.application_id === selectedInfo?.applicationID,
  );
  const licenseId = matchedLicense?.license_id ?? null;
  const hasLicense = !!licenseId;

  useEffect(() => {
    dispatch(getLicenses());
  }, [dispatch]);

  const [isAddTestOpen, setIsAddTestOpen] = useState(false);
  const [isShowAppointmentOpen, setIsShowAppointmentOpen] = useState(false);
  const [isIssueOpen, setIsIssueOpen] = useState(false);
  const [isShowLicenseOpen, setIsShowLicenseOpen] = useState(false);

  const [alertMsg, setAlertMsg] = useState(null);

  const anyChildOpen =
    isAddTestOpen || isShowAppointmentOpen || isIssueOpen || isShowLicenseOpen;

  const handleDelete = () => {
    if (isCancelled) return; // ✅ حماية إضافية على مستوى المنطق، مو بس تعطيل الزر بصريًا
    if (window.confirm("Are you sure you want to delete this application?")) {
      if (selectedInfo !== null) {
        dispatch(
          deleteLocalDrivingLicenseApplication(
            selectedInfo.localDrivingLicenseApplicationID,
          ),
        )
          .unwrap()
          .then(() => {
            setAlertMsg({
              type: "success",
              text: "Application deleted successfully ✅",
            });
            setTimeout(() => {
              setAlertMsg(null);
              onClose();
            }, 2000);
          })
          .catch(() => {
            setAlertMsg({
              type: "error",
              text: "Failed to delete application ❌",
            });
          });
      }
    }
  };

  const handleCanseld = () => {
    if (isCancelled) return;
    if (window.confirm("Are you sure you want to cancel this application?")) {
      if (selectedInfo !== null) {
        dispatch(CanseldApplicationStatus(selectedInfo.applicationID))
          .unwrap()
          .then(() => {
            setAlertMsg({
              type: "success",
              text: "Application canceled successfully ✅",
            });
            setTimeout(() => {
              setAlertMsg(null);
              onClose();
            }, 2000);
          })
          .catch(() => {
            setAlertMsg({
              type: "error",
              text: "Failed to cancel application ❌",
            });
          });
      }
    }
  };

  const handelAddTest = () => {
    if (isCancelled) return;
    setIsAddTestOpen(true);
  };

  return (
    <>
      <Dialog
        open={open && !anyChildOpen}
        onClose={onClose}
        maxWidth="md"
        fullWidth
      >
        <Box sx={{ display: "flex", justifyContent: "flex-end", p: 1 }}>
          <IconButton onClick={onClose} size="small">
            <CloseIcon fontSize="small" />
          </IconButton>
        </Box>

        <DialogContent sx={{ pt: 0 }}>
          {alertMsg && (
            <Alert
              severity={alertMsg.type}
              variant="filled"
              sx={{ mb: 2 }}
              onClose={() => setAlertMsg(null)}
            >
              {alertMsg.text}
            </Alert>
          )}

          {/* ✅ تنبيه واضح لما الطلب يكون ملغى */}
          {isCancelled && (
            <Alert severity="warning" variant="filled" sx={{ mb: 2 }}>
              This application has been cancelled. No further actions are
              available.
            </Alert>
          )}

          <ShowApplicationInfo localApplicationId={localApplicationId} />
        </DialogContent>

        {/* ✅ لو ملغى: ما نعرض أي أزرار إجراءات إطلاقًا، غير Show Appointment
            كخيار عرض معلومات بس (اختياري تركه أو تعطيله كمان — حاليًا مُبقى شغال
            لأنه لا يغيّر حالة الطلب، فقط يعرض مواعيد) */}
        {!isCancelled && (
          <DialogActions
            sx={{ flexWrap: "wrap", gap: 1, justifyContent: "center", p: 2 }}
          >
            <Button
              variant="outlined"
              color="error"
              disabled={hasLicense}
              onClick={handleDelete}
            >
              Delete Application
            </Button>
            <Button
              variant="outlined"
              color="warning"
              disabled={hasLicense}
              onClick={handleCanseld}
            >
              Cancel Application
            </Button>
            <Button
              variant="contained"
              onClick={handelAddTest}
              disabled={isCompleted || hasLicense}
            >
              Add Test
            </Button>
            <Button
              variant="outlined"
              onClick={() => setIsIssueOpen(true)}
              disabled={!isCompleted || hasLicense}
            >
              Issue Driving License (First Time)
            </Button>
            <Button
              variant="outlined"
              onClick={() => setIsShowLicenseOpen(true)}
              disabled={!hasLicense}
            >
              Show License
            </Button>
            {selectedInfo && (
              <Link
                to={`/manage-Licenses`}
                style={{ textDecoration: "none" }}
                state={{ FullName: selectedInfo.applicantFullName }}
              >
                <Button variant="outlined" disabled={!hasLicense}>
                  Show Person License History
                </Button>
              </Link>
            )}
            <Button
              variant="outlined"
              onClick={() => setIsShowAppointmentOpen(true)}
            >
              Show Appointment
            </Button>
          </DialogActions>
        )}
      </Dialog>

      {!isCancelled && selectedInfo?.applicantPersonID !== undefined && (
        <AddTest
          PersonId={selectedInfo.applicantPersonID}
          localDrivingLicenseApplicationID={localApplicationId}
          open={isAddTestOpen}
          onClose={() => setIsAddTestOpen(false)}
        />
      )}
      {!isCancelled && (
        <ShowAppointment
          localDrivingLicenseApplicationID={localApplicationId}
          open={isShowAppointmentOpen}
          onClose={() => setIsShowAppointmentOpen(false)}
        />
      )}
      {!isCancelled && (
        <IssueDrivingLicense
          localApplicationId={localApplicationId}
          open={isIssueOpen}
          onClose={() => setIsIssueOpen(false)}
        />
      )}
      {!isCancelled && (
        <ShowLicenseInfo
          licenseId={licenseId}
          open={isShowLicenseOpen}
          onClose={() => setIsShowLicenseOpen(false)}
        />
      )}
    </>
  );
};

export default memo(LocalDrivingLicenseApplicationDetailsModal);
