import React, { useEffect, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import Dialog from "@mui/material/Dialog";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import Button from "@mui/material/Button";
import Table from "@mui/material/Table";
import TableHead from "@mui/material/TableHead";
import TableBody from "@mui/material/TableBody";
import TableRow from "@mui/material/TableRow";
import TableCell from "@mui/material/TableCell";
import Checkbox from "@mui/material/Checkbox";
import DescriptionIcon from "@mui/icons-material/Description";
import CardMembershipIcon from "@mui/icons-material/CardMembership";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import BadgeIcon from "@mui/icons-material/Badge";
import FlagIcon from "@mui/icons-material/Flag";
import AttachMoneyIcon from "@mui/icons-material/AttachMoney";
import CategoryIcon from "@mui/icons-material/Category";
import PersonIcon from "@mui/icons-material/Person";
import EventIcon from "@mui/icons-material/Event";
import EventAvailableIcon from "@mui/icons-material/EventAvailable";
import PersonPinIcon from "@mui/icons-material/PersonPin";

import InfoCard from "../InfoCard";
import Field from "../Field";
import { getTestAppointmentsByLocalDrivingLicenseApplicationID } from "../../Store/features/TestAppointments/TestAppointmentsSlice";
import { TEST_SECTIONS } from "../../constants/testSections";
import TestResultModal from "../Tests/TestResultModal";

const ShowAppointment = ({
  localDrivingLicenseApplicationID,
  open,
  onClose,
}) => {
  const dispatch = useDispatch();
  const lastFetchedKey = useRef(null);
  const [selectedAppointment, setSelectedAppointment] = useState(null);

  const selectedInfo = useSelector(
    (state) => state.LocalDrivingLicense.selectedInfo,
  );

  const application = useSelector((state) =>
    state.applications.list.find(
      (a) => a.applicationID === selectedInfo?.applicationID,
    ),
  );

  const licenseClass = useSelector((state) =>
    state.LicenseClass.list.find(
      (c) => c.license_class_id === selectedInfo?.licenseClassID,
    ),
  );
  const User = useSelector((state) =>
    state.users.list.find((u) => u.user_id === selectedInfo?.createdByUserID),
  );
  const listRow = useSelector((state) =>
    state.LocalDrivingLicense.list.find(
      (l) =>
        l.local_driving_license_application_id ===
        localDrivingLicenseApplicationID,
    ),
  );

  const appointments = useSelector(
    (state) => state.testAppointments.byApplication,
  );
  const appointmentsStatus = useSelector(
    (state) => state.testAppointments.byApplicationStatus,
  );

  const passedTestsCount = listRow?.passed_test_count ?? 0;
  const activeSection =
    passedTestsCount < TEST_SECTIONS.length
      ? TEST_SECTIONS[passedTestsCount]
      : null;
  const testType = activeSection?.testTypeId;

  useEffect(() => {
    if (!open || !localDrivingLicenseApplicationID || !testType) return;

    const key = `${localDrivingLicenseApplicationID}-${testType}`;
    if (lastFetchedKey.current === key) return;
    lastFetchedKey.current = key;

    dispatch(
      getTestAppointmentsByLocalDrivingLicenseApplicationID({
        localDrivingLicenseApplicationID,
        testType,
      }),
    );
  }, [open, localDrivingLicenseApplicationID, testType, dispatch]);

  if (!selectedInfo) {
    return (
      <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
        <DialogContent>
          <Typography>Loading...</Typography>
        </DialogContent>
      </Dialog>
    );
  }

  const statusText = listRow?.application_status ?? selectedInfo.statusText;
  const fees = application?.paidFees ?? selectedInfo.paidFees;
  const statusDate = (
    application?.lastStatusDate ?? selectedInfo.lastStatusDate
  )?.split("T")[0];
  const applicationDate = (
    application?.applicationDate ?? selectedInfo.applicationDate
  )?.split("T")[0];

  return (
    <>
      <Dialog
        open={open && !selectedAppointment}
        onClose={onClose}
        maxWidth="md"
        fullWidth
        className="modal-dialog"
      >
        <Box sx={{ display: "flex", justifyContent: "flex-end", p: 1 }}>
          <IconButton onClick={onClose} size="small">
            <CloseIcon fontSize="small" />
          </IconButton>
        </Box>

        <DialogContent className="modal-content" sx={{ pt: 0 }}>
          <InfoCard
            icon={DescriptionIcon}
            title="DRIVING LICENSE APPLICATION INFO"
          >
            <Field
              icon={DescriptionIcon}
              label="D.L.App ID"
              value={selectedInfo.localDrivingLicenseApplicationID}
            />
            <Field
              icon={CardMembershipIcon}
              label="Applied For License"
              value={licenseClass?.class_name}
            />
            <Field
              icon={CheckCircleIcon}
              label="Passed Tests"
              value={`${passedTestsCount}/3`}
            />
          </InfoCard>

          <InfoCard icon={BadgeIcon} title="APPLICATION BASIC INFO">
            <Field
              icon={BadgeIcon}
              label="ID"
              value={selectedInfo.applicationID}
            />
            <Field icon={EventIcon} label="Date" value={applicationDate} />
            <Field icon={FlagIcon} label="Status" value={statusText} />
            <Field
              icon={EventAvailableIcon}
              label="Status Date"
              value={statusDate}
            />
            <Field icon={AttachMoneyIcon} label="Fees" value={fees} />
            <Field
              icon={PersonIcon}
              label="Created By"
              value={User?.user_name}
            />
            <Field
              icon={CategoryIcon}
              label="Type"
              value="New Local Driving License Service"
            />
            <Field
              icon={PersonPinIcon}
              label="Applicant"
              value={selectedInfo.applicantFullName}
            />
          </InfoCard>

          <Box sx={{ mt: 2 }}>
            <Typography className="license-info-card-title" sx={{ mb: 1 }}>
              APPOINTMENTS
            </Typography>

            <Box sx={{ display: "flex", gap: 3, alignItems: "center", mb: 1 }}>
              {TEST_SECTIONS.map((section) => {
                const Icon = section.icon;
                const isActive =
                  section.testTypeId === activeSection?.testTypeId;
                return (
                  <Box
                    key={section.testTypeId}
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                      opacity: isActive ? 1 : 0.35,
                    }}
                  >
                    <Icon
                      sx={{ fontSize: 32 }}
                      color={isActive ? "primary" : "disabled"}
                    />
                    <Typography
                      variant="caption"
                      sx={{ fontWeight: isActive ? 700 : 400 }}
                    >
                      {section.label}
                    </Typography>
                  </Box>
                );
              })}
            </Box>

            {activeSection ? (
              <Typography variant="subtitle2" sx={{ mb: 1 }}>
                Current Test: {activeSection.label}
              </Typography>
            ) : (
              <Typography color="text.secondary" sx={{ mb: 1 }}>
                All 3 tests passed — no test remaining.
              </Typography>
            )}

            {activeSection && appointmentsStatus === "loading" && (
              <Typography color="text.secondary">Loading...</Typography>
            )}

            {activeSection && appointmentsStatus === "succeeded" && (
              <>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Appointment ID</TableCell>
                      <TableCell>Appointment Date</TableCell>
                      <TableCell>Paid Fees</TableCell>
                      <TableCell>Is Locked</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {appointments.map((appt) => (
                      <TableRow
                        key={appt.test_appointment_id}
                        hover={!appt.is_locked}
                        onDoubleClick={() => {
                          if (!appt.is_locked) {
                            setSelectedAppointment(appt);
                          }
                        }}
                        sx={{
                          cursor: appt.is_locked ? "default" : "pointer",
                        }}
                      >
                        <TableCell>{appt.test_appointment_id}</TableCell>
                        <TableCell>
                          {appt.appointment_date?.split("T")[0]}
                        </TableCell>
                        <TableCell>{appt.paid_fees}</TableCell>
                        <TableCell>
                          <Checkbox checked={!!appt.is_locked} disabled />
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
                <Typography variant="caption" sx={{ mt: 1, display: "block" }}>
                  # Records: {appointments.length}
                </Typography>
              </>
            )}
          </Box>
        </DialogContent>

        <DialogActions
          className="modal-actions"
          sx={{ justifyContent: "center", p: 2 }}
        >
          <Button
            variant="contained"
            onClick={onClose}
            className="modal-btn-cancel"
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>

      <TestResultModal
        open={!!selectedAppointment}
        onClose={() => setSelectedAppointment(null)}
        appointment={selectedAppointment}
        section={activeSection}
        localDrivingLicenseApplicationID={localDrivingLicenseApplicationID}
      />
    </>
  );
};

export default ShowAppointment;
