// validations/validation.js
// دوال تحقق (validation) عامة قابلة لإعادة الاستخدام في أي فورم بالمشروع
// كل دالة تُرجع string (رسالة الخطأ) أو "" إن كانت القيمة صحيحة

export function validateRequired(value, fieldLabel) {
  if (!value || !String(value).trim()) {
    return `${fieldLabel} is required`;
  }
  return "";
}
export function validateAppointmentDate(value) {
  if (!value) return "Appointment date is required";
  const selected = new Date(value);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  selected.setHours(0, 0, 0, 0);
  if (selected < today) {
    return "Appointment date cannot be in the past";
  }
  return "";
}
// يجب أن يكون الإيميل بصيغة صحيحة و@gmail.com تحديداً
export function validateEmail(value) {
  if (!value) return "";
  const gmailRegex = /^[^\s@]+@gmail\.com$/i;
  return gmailRegex.test(value)
    ? ""
    : "Email must be a valid @gmail.com address";
}

// رقم الهاتف: 12 خانة على الأقل (أرقام فقط)
export function validatePhone(value) {
  if (!value) return "";
  const digitsOnly = value.replace(/\D/g, "");
  if (digitsOnly.length < 10) {
    return "Phone number must be at least 12 digits include Your Country Code";
  }
  return "";
}

// يُزيل أي حروف (مثل بادئة "N") ويُبقي الأرقام فقط
export function normalizeNationalNo(value) {
  if (!value) return "";
  return String(value).replace(/\D/g, "");
}

// التحقق من عدم تكرار National Number بين الأشخاص الموجودين
// excludeId: يُستخدم وقت الـ Update عشان الشخص ميتقارنش بنفسه
export function validateUniqueNationalNo(
  value,
  existingPeople,
  excludeId = null,
) {
  if (!value) return "";
  const target = normalizeNationalNo(value);
  const duplicate = existingPeople.some(
    (p) => normalizeNationalNo(p.nationalNo) === target && p.id !== excludeId,
  );
  return duplicate ? "This National Number is already registered" : "";
}

export function validateDateOfBirth(value) {
  if (!value) return "";
  const date = new Date(value);
  const today = new Date();
  if (date > today) return "Date of birth cannot be in the future";
  return "";
}

// يحسب العمر بدقة (بالسنة/الشهر/اليوم) للتأكد من إتمام 18 سنة كاملة
export function calculateAge(dateOfBirth) {
  const dob = new Date(dateOfBirth);
  const today = new Date();

  let age = today.getFullYear() - dob.getFullYear();
  const monthDiff = today.getMonth() - dob.getMonth();
  const dayDiff = today.getDate() - dob.getDate();

  if (monthDiff < 0 || (monthDiff === 0 && dayDiff < 0)) {
    age--;
  }

  return age;
}

// يجب أن يكون عمر الشخص 18 سنة فأكثر
export function validateAge(dateOfBirth) {
  if (!dateOfBirth) return "";
  const age = calculateAge(dateOfBirth);
  if (age < 18) {
    return "Person must be at least 18 years old";
  }
  return "";
}

// دالة تجميعية: تُشغّل كل قواعد فورم Add/Update Person وتُرجع object أخطاء
// formData.id: مطلوب وقت الـ Update فقط، عشان نستثني الشخص نفسه من فحص التكرار
export function validatePersonForm(formData, existingPeople) {
  const errors = {};

  errors.firstName = validateRequired(formData.firstName, "First Name");
  errors.secondName = validateRequired(formData.secondName, "Second Name");
  errors.nationalNo =
    validateRequired(formData.nationalNo, "National Number") ||
    validateUniqueNationalNo(formData.nationalNo, existingPeople, formData.id);
  errors.dateOfBirth =
    validateRequired(formData.dateOfBirth, "Date of Birth") ||
    validateDateOfBirth(formData.dateOfBirth) ||
    validateAge(formData.dateOfBirth);
  errors.gender = validateRequired(formData.gender, "Gender");
  errors.phone =
    validateRequired(formData.phone, "Phone") || validatePhone(formData.phone);
  errors.email =
    validateRequired(formData.email, "Email") || validateEmail(formData.email);
  errors.nationality = validateRequired(formData.nationality, "Country");

  Object.keys(errors).forEach((key) => {
    if (!errors[key]) delete errors[key];
  });

  return errors;
}

export function validateUserForm(formData) {
  const errors = {};

  errors.userName = validateRequired(formData.userName, "Username");
  errors.password = validateRequired(formData.password, "Password");
  if (formData.password && formData.password.length < 6) {
    errors.password = "Password must be at least 6 characters";
  }

  if (!formData.confirmPassword) {
    errors.confirmPassword = "Confirm Password is required";
  } else if (formData.password !== formData.confirmPassword) {
    errors.confirmPassword = "Passwords do not match";
  }

  Object.keys(errors).forEach((key) => {
    if (!errors[key]) delete errors[key];
  });

  return errors;
}

export function validateChangePasswordForm(formData) {
  const errors = {};

  errors.currentPassword = validateRequired(
    formData.currentPassword,
    "Current Password",
  );

  errors.newPassword = validateRequired(formData.newPassword, "New Password");
  if (formData.newPassword && formData.newPassword.length < 6) {
    errors.newPassword = "Password must be at least 6 characters";
  }

  if (!formData.confirmPassword) {
    errors.confirmPassword = "Confirm Password is required";
  } else if (formData.newPassword !== formData.confirmPassword) {
    errors.confirmPassword = "Passwords do not match";
  }

  if (
    formData.currentPassword &&
    formData.newPassword &&
    formData.currentPassword === formData.newPassword
  ) {
    errors.newPassword = "New password must be different from current password";
  }

  Object.keys(errors).forEach((key) => {
    if (!errors[key]) delete errors[key];
  });

  return errors;
}

export function validateLoginForm(formData) {
  const errors = {};
  errors.userName = validateRequired(formData.userName, "Username");
  errors.password = validateRequired(formData.password, "Password");

  Object.keys(errors).forEach((key) => {
    if (!errors[key]) delete errors[key];
  });

  return errors;
}
