import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  currentUser: null, // لتخزين بيانات المستخدم الحالي بعد تسجيل الدخول
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  addStatus: "idle",
  deletingstatus: "idle",
  updatingstatus: "idle",
  error: null,
};

export const getAllUsers = createAsyncThunk(
  "users/getAllUsers",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/Users",
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { users } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (users.status === "loading" || users.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);
export const getUserByID = createAsyncThunk(
  "users/getUserByID",
  async (id) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Users/${id}`,
    );
    return response.data; // الـ response عبارة عن object حسب الـ Swagger
  },
  {
    condition: (id, { getState }) => {
      const { users } = getState();
      const exists = users.list.some((u) => u.user_id === id);
      if (exists) return false; // ✅ موجود أصلاً، ألغِ الطلب وأعطِ الـ list الحالي فوراً
      return true;
    },
  },
);
export const getUserByPersonID = createAsyncThunk(
  "users/getUserByPersonID",
  async (id) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Users/${id}`,
    );
    return response.data; // الـ response عبارة عن object حسب الـ Swagger
  },
);
export const getUserByPasswordAndUsername = createAsyncThunk(
  "users/getUserByPasswordAndUsername",
  async (credentials) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Users/login?username=${credentials.username}&password=${credentials.password}`,
    );
    return response.data; // الـ response عبارة عن object حسب الـ Swagger
  },
);
export const addUserAsync = createAsyncThunk(
  "users/addUserAsync",
  async (user, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/Users/",
        user,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(err.response?.data?.message || "Add user failed");
    }
  },
);
export const DeleteUser = createAsyncThunk(
  "users/DeleteUser",
  async (userId, { rejectWithValue }) => {
    try {
      const response = await axios.delete(
        `https://idnan820-001-site1.ltempurl.com/api/Users/${userId}`,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(err.response?.data?.message || "Delete failed");
    }
  },
);
export const UpdateUser = createAsyncThunk(
  "users/UpdateUser",
  async (user, { rejectWithValue }) => {
    try {
      const response = await axios.put(
        `https://idnan820-001-site1.ltempurl.com/api/Users/${user.userID}`,
        user,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(err.response?.data?.message || "Update failed");
    }
  },
);
const Userlice = createSlice({
  name: "users",
  initialState,
  reducers: {
    addUser: (state, action) => {
      // action.payload لازم يكون object للشخص المراد إضافته
      state.list.push(action.payload);
    },
    resetAddUserStatus: (state) => {
      state.addStatus = "idle";
    },
    resetDeleteUserStatus: (state) => {
      state.deletingstatus = "idle";
    },
    updateUserLocally: (state, action) => {
      const index = state.list.findIndex(
        (u) => u.user_id === action.payload.user_id,
      );
      if (index !== -1) {
        state.list[index] = action.payload;
      }
    },
    resetUpdateUserStatus: (state) => {
      state.updatingstatus = "idle";
    },
  },
  // extraReducers: هون بنتعامل مع الأكشنز اللي جاية من الـ thunk (خارجية عن reducers العادية)
  extraReducers: (builder) => {
    builder
      .addCase(getAllUsers.pending, (state) => {
        state.status = "loading";

        state.error = null;
      })
      .addCase(getAllUsers.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im user done");
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getAllUsers.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(getUserByPasswordAndUsername.pending, (state) => {
        console.log("getUserByPasswordAndUsername.pending");
        state.status = "loading";
        state.error = null;
      })
      .addCase(getUserByPasswordAndUsername.fulfilled, (state, action) => {
        console.log("getUserByPasswordAndUsername.fulfilled", action.payload);
        state.status = "succeeded";
        state.currentUser = action.payload; // مش list
      })
      .addCase(getUserByPasswordAndUsername.rejected, (state, action) => {
        console.log("getUserByPasswordAndUsername.rejected", action.error);
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(addUserAsync.pending, (state) => {
        state.addStatus = "loading";
        state.error = null;
      })
      .addCase(addUserAsync.fulfilled, (state, action) => {
        state.addStatus = "succeeded";
        const newUser = {
          user_id: action.payload.userID,
          user_name: action.payload.userName,
          first_name: action.payload.firstName,
          last_name: action.payload.lastName,
          is_active: action.payload.isActive,
          person_id: action.payload.personID,
        };
        const pendingIndex = state.list.findIndex(
          (u) => u.user_id === undefined,
        );
        if (pendingIndex !== -1) {
          state.list[pendingIndex] = newUser;
        } else {
          state.list.push(newUser);
        }
      })
      .addCase(addUserAsync.rejected, (state, action) => {
        state.addStatus = "failed";
        state.error = action.payload;
      })
      .addCase(DeleteUser.pending, (state) => {
        state.deletingstatus = "loading";
        state.error = null;
      })
      .addCase(DeleteUser.fulfilled, (state, action) => {
        state.deletingstatus = "succeeded";
        state.list = state.list.filter((u) => u.user_id !== action.meta.arg);
        state.error = null;
      })
      .addCase(DeleteUser.rejected, (state, action) => {
        state.deletingstatus = "failed";
        state.error = action.payload;
      })
      .addCase(UpdateUser.pending, (state) => {
        state.updatingstatus = "loading";
        state.error = null;
      })
      .addCase(UpdateUser.fulfilled, (state, action) => {
        state.updatingstatus = "succeeded";
        const index = state.list.findIndex(
          (u) => u.user_id === action.payload.userID,
        );
        if (index !== -1) {
          state.list[index] = {
            user_id: action.payload.userID,
            user_name: action.payload.userName,
            first_name: action.payload.firstName,
            last_name: action.payload.lastName,
            is_active: action.payload.isActive,
            person_id: action.payload.personID,
          };
        }
      })
      .addCase(UpdateUser.rejected, (state, action) => {
        state.updatingstatus = "failed";
        state.error = action.payload;
      })
      .addCase(getUserByID.fulfilled, (state, action) => {
        const user = action.payload;
        const normalized = {
          user_id: user.userID,
          user_name: user.userName,
          first_name: user.firstName,
          last_name: user.lastName,
          is_active: user.isActive,
          person_id: user.personID,
        };
        const existingUserIndex = state.list.findIndex(
          (u) => u.user_id === user.userID,
        );
        if (existingUserIndex !== -1) {
          state.list[existingUserIndex] = normalized;
        } else {
          state.list.push(normalized); // ✅ الإضافة الناقصة سابقاً
        }
      });
  },
});

export const {
  addUser,
  resetAddUserStatus,
  resetDeleteUserStatus,
  resetUpdateUserStatus,
  updateUserLocally,
} = Userlice.actions;
export default Userlice.reducer;
