import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  Box,
  Typography,
  TextField,
  Button,
  Divider,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import { useSelector, useDispatch } from "react-redux";

import PersonInfoPanel from "../Shared/Person/PersonInfoModal";
import { selectPersonById } from "../Store/features/people/peopleSlice";
import {
  addUserAsync,
  resetAddUserStatus,
} from "../Store/features/Users/userSlice";
import FeildAlert from "../Popups/FailedAlert";
import Alert from "@mui/material/Alert";
import { validateUserForm } from "../validations/validation";

export default function AddUser({ open, onClose }) {
  const dispatch = useDispatch();
  const addStatus = useSelector((state) => state.users.addStatus);

  // ── قسم 1: البحث عن الشخص بالـ Person ID ──
  const [personIdInput, setPersonIdInput] = useState("");
  const [searchedPersonId, setSearchedPersonId] = useState(null);
  const [searchError, setSearchError] = useState("");

  const foundPerson = useSelector((state) =>
    searchedPersonId ? selectPersonById(state, searchedPersonId) : null,
  );

  // تحقق: هل الشخص ده عنده يوزر مسجل بالفعل؟
  const existingUser = useSelector((state) =>
    searchedPersonId
      ? state.users.list.find((u) => u.person_id === searchedPersonId)
      : null,
  );

  const handleSearch = () => {
    const idNum = Number(personIdInput);
    if (!personIdInput || Number.isNaN(idNum)) {
      setSearchError("Please enter a valid Person ID");
      setSearchedPersonId(null);
      return;
    }

    setSearchedPersonId(idNum);
    setSearchError("");
  };

  // بعد ما البحث يخلص، لو الشخص مش موجود نظهر رسالة خطأ
  const personNotFound = searchedPersonId !== null && !foundPerson;
  const personAlreadyHasUser = Boolean(foundPerson) && Boolean(existingUser);

  // ── قسم 3: بيانات اليوزر ──
  const [form, setForm] = useState({
    userName: "",
    password: "",
    confirmPassword: "",
  });
  const [touched, setTouched] = useState({});

  const errors = validateUserForm(form);
  const isFormValid =
    Object.keys(errors).length === 0 && Boolean(foundPerson) && !existingUser;

  const handleChange = (field) => (e) => {
    setForm((prev) => ({ ...prev, [field]: e.target.value }));
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const showError = (field) => Boolean(touched[field] && errors[field]);
  const errorText = (field) => (touched[field] ? errors[field] || "" : "");

  const handleSave = () => {
    if (!isFormValid) return;

    dispatch(
      addUserAsync({
        personID: searchedPersonId,
        userName: form.userName,
        password: form.password,
      }),
    );
  };

  const handleClose = () => {
    setPersonIdInput("");
    setSearchedPersonId(null);
    setSearchError("");
    setForm({ userName: "", password: "", confirmPassword: "" });
    setTouched({});
    dispatch(resetAddUserStatus());
    onClose();
  };

  // إغلاق تلقائي بعد نجاح الإضافة
  React.useEffect(() => {
    if (addStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 1800);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [addStatus]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog"
    >
      <DialogContent
        className="modal-content"
        sx={{ px: { xs: 3, md: 5 }, py: 4 }}
      >
        <Typography
          className="person-details-title"
          variant="h5"
          align="center"
          sx={{ mb: 3 }}
        >
          Add New User
        </Typography>

        {/* القسم 1: فلتر البحث بالـ Person ID */}
        <Box sx={{ display: "flex", gap: 2, alignItems: "flex-start", mb: 2 }}>
          <TextField
            className="modal-textfield"
            label="Person ID"
            value={personIdInput}
            onChange={(e) => setPersonIdInput(e.target.value)}
            size="small"
            sx={{ maxWidth: 200 }}
          />
          <Button
            variant="contained"
            startIcon={<SearchIcon />}
            onClick={handleSearch}
            className="people-add-btn"
          >
            Search
          </Button>
        </Box>

        {searchError && <FeildAlert>{searchError}</FeildAlert>}
        {personNotFound && (
          <FeildAlert>No person found with this ID</FeildAlert>
        )}
        {personAlreadyHasUser && (
          <FeildAlert>This person already has a user account</FeildAlert>
        )}

        {/* القسم 2: عرض بيانات الشخص لو موجود */}
        {foundPerson && (
          <>
            <Divider className="profile-section-divider" sx={{ my: 2 }} />
            <PersonInfoPanel personId={searchedPersonId} />
          </>
        )}

        {/* القسم 3: بيانات اليوزر — يظهر فقط لو الشخص موجود ومفيش يوزر عليه أصلاً */}
        {foundPerson && !existingUser && (
          <>
            <Divider className="profile-section-divider" sx={{ my: 3 }} />
            <Typography className="profile-section-title" sx={{ mb: 2 }}>
              Login Information
            </Typography>

            {addStatus === "failed" && (
              <FeildAlert>Failed to add user</FeildAlert>
            )}
            {addStatus === "succeeded" && (
              <Alert severity="success" variant="filled" sx={{ mb: 2 }}>
                User added successfully ✅
              </Alert>
            )}

            <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
              <TextField
                className="modal-textfield"
                label="Username"
                value={form.userName}
                onChange={handleChange("userName")}
                error={showError("userName")}
                helperText={errorText("userName")}
                fullWidth
                size="small"
              />
              <TextField
                className="modal-textfield"
                label="Password"
                type="password"
                value={form.password}
                onChange={handleChange("password")}
                error={showError("password")}
                helperText={errorText("password")}
                fullWidth
                size="small"
              />
              <TextField
                className="modal-textfield"
                label="Confirm Password"
                type="password"
                value={form.confirmPassword}
                onChange={handleChange("confirmPassword")}
                error={showError("confirmPassword")}
                helperText={errorText("confirmPassword")}
                fullWidth
                size="small"
              />
            </Box>

            <Box
              className="modal-actions"
              sx={{
                display: "flex",
                justifyContent: "flex-end",
                gap: 2,
                mt: 3,
              }}
            >
              <Button onClick={handleClose} className="modal-btn-cancel">
                Close
              </Button>
              <Button
                onClick={handleSave}
                className="modal-btn-save"
                variant="contained"
                disabled={
                  !isFormValid ||
                  addStatus === "loading" ||
                  addStatus === "succeeded"
                }
              >
                Save
              </Button>
            </Box>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}
