import React, { useRef, useEffect } from "react";

// ============================================
// DVLD Programming Advices - Animated Background
// React Component - Drop-in usage
// ============================================
// Usage:
//   import DvldHero from './DvldHero';
//   <DvldHero />
//
// Props:
//   scale         number   Canvas resolution scale (0.4 = light, 0.6 = balanced, 1.0 = max quality)
//   fps           number   Frame rate cap (default: 30)
//   lineCount     number   Number of contour lines (default: 70)
//   islandCount   number   Number of closed contour islands (default: 12)
//   title         string   Main title line 1 (default: "PROGRAMMING")
//   accent        string   Main title line 2 (default: "ADVICES")
//   subtitle      string   Subtitle (default: "LEARN THE RIGHT WAY")
//   project       string   Project name (default: "Driver & Vehicle Licenses Department (DVLD) Project")
// ============================================

const DvldHero = ({
  scale = 0.6,
  fps = 30,
  lineCount = 70,
  islandCount = 12,
  title = "PROGRAMMING",
  accent = "ADVICES",
  subtitle = "LEARN THE RIGHT WAY",
  project = "Driver & Vehicle Licenses Department (DVLD) Project",
}) => {
  const canvasRef = useRef(null);
  const containerRef = useRef(null);
  const stateRef = useRef({
    W: 0,
    H: 0,
    time: 0,
    mouseX: 0,
    mouseY: 0,
    targetMX: 0,
    targetMY: 0,
    animId: null,
    lastTime: 0,
  });

  // Original noise function (3 sin/cos waves)
  const noise = (x, y, t) => {
    return (
      Math.sin(x * 0.008 + t * 0.3) * Math.cos(y * 0.006 + t * 0.2) +
      Math.sin(x * 0.015 + y * 0.012 + t * 0.15) * 0.5 +
      Math.cos(x * 0.005 - y * 0.008 + t * 0.25) * 0.3
    );
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext("2d");
    const s = stateRef.current;
    const frameInterval = 1000 / fps;
    const mouseRange = 120;

    const resize = () => {
      const cssW = container.offsetWidth;
      const cssH = container.offsetHeight;
      s.W = canvas.width = Math.floor(cssW * scale);
      s.H = canvas.height = Math.floor(cssH * scale);
      canvas.style.width = cssW + "px";
      canvas.style.height = cssH + "px";
    };

    const handleMouseMove = (e) => {
      const rect = container.getBoundingClientRect();
      s.targetMX = (e.clientX - rect.left) * scale;
      s.targetMY = (e.clientY - rect.top) * scale;
    };

    const draw = () => {
      ctx.clearRect(0, 0, s.W, s.H);

      // Smooth mouse follow
      s.mouseX += (s.targetMX - s.mouseX) * 0.03;
      s.mouseY += (s.targetMY - s.mouseY) * 0.03;

      const step = Math.max(3, Math.floor(5 * scale));

      // Draw contour lines
      for (let i = 0; i < lineCount; i++) {
        const baseY = (i / lineCount) * s.H * 1.4 - s.H * 0.2;
        const distFromMouse = Math.abs(baseY - s.mouseY);
        const mouseGlow = Math.max(0, 1 - distFromMouse / 400);
        const baseOpacity = 0.15 + Math.sin(i * 0.3 + s.time * 0.5) * 0.08;
        const opacity = baseOpacity + mouseGlow * 0.35;

        ctx.beginPath();
        ctx.strokeStyle = `rgba(0, ${(200 + mouseGlow * 55) | 0}, ${(220 + mouseGlow * 35) | 0}, ${opacity})`;
        ctx.lineWidth = (0.8 + mouseGlow * 1.5) * scale;

        let firstPoint = true;
        for (let px = 0; px <= s.W; px += step) {
          let yOffset = noise(px, baseY, s.time) * 80;

          const dx = px - s.mouseX;
          const dy = baseY - s.mouseY;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < mouseRange * 3) {
            const force = (1 - dist / (mouseRange * 3)) * mouseRange;
            yOffset += (dy / (dist || 1)) * force * 0.5;
          }

          const py = baseY + yOffset;
          if (firstPoint) {
            ctx.moveTo(px, py);
            firstPoint = false;
          } else {
            ctx.lineTo(px, py);
          }
        }
        ctx.stroke();
      }

      // Draw closed contour islands
      for (let i = 0; i < islandCount; i++) {
        const cx = (Math.sin(i * 2.5 + s.time * 0.1) * 0.4 + 0.5) * s.W;
        const cy = (Math.cos(i * 1.8 + s.time * 0.08) * 0.4 + 0.5) * s.H;
        const radius = 30 + Math.sin(i + s.time * 0.2) * 15 + i * 8;
        const distFromMouse = Math.sqrt(
          (cx - s.mouseX) ** 2 + (cy - s.mouseY) ** 2,
        );
        const mouseGlow = Math.max(0, 1 - distFromMouse / 300);

        ctx.beginPath();
        ctx.strokeStyle = `rgba(0, ${(200 + mouseGlow * 55) | 0}, ${(220 + mouseGlow * 35) | 0}, ${0.1 + mouseGlow * 0.3})`;
        ctx.lineWidth = (0.6 + mouseGlow) * scale;

        for (let a = 0; a <= Math.PI * 2; a += 0.06) {
          const r =
            radius +
            Math.sin(a * 3 + s.time * 0.4 + i) * 10 +
            Math.cos(a * 5 - s.time * 0.3 + i * 2) * 5;
          const px = cx + Math.cos(a) * r;
          const py = cy + Math.sin(a) * r;
          if (a === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.stroke();
      }
    };

    const animate = (now) => {
      s.animId = requestAnimationFrame(animate);
      const delta = now - s.lastTime;
      if (delta < frameInterval) return;
      s.lastTime = now - (delta % frameInterval);
      s.time += 0.016;
      draw();
    };

    // Init
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);
    container.addEventListener("mousemove", handleMouseMove);
    s.animId = requestAnimationFrame(animate);

    // Cleanup
    return () => {
      if (s.animId) cancelAnimationFrame(s.animId);
      ro.disconnect();
      container.removeEventListener("mousemove", handleMouseMove);
    };
  }, [scale, fps, lineCount, islandCount]);

  return (
    <div
      ref={containerRef}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        background: "#0a0f14",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          zIndex: 0,
        }}
      />

      <div
        style={{
          position: "relative",
          zIndex: 10,
          background: "rgba(13, 17, 23, 0.94)",
          border: "1px solid rgba(0, 255, 255, 0.25)",
          borderRadius: "16px",
          padding: "60px 80px",
          textAlign: "center",
          backdropFilter: "blur(6px)",
          boxShadow:
            "0 0 60px rgba(0, 255, 255, 0.08), inset 0 0 60px rgba(0, 255, 255, 0.02)",
          animation: "dvldCardFloat 6s ease-in-out infinite",
        }}
      >
        <div
          style={{
            fontSize: "52px",
            fontWeight: 800,
            color: "#ffffff",
            letterSpacing: "4px",
            textTransform: "uppercase",
            lineHeight: 1.1,
            textShadow: "0 0 30px rgba(255,255,255,0.1)",
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontSize: "52px",
            fontWeight: 800,
            color: "#00e5ff",
            letterSpacing: "4px",
            textTransform: "uppercase",
            lineHeight: 1.1,
            marginTop: "4px",
            textShadow: "0 0 40px rgba(0, 229, 255, 0.4)",
            animation: "dvldAccentPulse 3s ease-in-out infinite",
          }}
        >
          {accent}
        </div>
        <div
          style={{
            fontSize: "16px",
            fontWeight: 400,
            color: "rgba(255, 255, 255, 0.7)",
            letterSpacing: "6px",
            textTransform: "uppercase",
            marginTop: "20px",
          }}
        >
          {subtitle}
        </div>
        <div
          style={{
            width: "100%",
            height: "1px",
            background:
              "linear-gradient(90deg, transparent, rgba(0,255,255,0.3) 20%, rgba(0,255,255,1) 50%, rgba(0,255,255,0.3) 80%, transparent)",
            margin: "28px 0",
            animation: "dvldDividerGlow 2s ease-in-out infinite",
          }}
        />
        <div
          style={{
            fontSize: "18px",
            fontWeight: 300,
            color: "rgba(255, 255, 255, 0.85)",
            letterSpacing: "1px",
          }}
        >
          {project}
        </div>
      </div>

      {/* Inline keyframes */}
      <style>{`
        @keyframes dvldCardFloat {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-8px); }
        }
        @keyframes dvldAccentPulse {
          0%, 100% { text-shadow: 0 0 40px rgba(0, 229, 255, 0.4); }
          50% { text-shadow: 0 0 60px rgba(0, 229, 255, 0.7); }
        }
        @keyframes dvldDividerGlow {
          0%, 100% { opacity: 0.8; box-shadow: 0 0 10px rgba(0,255,255,0.3); }
          50% { opacity: 1; box-shadow: 0 0 25px rgba(0,255,255,0.6); }
        }
        @media (max-width: 768px) {
          .dvld-card { padding: 40px 28px !important; margin: 16px !important; }
          .dvld-title { font-size: 30px !important; letter-spacing: 2px !important; }
          .dvld-subtitle { font-size: 12px !important; letter-spacing: 3px !important; }
          .dvld-project { font-size: 14px !important; }
        }
      `}</style>
    </div>
  );
};

export default DvldHero;
