import React, { useState, useCallback, useEffect } from "react";
import {
  Box,
  Typography,
  TextField,
  Button,
  Checkbox,
  FormControlLabel,
  InputAdornment,
} from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import LockIcon from "@mui/icons-material/Lock";
import LoginIcon from "@mui/icons-material/Login";
import { useNavigate } from "react-router-dom";

import { validateLoginForm } from "../validations/validation";
import { saveSession } from "../utils/session";

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { getUserByPasswordAndUsername } from "../Store/features/Users/userSlice";
import { GetCurrentPerson } from "../Store/features/people/peopleSlice";

const EMPTY_FORM = { userName: "", password: "", rememberMe: false };

export default function LoginForm() {
  //********************FormControl******************************* */
  const navigate = useNavigate();
  const [formData, setFormData] = useState(EMPTY_FORM);
  const [errors, setErrors] = useState({});
  const [authError, setAuthError] = useState("");
  const [LoginDisabeld, setLoginDisabeld] = useState(false);
  //********************FormControl******************************* */

  //********************Using Dispatch******************************* */
  const dispatch = useDispatch();

  const user = useSelector((state) => state.users.currentUser);
  const status = useSelector((state) => state.users.status);
  const error = useSelector((state) => state.users.error);

  const handleChange = useCallback(
    (field) => (e) => {
      const value = field === "rememberMe" ? e.target.checked : e.target.value;
      setFormData((prev) => ({ ...prev, [field]: value }));
      setErrors((prev) => {
        if (!prev[field]) return prev;
        const next = { ...prev };
        delete next[field];
        return next;
      });
      setAuthError("");
    },
    [],
  );

  const handleLogin = useCallback(async () => {
    const validationErrors = validateLoginForm(formData);
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    try {
      setLoginDisabeld(true);

      const loggedInUser = await dispatch(
        getUserByPasswordAndUsername({
          username: formData.userName,
          password: formData.password,
        }),
      ).unwrap();

      let loggedInPerson = null;
      try {
        loggedInPerson = await dispatch(
          GetCurrentPerson(loggedInUser.personID),
        ).unwrap();
      } catch (personErr) {
        // حتى لو فشل جلب الشخص، ما نمنع تسجيل الدخول — بس الجلسة المحفوظة
        // بتكون بدون بيانات شخصية كاملة لحد ما تتوفر لاحقًا
        console.error("Failed to fetch current person:", personErr);
      }

      saveSession(loggedInUser, loggedInPerson);

      navigate("/Home");
      setLoginDisabeld(false);
      return;
    } catch (ex) {
      setAuthError(error || "Login failed. Please try again.");
      setLoginDisabeld(false);
      return;
    }
  }, [formData, navigate, dispatch, error]);

  // يسمح بالضغط على Enter داخل أي حقل لتسجيل الدخول مباشرة
  const handleKeyDown = useCallback(
    (e) => {
      if (e.key === "Enter") handleLogin();
    },
    [handleLogin],
  );

  return (
    <Box className="login-form-panel">
      <Typography variant="h5" className="login-form-title">
        Login to your account
      </Typography>

      {authError && (
        <Typography className="login-auth-error">{authError}</Typography>
      )}

      <Box className="login-form-fields">
        <TextField
          label="Username"
          value={formData.userName}
          onChange={handleChange("userName")}
          onKeyDown={handleKeyDown}
          error={!!errors.userName}
          helperText={errors.userName}
          className="modal-textfield"
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <PersonIcon className="login-field-icon" />
              </InputAdornment>
            ),
          }}
          fullWidth
        />

        <TextField
          label="Password"
          type="password"
          value={formData.password}
          onChange={handleChange("password")}
          onKeyDown={handleKeyDown}
          error={!!errors.password}
          helperText={errors.password}
          className="modal-textfield"
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <LockIcon className="login-field-icon" />
              </InputAdornment>
            ),
          }}
          fullWidth
        />

        <FormControlLabel
          control={
            <Checkbox
              checked={formData.rememberMe}
              onChange={handleChange("rememberMe")}
            />
          }
          label="Remember Me"
          className="login-remember-checkbox"
        />

        <Button
          onClick={handleLogin}
          variant="contained"
          startIcon={<LoginIcon />}
          className="login-submit-btn"
          disabled={LoginDisabeld}
          sx={{
            backgroundColor: LoginDisabeld ? "grey" : "green",
            cursor: LoginDisabeld ? "not-allowed" : "pointer",
            opacity: LoginDisabeld ? 0.5 : 1,
          }}
        >
          Login
        </Button>
      </Box>
    </Box>
  );
}
