import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  Box,
  Divider,
  Typography,
  Button,
} from "@mui/material";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import EmailIcon from "@mui/icons-material/Email";
import SmsIcon from "@mui/icons-material/Sms";
import PinIcon from "@mui/icons-material/Pin";
import PersonIcon from "@mui/icons-material/Person";
import BadgeIcon from "@mui/icons-material/Badge";
import { useSelector } from "react-redux";

import PersonInfoPanel from "../Shared/Person/PersonInfoPanel";
import SendEmailDialog from "../Shared/Sends/SendEmailDialog";
import SendSmsDialog from "../Shared/Sends/SendSmsDialog";
import { selectPersonById } from "../Store/features/people/peopleSlice";

function InfoField({ icon: Icon, label, value }) {
  return (
    <Box className="profile-readonly-row" sx={{ flex: 1, minWidth: 0 }}>
      {Icon && (
        <Icon
          className="profile-readonly-icon"
          sx={{ fontSize: "1.1rem !important" }}
        />
      )}
      <Typography
        className="profile-readonly-label"
        sx={{ fontSize: "0.95rem !important", minWidth: 90 }}
      >
        {label}:
      </Typography>
      <Typography
        className="profile-readonly-value"
        component="span"
        sx={{ fontSize: "0.95rem !important" }}
      >
        {value || "—"}
      </Typography>
    </Box>
  );
}

// تظهر عند: ManageUsersScreen → single click على صف بالجدول
// userId: يُمرَّر فقط، البيانات تُقرأ من Redux (نفس نمط PersonDetailsModal)
export default function UserDetailsModal({
  open,
  onClose,
  userId,
  onUpdate,
  onDelete,
}) {
  const user = useSelector((state) =>
    state.users.list.find((u) => u.user_id === userId),
  );
  const personId = user?.person_id;
  const person = useSelector((state) => selectPersonById(state, personId));

  // state خاص بفتح/إغلاق نوافذ الإرسال — منفصل عن حالة الـ modal الرئيسي
  const [emailOpen, setEmailOpen] = useState(false);
  const [smsOpen, setSmsOpen] = useState(false);

  if (!user) return null;

  const fullName =
    `${person?.first_name || ""} ${person?.last_name || ""}`.trim();

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="lg"
      className="modal-dialog"
    >
      <DialogContent
        className="modal-content"
        sx={{ px: { xs: 3, md: 6 }, py: 4 }}
      >
        {/* القسم العلوي: Person Info */}
        <PersonInfoPanel personId={personId} />

        <Divider className="profile-section-divider" sx={{ my: 3 }} />

        {/* القسم الأوسط: User Info (مصغر) */}
        <Box className="profile-section">
          <Typography className="profile-section-title" sx={{ mb: 1.5 }}>
            Login Information
          </Typography>
          <Box sx={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
            <InfoField icon={PinIcon} label="User ID" value={user.user_id} />
            <InfoField
              icon={PersonIcon}
              label="Username"
              value={user.user_name}
            />
            <InfoField
              icon={BadgeIcon}
              label="Is Active"
              value={user.is_active ? "Yes" : "No"}
            />
          </Box>
        </Box>

        {/* القسم السفلي: الأزرار */}
        <Box
          className="modal-actions"
          sx={{
            display: "flex",
            justifyContent: "center",
            gap: 2,
            mt: 3,
            flexWrap: "wrap",
          }}
        >
          <Button
            className="modal-btn-save"
            startIcon={<EditIcon />}
            onClick={() => onUpdate && onUpdate(userId)}
          >
            Edit
          </Button>
          <Button
            className="modal-btn-cancel"
            startIcon={<DeleteIcon />}
            sx={{ color: "var(--color-danger-alt) !important" }}
            onClick={() => onDelete && onDelete(userId)}
          >
            Delete
          </Button>
          <Button
            className="modal-btn-cancel"
            startIcon={<EmailIcon />}
            onClick={() => setEmailOpen(true)}
          >
            Send Email
          </Button>
          <Button
            className="modal-btn-cancel"
            startIcon={<SmsIcon />}
            onClick={() => setSmsOpen(true)}
          >
            Send SMS
          </Button>
        </Box>
      </DialogContent>

      <SendEmailDialog
        open={emailOpen}
        onClose={() => setEmailOpen(false)}
        recipientName={fullName}
        recipientEmail={person?.email}
      />
      <SendSmsDialog
        open={smsOpen}
        onClose={() => setSmsOpen(false)}
        recipientName={fullName}
        recipientPhone={person?.phone}
      />
    </Dialog>
  );
}
