import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  Box,
  TextField,
  Button,
  Typography,
} from "@mui/material";
import EmailIcon from "@mui/icons-material/Email";
import SendIcon from "@mui/icons-material/Send";

// كومبوننت مشترك: يُستدعى من أي مكان (People أو Users) عبر props فقط
// recipientName / recipientEmail: بيانات للعرض فقط (مين المرسل إليه)
export default function SendEmailDialog({
  open,
  onClose,
  recipientName,
  recipientEmail,
}) {
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");
  const [status, setStatus] = useState("idle"); // idle | sending | success | failed

  const handleClose = () => {
    // نصفّر الفورم كل مرة نسكر فيها، حتى ما يضل subject/body قديم لمرة الجاية
    setSubject("");
    setBody("");
    setStatus("idle");
    onClose();
  };

  const handleSend = () => {
    setStatus("sending");
    // لاحقاً هنا فقط: dispatch(sendEmail({ to: recipientEmail, subject, body }))
    setTimeout(() => {
      setStatus("success");
      // بعد ما يبين النجاح لثانية، نسكر الـ Dialog تلقائياً وننضف الفورم
      setTimeout(() => {
        handleClose();
      }, 900);
    }, 1200);
  };

  return (
    <Dialog open={open} onClose={handleClose} fullWidth maxWidth="sm">
      <DialogTitle sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        <EmailIcon /> Send Email {recipientName ? `to ${recipientName}` : ""}
      </DialogTitle>

      <DialogContent
        sx={{ display: "flex", flexDirection: "column", gap: 2, pt: 1 }}
      >
        <Typography variant="body2" color="text.secondary">
          {recipientEmail || "—"}
        </Typography>

        <TextField
          label="Subject"
          value={subject}
          onChange={(e) => setSubject(e.target.value)}
          fullWidth
          size="small"
        />

        <TextField
          label="Body"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          fullWidth
          multiline
          rows={5}
        />

        {status === "success" && (
          <Typography color="success.main">Email sent successfully!</Typography>
        )}
        {status === "failed" && (
          <Typography color="error">Failed to send email.</Typography>
        )}

        <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 2 }}>
          <Button onClick={handleClose}>Close</Button>
          <Button
            variant="contained"
            startIcon={<SendIcon />}
            onClick={handleSend}
            disabled={status === "sending" || !subject || !body}
          >
            {status === "sending" ? "Sending..." : "Send"}
          </Button>
        </Box>
      </DialogContent>
    </Dialog>
  );
}
