import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import DriveEtaIcon from "@mui/icons-material/DriveEta";
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { getAllDrivers } from "../Store/features/Drivers/DriverSlice";
import { getLicenses } from "../Store/features/Licenses/LicensesSlice";
import Filter from "../Shared/Filter";
import AddDriver from "../Add/AddDriver";
import ShowLicenseInfo from "../Shared/License/Showlicenseinfo";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  DriverID: "id",
  PersonID: "PersonID",
  NationalNo: "nationalNo",
  FullName: "fullName",
};

// شاشة Manage Driver — Component عرض فقط، بلا بيانات وهمية
export default function ManageDriverScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");
  const dispatch = useDispatch();

  // useSelector: بيقرأ فقط الجزء الخاص بـ people من الـ state الكلي
  const Driver = useSelector((state) => state.driver.list);
  const status = useSelector((state) => state.driver.status);
  const error = useSelector((state) => state.driver.error);

  // ── حالة الـ double click على صف السائق وفتح ديالوج show license ──
  const [selectedDriverId, setSelectedDriverId] = useState(null);
  const [openLicenseDialog, setOpenLicenseDialog] = useState(false);

  // بنستخدم الـ list العام لـ licenses ونفلتر عليه محلياً
  // (الـ thunk getLicenses فيه condition بيلغي أي طلب جديد لو الـ list معبّى أصلاً)
  const licensesList = useSelector((state) => state.licenses.list);
  const driverLicensesForSelected = licensesList.filter(
    (l) => l.driver_id === selectedDriverId,
  );
  const licenseForSelectedDriver =
    driverLicensesForSelected.find((l) => l.is_active) ||
    driverLicensesForSelected[0];

  useEffect(() => {
    dispatch(getAllDrivers());
    dispatch(getLicenses()); // بيتجاهَل تلقائياً لو الـ list معبّى أصلاً
  }, [dispatch]);

  // لما توصل/تتوفر الرخصة المطابقة، افتح الديالوج
  useEffect(() => {
    if (selectedDriverId != null && licenseForSelectedDriver) {
      setOpenLicenseDialog(true);
    }
  }, [licenseForSelectedDriver, selectedDriverId]);

  const handleDriverRowDoubleClick = (driverId) => {
    setSelectedDriverId(driverId);
  };

  const handleCloseLicenseDialog = () => {
    setOpenLicenseDialog(false);
    setSelectedDriverId(null);
  };

  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }
  const rows = Driver.map((driver) => ({
    id: driver.driver_id,
    PersonID: driver.person_id,
    nationalNo: driver.national_no,
    fullName: driver.full_name,
    createdDate: driver.created_date,
    NumberofActiveLicenses: driver.number_of_active_licenses,
  }));

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "nationalNo"
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <Box className="people-header-wrapper">
          <Box className="people-header-icon-wrapper">
            <DriveEtaIcon className="people-header-icon" />
          </Box>
          <Typography variant="h4" className="people-header-title">
            Manage Driver
          </Typography>
          <Typography variant="h6" className="people-header-title">
            (Select Row and double click on it)
          </Typography>
        </Box>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  Driver ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Person ID.
                </TableCell>
                <TableCell className="people-table-head-cell">
                  National No.
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Created Date
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Number of Active Licenses
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow
                  key={row.id}
                  className="people-table-row"
                  onDoubleClick={() => handleDriverRowDoubleClick(row.id)}
                  style={{ cursor: "pointer" }}
                >
                  <TableCell className="people-table-cell-id">
                    {row.id}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.PersonID}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.nationalNo}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.fullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.createdDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.NumberofActiveLicenses}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>

        <ShowLicenseInfo
          open={openLicenseDialog}
          onClose={handleCloseLicenseDialog}
          licenseId={licenseForSelectedDriver?.license_id}
        />
      </Paper>
    </Box>
  );
}
