import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import LockClockIcon from "@mui/icons-material/LockClock";
import { Box as MuiBox, Typography } from "@mui/material";
//*************Loading Tools */
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
//*************Loading Tools */

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import {
  addDriver,
  getDetainedLicenses,
} from "../Store/features/DetainedLicenses/DetainedLicensesSlice";

import Filter from "../Shared/Filter";
import AddDetainedLicense from "../Shared/Application/DetainLicenseModal";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  DetainID: "detainId",
  LicenseID: "licenseId",
  DetainDate: "detainDate",
  IsReleased: "isReleased",
  NationalNo: "nationalNo",
  FullName: "fullName",
};

// شاشة Manage Detained Licenses — Component عرض فقط (صفحة كاملة، ليست Dialog)
export default function ManageDetainedLicensesScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");
  const [isDetainOpen, setIsDetainOpen] = useState(false);
  const dispatch = useDispatch();

  // useSelector: بيقرأ فقط الجزء الخاص بـ DetainedLicenses من الـ state الكلي
  const DetainedLicenses = useSelector((state) => state.DetainedLicenses.list);
  const status = useSelector((state) => state.DetainedLicenses.status);
  const error = useSelector((state) => state.DetainedLicenses.error);

  useEffect(() => {
    dispatch(getDetainedLicenses());
  }, [dispatch]);

  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }

  const rows = DetainedLicenses.map((license) => ({
    detainId: license.detain_id,
    licenseId: license.license_id,
    detainDate: license.detain_date,
    fineFees: license.fine_fees,
    isReleased: license.is_released ? "Yes" : "No",
    releaseDate: license.release_date,
    nationalNo: license.national_no,
    fullName: license.full_name,
    releaseAppId: license.release_application_id,
  }));

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "isReleased"
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <MuiBox className="people-header-wrapper">
          <MuiBox className="people-header-icon-wrapper">
            <LockClockIcon className="people-header-icon" />
          </MuiBox>
          <Typography variant="h4" className="people-header-title">
            Manage Detained Licenses
          </Typography>
        </MuiBox>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setIsDetainOpen(true)}
            className="people-add-btn"
          >
            Detain License
          </Button>
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  Detain ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  License ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Detain Date
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Is Released
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Fine Fees
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Release Date
                </TableCell>
                <TableCell className="people-table-head-cell">
                  National No.
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Release App ID
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow key={row.detainId} className="people-table-row">
                  <TableCell className="people-table-cell-id">
                    {row.detainId}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.licenseId}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.detainDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.isReleased}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.fineFees}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.releaseDate ? row.releaseDate : "N/A"}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.nationalNo}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.fullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.releaseAppId}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>
      </Paper>

      <AddDetainedLicense
        open={isDetainOpen}
        onClose={() => setIsDetainOpen(false)}
      />
    </Box>
  );
}
