import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Alert,
} from "@mui/material";
import DriveEtaIcon from "@mui/icons-material/DriveEta";
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { getLicenses } from "../Store/features/Licenses/LicensesSlice";
import Filter from "../Shared/Filter";
import NoCrashSharpIcon from "@mui/icons-material/NoCrashSharp";
import { getAllUsers } from "../Store/features/Users/userSlice";
import { getApplicationTypes } from "../Store/features/ApplicationType/ApplicationTypeSlice";
import { getAllDrivers } from "../Store/features/Drivers/DriverSlice";
import { useLocation } from "react-router-dom";

// ✅ استيراد الكومبوننت اللي هيفتح تفاصيل الرخصة
import ShowLicenseInfo from "../Shared/License/Showlicenseinfo";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  DriverID: "DriverID",
  PersonID: "PersonID",
  NationalNo: "NationalNo",
  FullName: "FullName",
};

// شاشة Manage Driver — Component عرض فقط، بلا بيانات وهمية
export default function ManageDriverScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");

  // ✅ حالة فتح دايلوك تفاصيل الرخصة + الـ ID المختار
  const [isShowLicenseOpen, setIsShowLicenseOpen] = useState(false);
  const [selectedLicenseId, setSelectedLicenseId] = useState(null);

  // ✅ تنبيه بسيط لما المستخدم يحاول يفتح رخصة Inactive
  const [inactiveAlertOpen, setInactiveAlertOpen] = useState(false);

  const location = useLocation();
  const { FullName } = location.state || {};
  const dispatch = useDispatch();

  useEffect(() => {
    dispatch(getLicenses());
    dispatch(getAllUsers());
    dispatch(getApplicationTypes());
    dispatch(getAllDrivers());
    if (FullName !== undefined) {
      setFilterBy("FullName");
      setSearchValue(FullName);
    }
  }, [dispatch]);

  // ⬇️ كل قائمة بترجع كاملة (array)، اللوكاب الفعلي لكل رخصة بيصير جوا rows.map تحت
  const Licenses = useSelector((state) => state.licenses.list);
  const drivers = useSelector((state) => state.driver.list);
  const applicationTypes = useSelector((state) => state.ApplicationType.list);
  const users = useSelector((state) => state.users.list);

  // ⬇️ لازم ننتظر كل المصادر، مش licenses بس
  const licensesStatus = useSelector((state) => state.licenses.status);
  const driverStatus = useSelector((state) => state.driver.status);
  const usersStatus = useSelector((state) => state.users.status);
  const appTypesStatus = useSelector((state) => state.ApplicationType.status);

  const allStatuses = [
    licensesStatus,
    driverStatus,
    usersStatus,
    appTypesStatus,
  ];

  const anyFailed = allStatuses.includes("failed");
  const allLoaded = allStatuses.every((s) => s === "succeeded");

  if (anyFailed) {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }

  if (!allLoaded) {
    return <CircularProgress></CircularProgress>;
  }

  const rows = Licenses.map((license) => {
    // ✅ driver_id مؤكّد snake_case من الـ Swagger على الاثنين License و Driver
    const driver = drivers.find((d) => d.driver_id === license.driver_id);

    // ⚠️ لسا مش مؤكّد 100% (ما شفنا Swagger لهم بعد) — خليها بالبال لو طلعت فاضية
    const issueType = applicationTypes.find(
      (t) => t.application_type_id === license.issue_reason,
    );
    const user = users.find((u) => u.user_id === license.created_by_user_id);

    return {
      id: license.license_id,
      DriverID: license.driver_id,
      PersonID: driver?.person_id ?? "-",
      NationalNo: driver?.national_no ?? "-",
      FullName: driver?.full_name ?? "-",
      IssueDate: license.issue_date,
      ExpirationDate: license.expiration_date,
      Notes: license.notes,
      Fees: license.paid_fees,
      isActive: license.is_active ? "Active" : "Inactive",
      IssueReason: issueType?.application_type_title || "-",
      createdBy: user?.user_name || "-",
    };
  });

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy];
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  // ✅ هاندلر الدبل كليك على الصف
  const handleRowDoubleClick = (row) => {
    if (row.isActive !== "Active") {
      // الرخصة Inactive: نمنع فتح الدايلوك ونعرض تنبيه بدل كذا
      setInactiveAlertOpen(true);
      return;
    }
    setInactiveAlertOpen(false); // ✅ نخفي رسالة التنبيه لو كانت ظاهرة من قبل
    setSelectedLicenseId(row.id);
    setIsShowLicenseOpen(true);
  };

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <Box className="people-header-wrapper">
          <Box className="people-header-icon-wrapper">
            <NoCrashSharpIcon className="people-header-icon" />
          </Box>
          <Typography variant="h4" className="people-header-title">
            All Licenses
          </Typography>
          <Typography variant="h6" className="people-header-title">
            (Select Row and double click on it)
          </Typography>
        </Box>

        {inactiveAlertOpen && (
          <Alert
            severity="warning"
            variant="filled"
            sx={{ mb: 2 }}
            onClose={() => setInactiveAlertOpen(false)}
          >
            This license is Inactive. Details cannot be shown.
          </Alert>
        )}

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  License ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Driver ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Person ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  IssueDate
                </TableCell>
                <TableCell className="people-table-head-cell">
                  ExpirationDate
                </TableCell>
                <TableCell className="people-table-head-cell">
                  IssueReason
                </TableCell>
                <TableCell className="people-table-head-cell">
                  IsActive
                </TableCell>
                <TableCell className="people-table-head-cell">
                  CreatedBy
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow
                  key={row.id}
                  className="people-table-row"
                  onDoubleClick={() => handleRowDoubleClick(row)}
                  sx={{ cursor: "pointer" }}
                >
                  <TableCell className="people-table-cell-id">
                    {row.id}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.DriverID}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.PersonID}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.FullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.IssueDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.ExpirationDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.IssueReason}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.isActive}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.createdBy}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>
      </Paper>

      {/* ✅ دايلوك تفاصيل الرخصة - يفتح فقط لما نضبط selectedLicenseId ونكون Active */}
      <ShowLicenseInfo
        licenseId={selectedLicenseId}
        open={isShowLicenseOpen}
        onClose={() => {
          setIsShowLicenseOpen(false);
          setSelectedLicenseId(null);
        }}
      />
    </Box>
  );
}
