import React from "react";
import { Box, Typography } from "@mui/material";
import CarAnimation from "../MainScreen/DrivingCarAnimation";
export default function LoginBrandingPanel() {
  return (
    <>
      <Box className="login-branding-panel">
        <div style={{ justifyContent: "center", display: "flex" }}>
          The UserName = <span style={{ color: "gold" }}> (Adnan)</span>
        </div>
        <div style={{ justifyContent: "center", display: "flex" }}>
          The PassWord = <span style={{ color: "gold" }}> (12)</span>
        </div>
        <CarAnimation />
        <Typography variant="h4" className="login-branding-welcome">
          Welcome To
        </Typography>
        <Typography variant="h4" className="login-branding-title">
          Driving &amp; Vehicle License
          <br />
          Department (DVLD) System
        </Typography>
        <Typography className="login-branding-version">Version 1.0</Typography>
      </Box>
    </>
  );
}
