import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  Box,
  Typography,
  TextField,
  Button,
  FormControlLabel,
  Checkbox,
} from "@mui/material";
import PinIcon from "@mui/icons-material/Pin";
import PersonIcon from "@mui/icons-material/Person";
import { useSelector, useDispatch } from "react-redux";
import {
  UpdateUser as updateUserThunk,
  updateUserLocally,
  resetUpdateUserStatus,
} from "../Store/features/Users/userSlice";
import FeildAlert from "../Popups/FailedAlert";
import Alert from "@mui/material/Alert";
import { validateUserForm } from "../validations/validation";

export default function UpdateUser({ open, onClose, userId }) {
  const dispatch = useDispatch();
  const user = useSelector((state) =>
    state.users.list.find((u) => u.user_id === userId),
  );
  const updatingstatus = useSelector((state) => state.users.updatingstatus);
  const error = useSelector((state) => state.users.error);

  const [form, setForm] = useState({
    userName: "",
    password: "",
    confirmPassword: "",
    isActive: true,
  });
  const [touched, setTouched] = useState({});

  // نجلب بيانات اليوزر من Redux ونعبي الفورم بيها
  useEffect(() => {
    if (user) {
      setForm({
        userName: user.user_name || "",
        password: "",
        confirmPassword: "",
        isActive: Boolean(user.is_active),
      });
    }
  }, [user]);

  // الباسورد اختياري وقت التعديل: لو فاضي، منسيبوش يفشل الفاليديشن
  const validationInput = {
    ...form,
    password: form.password || "placeholder123",
    confirmPassword: form.confirmPassword || "placeholder123",
  };
  const errors = form.password
    ? validateUserForm(validationInput)
    : {
        ...validateUserForm(validationInput),
        password: "",
        confirmPassword: "",
      };

  const isFormValid = Object.keys(errors).length === 0;

  const handleChange = (field) => (e) => {
    setForm((prev) => ({ ...prev, [field]: e.target.value }));
    setTouched((prev) => ({ ...prev, [field]: true }));
  };

  const handleIsActiveChange = (e) => {
    setForm((prev) => ({ ...prev, isActive: e.target.checked }));
  };

  const showError = (field) => Boolean(touched[field] && errors[field]);
  const errorText = (field) => (touched[field] ? errors[field] || "" : "");

  const handleSave = () => {
    if (!isFormValid || !user) return;

    const payload = {
      userID: user.user_id,
      personID: user.person_id,
      userName: form.userName,
      isActive: form.isActive,
    };

    // نحدّث الجدول فوراً محلياً (optimistic)، قبل ما نستنى رد السيرفر
    dispatch(
      updateUserLocally({
        user_id: user.user_id,
        user_name: form.userName,
        first_name: user.first_name,
        last_name: user.last_name,
        is_active: form.isActive,
        person_id: user.person_id,
      }),
    );

    // نبعت الباسورد بس لو المستخدم كتب واحدة جديدة فعلاً
    if (form.password) {
      payload.password = form.password;
    }

    dispatch(updateUserThunk(payload));
  };

  const handleClose = () => {
    if (updatingstatus === "loading") return;
    setTouched({});
    dispatch(resetUpdateUserStatus());
    onClose();
  };

  // إغلاق تلقائي بعد نجاح التحديث
  useEffect(() => {
    if (updatingstatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 1500);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [updatingstatus]);

  if (!user) return null;

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullWidth
      maxWidth="sm"
      className="modal-dialog"
    >
      <DialogContent
        className="modal-content"
        sx={{ px: { xs: 3, md: 5 }, py: 4 }}
      >
        <Typography
          className="person-details-title"
          variant="h5"
          align="center"
          sx={{ mb: 3 }}
        >
          Update User
        </Typography>

        {updatingstatus === "failed" && (
          <FeildAlert>{error || "Failed to update user"}</FeildAlert>
        )}
        {updatingstatus === "succeeded" && (
          <Alert severity="success" variant="outlined" sx={{ mb: 2 }}>
            User updated successfully ✅
          </Alert>
        )}

        <Box className="profile-readonly-row" sx={{ mb: 2 }}>
          <PinIcon className="profile-readonly-icon" />
          <Typography className="profile-readonly-label">UserID:</Typography>
          <Typography className="profile-readonly-value">
            {user.user_id}
          </Typography>
        </Box>

        <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            <PersonIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="UserName"
              value={form.userName}
              onChange={handleChange("userName")}
              error={showError("userName")}
              helperText={errorText("userName")}
              fullWidth
              size="small"
            />
          </Box>

          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            <PinIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="Password"
              type="password"
              placeholder="Leave blank to keep current password"
              value={form.password}
              onChange={handleChange("password")}
              error={showError("password")}
              helperText={
                errorText("password") || "Leave blank to keep current password"
              }
              fullWidth
              size="small"
            />
          </Box>

          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            <PinIcon className="submenu-accent-icon" />
            <TextField
              className="modal-textfield"
              label="Confirm Password"
              type="password"
              value={form.confirmPassword}
              onChange={handleChange("confirmPassword")}
              error={showError("confirmPassword")}
              helperText={errorText("confirmPassword")}
              fullWidth
              size="small"
            />
          </Box>

          <FormControlLabel
            control={
              <Checkbox
                checked={form.isActive}
                onChange={handleIsActiveChange}
              />
            }
            label="Is Active"
          />
        </Box>

        <Box
          className="modal-actions"
          sx={{ display: "flex", justifyContent: "flex-end", gap: 2, mt: 3 }}
        >
          <Button onClick={handleClose} className="modal-btn-cancel">
            Close
          </Button>
          <Button
            onClick={handleSave}
            className="modal-btn-save"
            variant="contained"
            disabled={
              !isFormValid ||
              updatingstatus === "loading" ||
              updatingstatus === "succeeded"
            }
          >
            Save
          </Button>
        </Box>
      </DialogContent>
    </Dialog>
  );
}
