import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [], // هنا رح تنخزن قائمة الـ test appointments
  currentAppointment: null, // لتخزين بيانات الـ appointment الحالي بعد جلبه بالـ ID
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  addStatus: "idle",
  byApplication: [], // ✅ جديد: نتيجة getTestAppointmentsByLocalDrivingLicenseApplicationID
  byApplicationStatus: "idle", // ✅ جديد
  cancelStatus: "idle",
  error: null,
};

// createAsyncThunk بيولّد تلقائياً 3 حالات (actions):
// testAppointments/getTestAppointments/pending
// testAppointments/getTestAppointments/fulfilled
// testAppointments/getTestAppointments/rejected

export const getTestAppointments = createAsyncThunk(
  "testAppointments/getTestAppointments",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/TestAppointments",
    );
    return response.data; // array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { testAppointments } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (
        testAppointments.status === "loading" ||
        testAppointments.list.length > 0
      ) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً، ورح تعتمد الكومبوننت على list الموجودة
      }
      return true;
    },
  },
);

export const getTestAppointmentById = createAsyncThunk(
  "testAppointments/getTestAppointmentById",
  async (testAppointmentId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/TestAppointments/${testAppointmentId}`,
    );
    return response.data; // object مباشرة حسب الـ Swagger
  },
  {
    condition: (testAppointmentId, { getState }) => {
      const { testAppointments } = getState();
      // إذا موجود أصلاً بالـ list، ما في داعي نجيبه من جديد
      const alreadyInList = testAppointments.list.some(
        (a) => a.testAppointmentID === testAppointmentId,
      );
      if (testAppointments.status === "loading" || alreadyInList) {
        return false;
      }
      return true;
    },
  },
);

export const AddTestAppointment = createAsyncThunk(
  "testAppointments/AddTestAppointment",
  async (testAppointment) => {
    const response = await axios.post(
      "https://idnan820-001-site1.ltempurl.com/api/TestAppointments",
      testAppointment,
    );
    return response.data;
  },
);
export const getTestAppointmentsByLocalDrivingLicenseApplicationID =
  createAsyncThunk(
    "testAppointments/getTestAppointmentsByLocalDrivingLicenseApplicationID",
    async ({ localDrivingLicenseApplicationID, testType }) => {
      const response = await axios.get(
        `https://idnan820-001-site1.ltempurl.com/api/TestAppointments/application/${localDrivingLicenseApplicationID}/type/${testType}`,
      );
      return response.data; // array حسب الصورة اللي أرسلتها
    },
    {
      condition: (_, { getState }) => {
        const { testAppointments } = getState();
        // فقط نمنع طلب مزدوج وقت ما في طلب شغال، وما نمنع إعادة الجلب
        // لأن المواعيد ممكن تتغير (إضافة/إلغاء) بين كل فتح للنافذة
        if (testAppointments.byApplicationStatus === "loading") {
          return false;
        }
        return true;
      },
    },
  );
// ⚠️ ملاحظة: ما في endpoint خاص بـ DELETE أو "Cancel" ظاهر بالصور اللي أرسلتها，
// بس في PUT /api/TestAppointments/{id}. اعتمدت عليه لعمل "الإلغاء" عن طريق
// تحديث نفس السجل (مثلاً تصفير isLocked / retakeTestApplicationID أو أي حقل إلغاء
// موجود عندك بالباك اند). إذا عندك endpoint مختلف للإلغاء بلغني وبعدل الـ thunk.
export const CancelTestAppointment = createAsyncThunk(
  "testAppointments/CancelTestAppointment",
  async (testAppointment, { rejectWithValue }) => {
    try {
      const response = await axios.put(
        `https://idnan820-001-site1.ltempurl.com/api/TestAppointments/${testAppointment.testAppointmentID}`,
        testAppointment,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Cancel failed",
      );
    }
  },
);

const testAppointmentSlice = createSlice({
  name: "testAppointments",
  initialState,
  reducers: {
    addTestAppointmentToList: (state, action) => {
      state.list.push(action.payload);
    },
    updateTestAppointmentLocally: (state, action) => {
      const index = state.list.findIndex(
        (a) => a.testAppointmentID === action.payload.testAppointmentID,
      );
      if (index !== -1) {
        state.list[index] = action.payload;
      }
    },
    resetAddStatus: (state) => {
      state.addStatus = "idle";
    },
    resetCancelStatus: (state) => {
      state.cancelStatus = "idle";
    },
  },

  extraReducers: (builder) => {
    builder
      .addCase(getTestAppointments.pending, (state) => {
        state.status = "loading";
        console.log("Im testAppointments Not done yet");
        state.error = null;
      })
      .addCase(getTestAppointments.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im testAppointments done");
        state.list = action.payload;
      })
      .addCase(getTestAppointments.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })

      .addCase(getTestAppointmentById.pending, (state) => {
        state.status = "loading";
        console.log("Current TestAppointment has been worked on");
        state.error = null;
      })
      .addCase(getTestAppointmentById.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Current TestAppointment has arrived");
        state.currentAppointment = action.payload;

        // إذا مش موجود بالـ list نضيفه، إذا موجود نحدثه
        const index = state.list.findIndex(
          (a) => a.testAppointmentID === action.payload.testAppointmentID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        } else {
          state.list.push(action.payload);
        }
      })
      .addCase(getTestAppointmentById.rejected, (state, action) => {
        state.status = "failed";
        console.log("Current TestAppointment has Not arrived");
        state.error = action.error.message;
      })

      .addCase(AddTestAppointment.pending, (state) => {
        state.addStatus = "loading";
        state.error = null;
      })
      .addCase(AddTestAppointment.fulfilled, (state, action) => {
        state.addStatus = "succeeded";
        console.log("AddTestAppointment succeeded");
        state.list.push(action.payload);
      })
      .addCase(AddTestAppointment.rejected, (state, action) => {
        state.addStatus = "failed";
        console.log("AddTestAppointment has not succeeded");
        state.error = action.error.message;
      })

      .addCase(CancelTestAppointment.pending, (state) => {
        state.cancelStatus = "loading";
        console.log("CancelTestAppointment work on it");
        state.error = null;
      })
      .addCase(CancelTestAppointment.fulfilled, (state, action) => {
        state.cancelStatus = "succeeded";
        console.log("CancelTestAppointment succeeded");
        const index = state.list.findIndex(
          (a) => a.testAppointmentID === action.payload.testAppointmentID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        }
      })
      .addCase(CancelTestAppointment.rejected, (state, action) => {
        state.cancelStatus = "failed";
        console.log("CancelTestAppointment has failed");
        state.error = action.payload;
      })
      .addCase(
        getTestAppointmentsByLocalDrivingLicenseApplicationID.pending,
        (state) => {
          state.byApplicationStatus = "loading";
          state.error = null;
        },
      )
      .addCase(
        getTestAppointmentsByLocalDrivingLicenseApplicationID.fulfilled,
        (state, action) => {
          state.byApplicationStatus = "succeeded";
          state.byApplication = action.payload;
        },
      )
      .addCase(
        getTestAppointmentsByLocalDrivingLicenseApplicationID.rejected,
        (state, action) => {
          state.byApplicationStatus = "failed";
          state.error = action.error.message;
        },
      );
  },
});

export const selectTestAppointmentById = (state, testAppointmentId) =>
  state.testAppointments.list.find(
    (a) => a.testAppointmentID === testAppointmentId,
  );

export const selectTestAppointmentsByLocalDrivingLicenseApplicationID = (
  state,
) => state.testAppointments.byApplication;

export const {
  addTestAppointmentToList,
  updateTestAppointmentLocally,
  resetAddStatus,
  resetCancelStatus,
} = testAppointmentSlice.actions;

export default testAppointmentSlice.reducer;
