import React, { useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Button,
  IconButton,
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import ReceiptLongIcon from "@mui/icons-material/ReceiptLong";
//*************Loading Tools */
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
//*************Loading Tools */

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { getApplicationTypes } from "../Store/features/ApplicationType/ApplicationTypeSlice";

export default function ManageApplicationTypesScreen({ open, onClose }) {
  const dispatch = useDispatch();
  const ApplicationType = useSelector((state) => state.ApplicationType.list);
  const status = useSelector((state) => state.ApplicationType.status);

  useEffect(() => {
    if (!open) {
      return;
    }
    dispatch(getApplicationTypes());
  }, [open]);

  // ملاحظة: لا يوجد return مبكر هنا قبل <Dialog> — الـ Dialog هو الغلاف
  // الثابت دائمًا، وحالات loading/failed تُعرض جواه لا بدلاً منه
  const rows = ApplicationType.map((type) => ({
    id: type.application_type_id,
    title: type.application_type_title,
    fees: type.application_fees,
  }));

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog app-types-dialog"
    >
      <IconButton onClick={onClose} className="app-types-close-btn">
        <CloseIcon />
      </IconButton>

      <DialogContent className="app-types-content">
        <Box className="people-header-wrapper">
          <Box className="people-header-icon-wrapper">
            <ReceiptLongIcon className="people-header-icon" />
          </Box>
          <Typography variant="h4" className="people-header-title">
            Manage Application Types
          </Typography>
        </Box>

        <Box className="people-toolbar-row"></Box>

        {status === "loading" && <CircularProgress />}

        {status === "failed" && (
          <FeildAlert>No Data Here, pleas call support</FeildAlert>
        )}

        {status === "succeeded" && (
          <>
            <TableContainer className="people-table-container">
              <Table className="people-table">
                <TableHead className="people-table-head">
                  <TableRow>
                    <TableCell className="people-table-head-cell">
                      Type ID
                    </TableCell>
                    <TableCell className="people-table-head-cell">
                      Type Title
                    </TableCell>
                    <TableCell className="people-table-head-cell">
                      Fees
                    </TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {rows.map((row) => (
                    <TableRow key={row.id} className="people-table-row">
                      <TableCell className="people-table-cell-id">
                        {row.id}
                      </TableCell>
                      <TableCell className="people-table-cell">
                        {row.title}
                      </TableCell>
                      <TableCell className="people-table-cell">
                        {row.fees}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Box className="people-table-footer">
              <Typography className="people-table-footer-count">
                # Records: {rows.length}
              </Typography>
            </Box>
          </>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button onClick={onClose} className="modal-btn-cancel">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}
