import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Avatar,
  Divider,
  TextField,
  Button,
} from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import BadgeIcon from "@mui/icons-material/Badge";
import PinIcon from "@mui/icons-material/Pin";
import CakeIcon from "@mui/icons-material/Cake";
import WcIcon from "@mui/icons-material/Wc";
import PhoneIcon from "@mui/icons-material/Phone";
import EmailIcon from "@mui/icons-material/Email";
import PublicIcon from "@mui/icons-material/Public";
import HomeIcon from "@mui/icons-material/Home";
import CloseIcon from "@mui/icons-material/Close";
import SaveIcon from "@mui/icons-material/Save";
import { useSelector, useDispatch } from "react-redux";
import CircularProgress from "../../Popups/LodaingCircul";
import FailedAlert from "../../Popups/FailedAlert";
import {
  UpdateUser,
  resetUpdateUserStatus,
} from "../../Store/features/Users/userSlice";
import { Alert } from "@mui/material"; // ضيفه لقائمة استيراد MUI الموجودة فوق

function FieldRow({ icon, label, value }) {
  return (
    <Box className="profile-readonly-row">
      {icon}
      <Typography className="profile-readonly-label">{label}:</Typography>
      <Typography className="profile-readonly-value">{value || "—"}</Typography>
    </Box>
  );
}

// person: { id, firstName, fatherName, grandFatherName, lastName, nationalNo,
//           dateOfBirth, gender, phone, email, country, address, photoUrl }
// user:   { id, username, isActive }
// onSave(currentPassword, newPassword, confirmPassword) — حاليًا console.log فقط
export default function UserInfoPanel({
  //person = {},
  //user = null,
  onEditPerson,
  onClose,
  onSave,
}) {
  const dispatch = useDispatch();
  const user = useSelector((state) => state.users.currentUser);
  const person = useSelector((state) => state.people.currentPerson);
  const countries = useSelector((state) => state.Country.list);
  const personCountry = countries.find(
    (c) => c.country_id === person?.nationalityCountryID,
  );
  console.log(personCountry);
  const statu = useSelector((state) => state.people.status);

  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordError, setPasswordError] = useState("");
  const updatingstatus = useSelector((state) => state.users.updatingstatus);

  const handleSave = () => {
    setPasswordError("");

    if (!newPassword || !confirmPassword) {
      setPasswordError("الرجاء إدخال كلمة المرور الجديدة وتأكيدها");
      return;
    }
    if (newPassword !== confirmPassword) {
      setPasswordError("كلمة المرور الجديدة وتأكيدها غير متطابقين");
      return;
    }

    const updatedUser = {
      userID: user.userID,
      userName: user.userName,
      password: newPassword,
      isActive: user.isActive,
      personID: user.personID,
    };

    dispatch(UpdateUser(updatedUser));
  };
  useEffect(() => {
    if (updatingstatus === "succeeded") {
      const timer = setTimeout(() => {
        dispatch(resetUpdateUserStatus());
        setCurrentPassword("");
        setNewPassword("");
        setConfirmPassword("");
        if (onClose) onClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [updatingstatus]);
  if (statu === "idle") {
    return <FailedAlert> No data has come in, Pleas log out now</FailedAlert>;
  }
  if (statu === "loading") {
    return <CircularProgress />;
  }

  if (statu === "failed") {
    return (
      <FailedAlert> No data has come in, Pleas try again later</FailedAlert>
    );
  }
  console.log(person);
  return (
    <Box>
      {/* Person Information */}
      <Box className="profile-section">
        <Box className="profile-section-header-row">
          <Typography className="profile-section-title">
            Person Information
          </Typography>
          {onEditPerson && (
            <Button className="profile-edit-link" onClick={onEditPerson}>
              Edit Person Info
            </Button>
          )}
        </Box>

        <Box className="profile-person-body">
          <Box className="profile-person-fields">
            <FieldRow
              icon={<PinIcon className="profile-readonly-icon" />}
              label="Person ID"
              value={person.personID}
            />
            <FieldRow
              icon={<BadgeIcon className="profile-readonly-icon" />}
              label="Name"
              value={person.fullName}
            />
            <FieldRow
              icon={<PinIcon className="profile-readonly-icon" />}
              label="National No"
              value={person.nationalNo}
            />
            <FieldRow
              icon={<CakeIcon className="profile-readonly-icon" />}
              label="Date Of Birth"
              value={person.dateOfBirth}
            />
            <FieldRow
              icon={<WcIcon className="profile-readonly-icon" />}
              label="Gender"
              value={person.gendor}
            />
            <FieldRow
              icon={<PhoneIcon className="profile-readonly-icon" />}
              label="Phone"
              value={person.phone}
            />
            <FieldRow
              icon={<EmailIcon className="profile-readonly-icon" />}
              label="Email"
              value={person.email}
            />
            <FieldRow
              icon={<PublicIcon className="profile-readonly-icon" />}
              label="Country"
              value={personCountry?.country_name}
            />
            <FieldRow
              icon={<HomeIcon className="profile-readonly-icon" />}
              label="Address"
              value={person.address}
            />
          </Box>

          <Avatar className="profile-person-avatar" src={person.imagePath}>
            <PersonIcon className="profile-avatar-icon" />
          </Avatar>
        </Box>
      </Box>

      <Divider className="profile-section-divider" />

      {/* Login Information */}
      <Box className="profile-section">
        <Typography className="profile-section-title">
          Login Information
        </Typography>
        <Box className="profile-login-row">
          <FieldRow
            icon={<PinIcon className="profile-readonly-icon" />}
            label="User ID"
            value={user.userID}
          />
          <FieldRow
            icon={<PersonIcon className="profile-readonly-icon" />}
            label="Username"
            value={user.userName}
          />
          <FieldRow
            icon={<BadgeIcon className="profile-readonly-icon" />}
            label="Is Active"
            value={
              user.isActive === undefined ? "" : user.isActive ? "Yes" : "No"
            }
          />
        </Box>
      </Box>

      <Divider className="profile-section-divider" />

      {/* Change Password */}
      <Box className="profile-section">
        <Box className="profile-password-fields">
          <TextField
            className="modal-textfield"
            label="Current Password"
            type="password"
            value={currentPassword}
            onChange={(e) => setCurrentPassword(e.target.value)}
            fullWidth
          />
          <TextField
            className="modal-textfield"
            label="New Password"
            type="password"
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            fullWidth
          />
          <TextField
            className="modal-textfield"
            label="Confirm Password"
            type="password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            fullWidth
          />
        </Box>
      </Box>
      {passwordError && (
        <Alert severity="error" variant="filled" sx={{ mb: 2 }}>
          {passwordError}
        </Alert>
      )}
      {updatingstatus === "succeeded" && (
        <Alert severity="success" variant="filled" sx={{ mb: 2 }}>
          Password updated successfully ✅
        </Alert>
      )}
      {updatingstatus === "failed" && (
        <Alert severity="error" variant="filled" sx={{ mb: 2 }}>
          Failed to update password ❌
        </Alert>
      )}
      <Box className="profile-drawer-actions">
        <Button
          className="modal-btn-cancel"
          startIcon={<CloseIcon />}
          onClick={onClose}
        >
          Close
        </Button>
        <Button
          className="modal-btn-save"
          startIcon={<SaveIcon />}
          onClick={onSave || handleSave}
        >
          Save
        </Button>
      </Box>
    </Box>
  );
}
