import CircularProgress from "@mui/material/CircularProgress";
import Box from "@mui/material/Box";

export default function CircularIndeterminate() {
  return (
    <Box
      sx={{
        width: "100%",
        justifyContent: "center",
        display: "flex",
        marginTop: "5%",
      }}
    >
      <CircularProgress aria-label="Loading…" />
    </Box>
  );
}
