import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Box,
  Typography,
  Radio,
  RadioGroup,
  FormControlLabel,
  Button,
  CircularProgress,
  Alert,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import PublishIcon from "@mui/icons-material/Publish";
import AssignmentIcon from "@mui/icons-material/Assignment";

import LicenseFilter from "../License/LicenseFilter";
import { LicenseInfoContent } from "../License/Showlicenseinfo";
import InfoCard from "../InfoCard";
import Field from "../Field";
import { replaceLicense } from "../../Store/features/Licenses/LicensesSlice";
import { getApplicationTypes } from "../../Store/features/ApplicationType/ApplicationTypeSlice";
const APPLICATION_TYPE = {
  damaged: 4,
  lost: 3,
};

const REASON_TITLE = {
  damaged: "Damaged License",
  lost: "Lost License",
};

const formatDate = (isoDate) => {
  if (!isoDate) return "";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

export default function ReplaceLicenseModal({ open, onClose }) {
  const dispatch = useDispatch();
  //  كل الـ useState أولاً

  const [filterInput, setFilterInput] = useState("");
  const [committedLicenseId, setCommittedLicenseId] = useState(null);
  const [replacementReason, setReplacementReason] = useState("damaged");
  const [searchError, setSearchError] = useState(null);
  const [issuedApplicationID, setIssuedApplicationID] = useState(null);
  const [issuedNewLicenseID, setIssuedNewLicenseID] = useState(null);
  // useSelector
  const currentUser = useSelector((state) => state.users.currentUser);
  const replaceStatus = useSelector((state) => state.licenses.replaceStatus);
  const replaceError = useSelector((state) => state.licenses.error);
  const applicationTypes = useSelector((state) => state.ApplicationType.list);

  const applicationFees = applicationTypes.find(
    (t) => t.application_type_id === APPLICATION_TYPE[replacementReason],
  )?.application_fees;

  const isLoading = replaceStatus === "loading";
  const alreadyIssued = Boolean(issuedNewLicenseID);
  const canIssue = Boolean(committedLicenseId) && !isLoading && !alreadyIssued;
  useEffect(() => {
    if (!open) return;
    dispatch(getApplicationTypes());
  }, [open, dispatch]);
  const resetAll = () => {
    setFilterInput("");
    setCommittedLicenseId(null);
    setReplacementReason("damaged");
    setIssuedApplicationID(null);
    setIssuedNewLicenseID(null);
    setSearchError(null);
  };

  const handleClose = () => {
    resetAll();
    onClose();
  };

  const handleSearch = () => {
    const idNum = Number(filterInput);
    if (!idNum) {
      setSearchError("الرجاء إدخال رقم رخصة صحيح");
      setCommittedLicenseId(null);
      return;
    }
    setSearchError(null);
    setCommittedLicenseId(idNum);
    setIssuedApplicationID(null);
    setIssuedNewLicenseID(null);
  };

  const handleIssue = async () => {
    if (!committedLicenseId) return;
    try {
      const result = await dispatch(
        replaceLicense({
          oldLicenseId: committedLicenseId,
          issueReason: APPLICATION_TYPE[replacementReason],
          createdByUserId: currentUser?.userID,
        }),
      ).unwrap();

      setIssuedApplicationID(result.applicationID);
      setIssuedNewLicenseID(result.licenseID);
    } catch (err) {
      console.error("Replace license failed:", err);
    }
  };

  useEffect(() => {
    if (replaceStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [replaceStatus]);

  const title = `Replacement for ${REASON_TITLE[replacementReason]}`;

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          {title}
        </Typography>

        <Box
          sx={{
            display: "flex",
            gap: 3,
            alignItems: "flex-start",
            flexWrap: "wrap",
          }}
        >
          <Box sx={{ flex: "1 1 auto", minWidth: 260 }}>
            <LicenseFilter
              value={filterInput}
              onChange={(e) => setFilterInput(e.target.value)}
              onSearch={handleSearch}
              error={searchError}
            />
          </Box>

          <Box sx={{ flex: "0 0 auto" }}>
            <Typography className="license-info-field-label" sx={{ mb: 1 }}>
              Replacement For:
            </Typography>
            <RadioGroup
              value={replacementReason}
              onChange={(e) => setReplacementReason(e.target.value)}
            >
              <FormControlLabel
                value="damaged"
                control={<Radio size="small" />}
                label="Damaged License"
              />
              <FormControlLabel
                value="lost"
                control={<Radio size="small" />}
                label="Lost License"
              />
            </RadioGroup>
          </Box>
        </Box>

        {committedLicenseId ? (
          <Box sx={{ mt: 2 }}>
            <LicenseInfoContent licenseId={committedLicenseId} />
          </Box>
        ) : (
          <Typography className="license-info-field-value-empty" sx={{ mt: 2 }}>
            ابحث برقم الرخصة أولاً
          </Typography>
        )}

        {committedLicenseId && (
          <InfoCard
            icon={AssignmentIcon}
            title="APPLICATION INFO FOR LICENSE REPLACEMENT"
          >
            <Field
              icon={AssignmentIcon}
              label="L.R. Application ID"
              value={issuedApplicationID}
            />
            <Field label="Replaced License ID" value={issuedNewLicenseID} />
            <Field
              label="Application Date"
              value={
                issuedApplicationID
                  ? formatDate(new Date().toISOString())
                  : undefined
              }
            />
            <Field label="Old License ID" value={committedLicenseId} />
            <Field label="Application Fees" value={applicationFees} />{" "}
            <Field
              label="Created By"
              value={currentUser?.user_name ?? currentUser?.userID}
            />
          </InfoCard>
        )}

        {replaceStatus === "succeeded" && (
          <Alert severity="success" variant="filled" sx={{ mt: 2 }}>
            License replaced successfully ✅
          </Alert>
        )}

        {replaceStatus === "failed" && replaceError && (
          <Alert severity="error" variant="filled" sx={{ mt: 2 }}>
            {typeof replaceError === "string"
              ? replaceError
              : "فشل استبدال الرخصة"}
          </Alert>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button
          variant="contained"
          color="error"
          startIcon={<CloseIcon />}
          onClick={handleClose}
          className="modal-btn-cancel"
        >
          Close
        </Button>
        <Button
          variant="contained"
          startIcon={
            isLoading ? (
              <CircularProgress size={16} color="inherit" />
            ) : (
              <PublishIcon />
            )
          }
          onClick={handleIssue}
          disabled={!canIssue}
          className="modal-btn-save"
        >
          Issue Replacement
        </Button>
      </DialogActions>
    </Dialog>
  );
}
