import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import ManageAccountsIcon from "@mui/icons-material/ManageAccounts";

//*************Loading Tools */
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
//*************Loading Tools */

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import { addUser, getAllUsers } from "../Store/features/Users/userSlice";
import { getPeople } from "../Store/features/people/peopleSlice";

import Filter from "../Shared/Filter";
import AddUser from "../Add/AddUser";
import UserDetailsModal from "../Popups/UserDetailsModal";
import DeleteUser from "../Delete/DeleteUser";
import UpdateUser from "../Update/UpdateUser";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  UserID: "id",
  UserName: "userName",
  FullName: "fullName",
  IsActive: "isActive",
};

// شاشة Manage Users — Component عرض فقط، بلا بيانات وهمية
export default function ManageUsersScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");
  const [isAddOpen, setIsAddOpen] = useState(false);

  // ── حالة صف مختار / شاشة تفاصيل اليوزر ──
  const [detailsUserId, setDetailsUserId] = useState(null);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);
  const [deleteUserId, setDeleteUserId] = useState(null);
  const [isDeleteOpen, setIsDeleteOpen] = useState(false);
  const [updateUserId, setUpdateUserId] = useState(null);
  const [isUpdateOpen, setIsUpdateOpen] = useState(false);

  const dispatch = useDispatch();

  // useSelector: بيقرأ فقط الجزء الخاص بـ people من الـ state الكلي
  const Users = useSelector((state) => state.users.list);
  const status = useSelector((state) => state.users.status);
  const error = useSelector((state) => state.users.error);
  useEffect(() => {
    dispatch(getAllUsers());
  }, [dispatch]);
  useEffect(() => {
    dispatch(getPeople());
  }, [dispatch]);
  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }
  const rows = Users.map((user) => ({
    id: user.user_id,
    userName: user.user_name,
    fullName: user.FullName,
    isActive: user.is_active ? "Yes" : "No",
  }));

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "fullName"
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  // ── معالج الضغطة الواحدة (single click) على صف ──
  const handleRowClick = (row) => {
    setDetailsUserId(row.id);
    setIsDetailsOpen(true);
  };

  const handleUpdate = (userId) => {
    setIsDetailsOpen(false);
    setUpdateUserId(userId);
    setIsUpdateOpen(true);
  };

  const handleDelete = (userId) => {
    setIsDetailsOpen(false);
    setDeleteUserId(userId);
    setIsDeleteOpen(true);
  };

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <Box className="people-header-wrapper">
          <Box className="people-header-icon-wrapper">
            <ManageAccountsIcon className="people-header-icon" />
          </Box>
          <Typography variant="h4" className="people-header-title">
            Manage Users
          </Typography>
          <Typography variant="h6" className="people-header-title">
            (Select Row and double click on it)
          </Typography>
        </Box>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setIsAddOpen(true)}
            className="people-add-btn"
          >
            Add User
          </Button>
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  User ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  User Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Is Active
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow
                  key={row.id}
                  className="people-table-row"
                  onClick={() => handleRowClick(row)}
                  sx={{ cursor: "pointer" }}
                >
                  <TableCell className="people-table-cell-id">
                    {row.id}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.userName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.fullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.isActive}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>
      </Paper>

      <AddUser open={isAddOpen} onClose={() => setIsAddOpen(false)} />

      <UserDetailsModal
        open={isDetailsOpen}
        onClose={() => setIsDetailsOpen(false)}
        userId={detailsUserId}
        onUpdate={handleUpdate}
        onDelete={handleDelete}
      />

      <DeleteUser
        open={isDeleteOpen}
        onClose={() => setIsDeleteOpen(false)}
        userId={deleteUserId}
      />

      <UpdateUser
        open={isUpdateOpen}
        onClose={() => setIsUpdateOpen(false)}
        userId={updateUserId}
      />
    </Box>
  );
}
