import React, { useState, useCallback } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  AppBar,
  Toolbar,
  Box,
  IconButton,
  Button,
  Menu,
  MenuItem,
} from "@mui/material";
import {
  PeopleAlt,
  DriveEta,
  ManageAccounts,
  Menu as MenuIcon,
  Home as HomeIcon,
  FolderCopy,
  ChevronRight,
  ContentPaste,
  Lock,
  ReceiptLong,
  Assignment,
  ContactPage,
  Autorenew,
  ErrorOutline,
  LockOpen,
  PersonAdd,
  Diversity3,
  AccountBox,
  ExitToApp,
} from "@mui/icons-material";
import EditCalendarIcon from "@mui/icons-material/EditCalendar";
import NewLocalDrivingLicenseApplication from "../Add/NewLocalDrivingLicenseApplication"; // ظبط المسار حسب مكان الملف
import DrivingCarAnimation from "./DrivingCarAnimation";
import MobileMainScreen from "../Mobile/MobileMainScreen";
import ManageApplicationTypesScreen from "../Screens/ManageApplicationTypesScreen";
import ManageTestTypesScreen from "../Screens/ManageTestTypesScreen";
import DetainLicenseModal from "../Shared/Application/DetainLicenseModal";
import ReleaseDetainedLicenseModal from "../Shared/Application/ReleaseDetainedLicenseModal";
import CurrentUserInfoPanel from "../Popups/CurrentUserInfoPanel";
import { clearSession } from "../utils/session";
import OfflinePinSharpIcon from "@mui/icons-material/OfflinePinSharp";
import ReplaceLicenseModal from "../Shared/Application/ReplaceLicenseModal";
import IssueInternationalLicenseModal from "../Shared/Application/IssueInternationalLicenseModal";
import RenewLicenseModal from "../Shared/Application/RenewLicenseModal"; // ظبط المسار حسب مكان الملف الفعلي
const SUBMENU_ANCHOR_PROPS = {
  anchorOrigin: { vertical: "top", horizontal: "right" },
  transformOrigin: { vertical: "top", horizontal: "left" },
};

export default function TopBarButtons() {
  //console.log("TopBarButtons RENDER"); // ✅ ضيف هيك سطر وحيد
  const navigate = useNavigate();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [isNewLocalLicenseOpen, setIsNewLocalLicenseOpen] = useState(false);
  // Applications menu (متعدد المستويات)
  const [appsAnchor, setAppsAnchor] = useState(null);
  const [drivingAnchor, setDrivingAnchor] = useState(null);
  const [newLicenseAnchor, setNewLicenseAnchor] = useState(null);
  const [detainAnchor, setDetainAnchor] = useState(null);
  const [accountAnchor, setAccountAnchor] = useState(null);
  const [isReplaceLicenseOpen, setIsReplaceLicenseOpen] = useState(false);
  // الشاشات المنبثقة (Dialogs) التي ما زالت تفتح من قائمة Applications
  const [isAppTypesOpen, setIsAppTypesOpen] = useState(false);
  const [isTestTypesOpen, setIsTestTypesOpen] = useState(false);
  const [isDetainOpen, setIsDetainOpen] = useState(false);
  const [isReleaseOpen, setIsReleaseOpen] = useState(false);
  const [isCurrentUserOpen, setIsCurrentUserOpen] = useState(false);
  const [isIssueInternationalOpen, setIsIssueInternationalOpen] =
    useState(false);
  const [isRenewLicenseOpen, setIsRenewLicenseOpen] = useState(false);
  const handleDrawerToggle = useCallback(() => setMobileOpen((p) => !p), []);

  const closeAllMenus = useCallback(() => {
    setAppsAnchor(null);
    setDrivingAnchor(null);
    setNewLicenseAnchor(null);
    setDetainAnchor(null);
  }, []);

  const handleSignOut = useCallback(() => {
    setAccountAnchor(null);
    clearSession();
    // لاحقاً هنا فقط: dispatch(signOut())
    navigate("/");
  }, [navigate]);

  return (
    <>
      <AppBar position="static" className="nav-app-bar">
        <Toolbar className="nav-toolbar">
          <Box className="nav-toolbar-left">
            <IconButton
              color="inherit"
              edge="start"
              onClick={handleDrawerToggle}
              className="nav-mobile-btn"
            >
              <MenuIcon />
            </IconButton>

            <Box className="nav-desktop-links">
              <Link to="/Home" className="nav-link">
                <Button
                  startIcon={<HomeIcon />}
                  color="inherit"
                  className="nav-btn"
                >
                  Home
                </Button>
              </Link>

              {/* ── Applications ── */}
              <Button
                startIcon={<FolderCopy />}
                color="inherit"
                className="nav-btn"
                onClick={(e) => setAppsAnchor(e.currentTarget)}
              >
                Applications
              </Button>

              <Menu
                anchorEl={appsAnchor}
                open={Boolean(appsAnchor)}
                onClose={closeAllMenus}
              >
                <MenuItem
                  onClick={(e) => setDrivingAnchor(e.currentTarget)}
                  className="submenu-item-row submenu-item-wide"
                >
                  <span className="submenu-item-label">
                    <DriveEta className="submenu-icon" /> Driving Licenses
                    Services
                  </span>
                  <ChevronRight fontSize="small" />
                </MenuItem>

                <MenuItem
                  component={Link}
                  to="/manage-Local"
                  onClick={closeAllMenus}
                >
                  <ContentPaste className="submenu-icon" /> Local Driving
                  License Applications
                </MenuItem>
                <MenuItem
                  component={Link}
                  to="/manage-International"
                  onClick={closeAllMenus}
                >
                  <ContentPaste className="submenu-icon" /> International
                  License Applications
                </MenuItem>

                <MenuItem
                  onClick={(e) => setDetainAnchor(e.currentTarget)}
                  className="submenu-item-row"
                >
                  <span className="submenu-item-label">
                    <Lock className="submenu-icon" /> Detain Licenses
                  </span>
                  <ChevronRight fontSize="small" />
                </MenuItem>
                <Link to="/manage-Licenses" className="nav-link">
                  <MenuItem
                    onClick={() => {
                      closeAllMenus();
                    }}
                  >
                    <OfflinePinSharpIcon className="submenu-icon" />
                    Licenses
                  </MenuItem>
                </Link>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsAppTypesOpen(true);
                  }}
                >
                  <ReceiptLong className="submenu-icon" /> Manage Application
                  Types
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsTestTypesOpen(true);
                  }}
                >
                  <Assignment className="submenu-icon" /> Manage Test Types
                </MenuItem>
              </Menu>

              {/* Driving Licenses Services (فرعية) */}
              <Menu
                anchorEl={drivingAnchor}
                open={Boolean(drivingAnchor)}
                onClose={() => setDrivingAnchor(null)}
                {...SUBMENU_ANCHOR_PROPS}
              >
                <MenuItem
                  onClick={(e) => setNewLicenseAnchor(e.currentTarget)}
                  className="submenu-item-row submenu-item-extra"
                >
                  <span className="submenu-item-label">
                    <ContactPage className="submenu-icon" /> New Driving License
                  </span>
                  <ChevronRight fontSize="small" />
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsRenewLicenseOpen(true);
                  }}
                >
                  <Autorenew className="submenu-icon" /> Renew Driving License
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsReplaceLicenseOpen(true);
                  }}
                >
                  <ErrorOutline className="submenu-icon" /> Replacement for Lost
                  or Damaged License
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsReleaseOpen(true);
                  }}
                >
                  <LockOpen className="submenu-icon" /> Release Detained Driving
                  License
                </MenuItem>
                <MenuItem
                  component={Link}
                  to="/manage-Local"
                  onClick={closeAllMenus}
                >
                  <Assignment className="submenu-icon" /> Retake Test
                </MenuItem>
              </Menu>

              {/* New Driving License (فرعية ثانية) */}
              <Menu
                anchorEl={newLicenseAnchor}
                open={Boolean(newLicenseAnchor)}
                onClose={() => setNewLicenseAnchor(null)}
                {...SUBMENU_ANCHOR_PROPS}
              >
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setNewLicenseAnchor(null); // القائمة الفرعية التالتة محتاجة تتقفل هي كمان
                    setIsNewLocalLicenseOpen(true);
                  }}
                >
                  <PersonAdd className="submenu-accent-icon" /> First Time
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setNewLicenseAnchor(null); // نفس نمط "First Time" فوقه — قفل القائمة الفرعية الثالثة
                    setIsIssueInternationalOpen(true);
                  }}
                >
                  <Diversity3 className="submenu-accent-icon" /> International
                  License Holder
                </MenuItem>
              </Menu>

              {/* Detain Licenses (فرعية) */}
              <Menu
                anchorEl={detainAnchor}
                open={Boolean(detainAnchor)}
                onClose={() => setDetainAnchor(null)}
                {...SUBMENU_ANCHOR_PROPS}
              >
                <MenuItem
                  component={Link}
                  to="/manage-DetainedLicensesS"
                  onClick={closeAllMenus}
                >
                  <Lock className="submenu-icon" /> Manage Detained Licenses
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsDetainOpen(true);
                  }}
                >
                  <Lock className="submenu-icon" /> Detain License
                </MenuItem>
                <MenuItem
                  onClick={() => {
                    closeAllMenus();
                    setIsReleaseOpen(true);
                  }}
                >
                  <Lock className="submenu-icon" /> Release Detained License
                </MenuItem>
              </Menu>
              <Link to="/manage-AllAppointments" className="nav-link">
                <Button
                  startIcon={<EditCalendarIcon />}
                  color="inherit"
                  className="nav-btn"
                >
                  AllAppointments
                </Button>
              </Link>
              <Link to="/manage-people" className="nav-link">
                <Button
                  startIcon={<PeopleAlt />}
                  color="inherit"
                  className="nav-btn"
                >
                  People
                </Button>
              </Link>
              <Link to="/manage-drivers" className="nav-link">
                <Button
                  startIcon={<DriveEta />}
                  color="inherit"
                  className="nav-btn"
                >
                  Drivers
                </Button>
              </Link>
              <Link to="/manage-users" className="nav-link">
                <Button
                  startIcon={<ManageAccounts />}
                  color="inherit"
                  className="nav-btn"
                >
                  Users
                </Button>
              </Link>

              {/* Account Settings */}
              <Button
                startIcon={<ManageAccounts />}
                color="inherit"
                className="nav-btn"
                onClick={(e) => setAccountAnchor(e.currentTarget)}
              >
                Account Settings
              </Button>
              <Menu
                anchorEl={accountAnchor}
                open={Boolean(accountAnchor)}
                onClose={() => setAccountAnchor(null)}
              >
                <MenuItem
                  onClick={() => {
                    setAccountAnchor(null);
                    setIsCurrentUserOpen(true);
                  }}
                >
                  <AccountBox className="submenu-icon" /> Current User Info
                </MenuItem>
                <MenuItem
                  onClick={handleSignOut}
                  className="submenu-danger-item"
                >
                  <ExitToApp className="submenu-icon" /> Sign Out
                </MenuItem>
              </Menu>
            </Box>
          </Box>

          <Box className="nav-car-wrapper">
            <Link to="/Home" className="nav-link">
              <DrivingCarAnimation />
            </Link>
          </Box>
        </Toolbar>
      </AppBar>
      {/* القائمة الجانبية للموبايل — ملف مستقل بنفس الربط */}
      <MobileMainScreen open={mobileOpen} onClose={handleDrawerToggle} />
      {/* الشاشات المنبثقة المرتبطة بقائمة Applications (ما زالت Dialogs) */}
      <ManageApplicationTypesScreen
        open={isAppTypesOpen}
        onClose={() => setIsAppTypesOpen(false)}
      />
      <ManageTestTypesScreen
        open={isTestTypesOpen}
        onClose={() => setIsTestTypesOpen(false)}
      />
      <DetainLicenseModal
        open={isDetainOpen}
        onClose={() => setIsDetainOpen(false)}
      />
      <ReleaseDetainedLicenseModal
        open={isReleaseOpen}
        onClose={() => setIsReleaseOpen(false)}
      />
      <CurrentUserInfoPanel
        open={isCurrentUserOpen}
        onClose={() => setIsCurrentUserOpen(false)}
        person={null}
      />
      <NewLocalDrivingLicenseApplication
        open={isNewLocalLicenseOpen}
        onClose={() => setIsNewLocalLicenseOpen(false)}
      />{" "}
      <ReplaceLicenseModal
        open={isReplaceLicenseOpen}
        onClose={() => setIsReplaceLicenseOpen(false)}
      />
      <IssueInternationalLicenseModal
        open={isIssueInternationalOpen}
        onClose={() => setIsIssueInternationalOpen(false)}
      />
      <RenewLicenseModal
        open={isRenewLicenseOpen}
        onClose={() => setIsRenewLicenseOpen(false)}
      />
    </>
  );
}
