import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import HomeWorkIcon from "@mui/icons-material/HomeWork";
import { Box as MuiBox, Typography } from "@mui/material";
//*************Loading Tools */
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
//*************Loading Tools */

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import {
  addLocalDrivingLicense,
  getAllLocalDrivingLicenses,
} from "../Store/features/LocalDrivingLicense/LocalDrivingLicenseSlice";

import Filter from "../Shared/Filter";
import AddLocalDrivingLicenseApplication from "../Add/AddLocalDrivingLicenseApplication";
import LocalDrivingLicenseApplicationDetailsModal from "../Popups/LocalDrivingLicenseApplicationDetailsModal";
// ✅ نفس الشاشة يلي بتفتح من TopBarButtons عند الضغط على "First Time"
import NewLocalDrivingLicenseApplication from "../Add/NewLocalDrivingLicenseApplication";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  AppID: "id",
  DrivingClass: "drivingClass",
  NationalNo: "nationalNo",
  FullName: "fullName",
  Status: "applicationstatus",
};

export default function ManageLocalDrivingLicenseApplicationsScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [detailsLocalApplicationId, setDetailsLocalApplicationId] =
    useState(null);

  const [isDetailsOpen, setIsDetailsOpen] = useState(false);
  // ✅ جديد: نفس آلية isNewLocalLicenseOpen الموجودة بـ TopBarButtons
  const [isNewLocalLicenseOpen, setIsNewLocalLicenseOpen] = useState(false);

  const dispatch = useDispatch();

  const LocalDrivingLicense = useSelector(
    (state) => state.LocalDrivingLicense.list,
  );
  const status = useSelector((state) => state.LocalDrivingLicense.status);
  //const error = useSelector((state) => state.LocalDrivingLicense.error);

  useEffect(() => {
    dispatch(getAllLocalDrivingLicenses());
  }, [dispatch]);

  const handleRowDoubleClick = (id) => {
    setDetailsLocalApplicationId(id);
    setIsDetailsOpen(true);
  };

  const handleCloseDetails = () => {
    setIsDetailsOpen(false);
    setDetailsLocalApplicationId(null);
  };

  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }
  console.log(LocalDrivingLicense);
  const rows = LocalDrivingLicense.map((license) => ({
    id: license.local_driving_license_application_id,
    drivingClass: license.class_name,
    nationalNo: license.national_no,
    fullName: license.full_name,
    applicationDate: license.application_date,
    passedTests: license.passed_test_count,
    applicationstatus: license.application_status,
  }));

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "applicationstatus"
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <MuiBox className="people-header-wrapper">
          <MuiBox className="people-header-icon-wrapper">
            <HomeWorkIcon className="people-header-icon" />
          </MuiBox>
          <Typography variant="h4" className="people-header-title">
            Local Driving License Applications
          </Typography>
          <Typography variant="h6" className="people-header-title">
            (Select Row and double click on it)
          </Typography>
        </MuiBox>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            // ✅ تم التصحيح: بيفتح نفس شاشة "First Time" مباشرة
            onClick={() => setIsNewLocalLicenseOpen(true)}
            className="people-add-btn"
          >
            New Application
          </Button>
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  L.D.L.AppID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Driving Class
                </TableCell>
                <TableCell className="people-table-head-cell">
                  National No.
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Application Date
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Passed Tests
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Application Status
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow
                  key={row.id}
                  className="people-table-row"
                  // ✅ دبل كليك عالصف بيفتح المودال بالـ id تبعه
                  onDoubleClick={() => handleRowDoubleClick(row.id)}
                  sx={{ cursor: "pointer" }}
                >
                  <TableCell className="people-table-cell-id">
                    {row.id}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.drivingClass}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.nationalNo}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.fullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.applicationDate}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.passedTests}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.applicationstatus}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>
      </Paper>

      <AddLocalDrivingLicenseApplication
        open={isAddOpen}
        onClose={() => setIsAddOpen(false)}
      />

      {/* مودال تفاصيل الـ application، تفتح بس لما يكون في id محدد */}
      {detailsLocalApplicationId && (
        <LocalDrivingLicenseApplicationDetailsModal
          localApplicationId={detailsLocalApplicationId}
          open={isDetailsOpen}
          onClose={handleCloseDetails}
        />
      )}

      {/* ✅ جديد: نفس شاشة "First Time" الموجودة بـ TopBarButtons */}
      <NewLocalDrivingLicenseApplication
        open={isNewLocalLicenseOpen}
        onClose={() => setIsNewLocalLicenseOpen(false)}
      />
    </Box>
  );
}
