import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  Box,
  Typography,
  TextField,
  Button,
  Select,
  MenuItem,
  Divider,
  Alert,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import AssignmentIcon from "@mui/icons-material/Assignment";
import { useSelector, useDispatch } from "react-redux";

import PersonInfoPanel from "../Shared/Person/PersonInfoPanel";
import InfoCard from "../Shared/InfoCard";
import Field from "../Shared/Field";
import {
  selectPersonById,
  getPeople,
} from "../Store/features/people/peopleSlice";
import { getLicenseClasses } from "../Store/features/licenseClass/licenseClassSlice";
import {
  addLocalDrivingLicenseAsync,
  resetAddStatus,
} from "../Store/features/LocalDrivingLicense/LocalDrivingLicenseSlice";
import FeildAlert from "../Popups/FailedAlert";

const NEW_DRIVING_LICENSE_APPLICATION_TYPE_ID = 1;

const formatDate = (isoDate) => {
  if (!isoDate) return "";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

export default React.memo(function NewLocalDrivingLicenseApplication({
  open,
  onClose,
}) {
  const dispatch = useDispatch();

  useEffect(() => {
    if (open) {
      dispatch(getPeople());
      dispatch(getLicenseClasses());
    }
  }, [open, dispatch]);

  const licenseClasses = useSelector((state) => state.LicenseClass.list);
  const currentUser = useSelector((state) => state.users.currentUser);
  const addStatus = useSelector((state) => state.LocalDrivingLicense.addStatus);
  const addError = useSelector((state) => state.LocalDrivingLicense.error);

  const [personIdInput, setPersonIdInput] = useState("");
  const [searchedPersonId, setSearchedPersonId] = useState(null);
  const [searchError, setSearchError] = useState("");

  const foundPerson = useSelector((state) =>
    searchedPersonId ? selectPersonById(state, searchedPersonId) : null,
  );
  const personNotFound = searchedPersonId !== null && !foundPerson;

  const handleSearch = () => {
    const idNum = Number(personIdInput);
    if (!personIdInput || Number.isNaN(idNum)) {
      setSearchError("Please enter a valid Person ID");
      setSearchedPersonId(null);
      return;
    }
    setSearchedPersonId(idNum);
    setSearchError("");
  };

  const [licenseClassId, setLicenseClassId] = useState("");

  const selectedClass = licenseClasses.find(
    (c) => c.license_class_id === licenseClassId,
  );
  const applicationFees = selectedClass?.class_fees ?? "";

  const today = new Date();

  const isFormValid = Boolean(foundPerson) && Boolean(licenseClassId);

  const handleSave = () => {
    if (!isFormValid) return;

    const nowIso = today.toISOString();

    dispatch(
      addLocalDrivingLicenseAsync({
        applicationID: 0,
        applicantPersonID: searchedPersonId,
        applicationDate: nowIso,
        applicationTypeID: NEW_DRIVING_LICENSE_APPLICATION_TYPE_ID,
        applicationStatus: 1,
        lastStatusDate: nowIso,
        paidFees: applicationFees,
        createdByUserID: currentUser?.userID,
        localDrivingLicenseApplicationID: 0,
        licenseClassID: licenseClassId,
      }),
    );
  };

  const handleClose = () => {
    setPersonIdInput("");
    setSearchedPersonId(null);
    setSearchError("");
    setLicenseClassId("");
    dispatch(resetAddStatus());
    onClose();
  };

  useEffect(() => {
    if (addStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [addStatus]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog"
    >
      <DialogContent
        className="modal-content"
        sx={{ px: { xs: 3, md: 5 }, py: 4 }}
      >
        <Typography
          className="modal-red-title"
          variant="h5"
          align="center"
          sx={{ mb: 3 }}
        >
          New Local Driving License Application
        </Typography>

        <Box sx={{ display: "flex", gap: 2, alignItems: "flex-start", mb: 2 }}>
          <TextField
            className="modal-textfield"
            label="Person ID"
            value={personIdInput}
            onChange={(e) => setPersonIdInput(e.target.value)}
            size="small"
            sx={{ maxWidth: 200 }}
          />
          <Button
            variant="outlined"
            startIcon={<SearchIcon />}
            onClick={handleSearch}
            className="user-verify-btn"
          >
            Search
          </Button>
        </Box>

        {searchError && <FeildAlert>{searchError}</FeildAlert>}
        {personNotFound && (
          <FeildAlert>No person found with this ID</FeildAlert>
        )}

        {foundPerson && (
          <>
            <Divider className="profile-section-divider" sx={{ my: 2 }} />
            <PersonInfoPanel personId={searchedPersonId} />
          </>
        )}

        {foundPerson && (
          <>
            <Divider className="profile-section-divider" sx={{ my: 3 }} />

            {addStatus === "failed" && (
              <Alert severity="error" variant="filled" sx={{ mb: 2 }}>
                {addError || "Failed to create application"}
              </Alert>
            )}
            {addStatus === "succeeded" && (
              <Alert severity="success" variant="filled" sx={{ mb: 2 }}>
                Application created successfully ✅
              </Alert>
            )}

            <InfoCard icon={AssignmentIcon} title="APPLICATION INFORMATION">
              <Field
                icon={AssignmentIcon}
                label="D.L Application ID"
                value={undefined}
              />
              <Field
                label="Application Date"
                value={formatDate(today.toISOString())}
              />

              <Box className="license-info-field" sx={{ gridColumn: "1 / -1" }}>
                <Box className="license-info-field-label">License Class</Box>
                <Select
                  className="modal-textfield"
                  value={licenseClassId}
                  onChange={(e) => setLicenseClassId(e.target.value)}
                  displayEmpty
                  fullWidth
                  size="small"
                >
                  <MenuItem value="">
                    <em>Select License Class</em>
                  </MenuItem>
                  {licenseClasses.map((c) => (
                    <MenuItem
                      key={c.license_class_id}
                      value={c.license_class_id}
                    >
                      {c.class_name}
                    </MenuItem>
                  ))}
                </Select>
              </Box>

              <Field label="Application Fees" value={applicationFees} />
              <Field label="Created By" value={currentUser?.userName} />
            </InfoCard>

            <Box
              className="modal-actions"
              sx={{
                display: "flex",
                justifyContent: "flex-end",
                gap: 2,
                mt: 3,
              }}
            >
              <Button onClick={handleClose} className="modal-btn-cancel">
                Close
              </Button>
              <Button
                onClick={handleSave}
                className="modal-btn-save"
                variant="contained"
                disabled={
                  !isFormValid ||
                  addStatus === "loading" ||
                  addStatus === "succeeded"
                }
              >
                Save
              </Button>
            </Box>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
});
