import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import LockIcon from "@mui/icons-material/Lock";

import LicenseFilter from "../License/LicenseFilter";
import { LicenseInfoContent } from "../License/Showlicenseinfo";
import DetainInfo from "./DetainInfo";
import { getLicenses } from "../../Store/features/Licenses/LicensesSlice";
import {
  getDetainedLicenses,
  detainLicense,
} from "../../Store/features/DetainedLicenses/DetainedLicensesSlice"; // ⚠️ عدّل المسار حسب مكان الملف الفعلي عندك

export default function DetainLicenseModal({ open, onClose }) {
  const dispatch = useDispatch();

  const [filterInput, setFilterInput] = useState("");
  const [committedLicenseId, setCommittedLicenseId] = useState(null);
  const [searchError, setSearchError] = useState(null);
  const [fineFees, setFineFees] = useState("");
  const [detainedResult, setDetainedResult] = useState(null);

  const currentUser = useSelector((state) => state.users.currentUser);
  const licensesList = useSelector((state) => state.licenses.list);
  const detainedList = useSelector((state) => state.DetainedLicenses.list); // ⚠️ عدّل اسم الـ slice لو مختلف
  const detainStatus = useSelector(
    (state) => state.DetainedLicenses.detainStatus,
  );
  const detainError = useSelector((state) => state.DetainedLicenses.error);

  const isLoading = detainStatus === "loading";
  const alreadyDetained = Boolean(detainedResult);
  const canDetain =
    Boolean(committedLicenseId) &&
    fineFees !== "" &&
    Number(fineFees) >= 0 &&
    !isLoading &&
    !alreadyDetained;

  useEffect(() => {
    if (!open) return;
    dispatch(getLicenses());
    dispatch(getDetainedLicenses());
  }, [open, dispatch]);

  const resetAll = () => {
    setFilterInput("");
    setCommittedLicenseId(null);
    setSearchError(null);
    setFineFees("");
    setDetainedResult(null);
  };

  const handleClose = () => {
    resetAll();
    onClose();
  };

  const handleSearch = () => {
    const idNum = Number(filterInput);
    if (!idNum) {
      setSearchError("الرجاء إدخال رقم رخصة صحيح");
      setCommittedLicenseId(null);
      return;
    }

    const foundLicense = licensesList.find((l) => l.license_id === idNum);

    if (!foundLicense) {
      setSearchError("لا توجد رخصة بهذا الرقم");
      setCommittedLicenseId(null);
      return;
    }

    if (!foundLicense.is_active) {
      setSearchError(
        "هذه الرخصة غير مفعّلة (Inactive) — الرجاء اختيار رخصة Active فقط",
      );
      setCommittedLicenseId(null);
      return;
    }

    const alreadyHasActiveDetain = detainedList.some(
      (d) => d.licenseID === idNum && !d.isReleased,
    );
    if (alreadyHasActiveDetain) {
      setSearchError("هذه الرخصة محتجزة (Detained) بالفعل");
      setCommittedLicenseId(null);
      return;
    }

    setSearchError(null);
    setCommittedLicenseId(idNum);
    setDetainedResult(null);
  };

  const handleDetain = async () => {
    if (!committedLicenseId) return;

    const nowISO = new Date().toISOString();

    const payload = {
      detainID: 0,
      licenseID: committedLicenseId,
      detainDate: nowISO,
      fineFees: Number(fineFees),
      createdByUserID: currentUser?.userID,
      isReleased: false,
    };

    try {
      const result = await dispatch(detainLicense(payload)).unwrap();
      setDetainedResult(result);
    } catch (err) {
      console.error("Detain license failed:", err);
    }
  };

  // ✅ إغلاق تلقائي بعد نجاح الاحتجاز
  useEffect(() => {
    if (detainStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [detainStatus]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        {isLoading && (
          <Box className="detain-license-loading-overlay">
            <CircularProgress />
          </Box>
        )}

        <Typography variant="h5" className="modal-red-title">
          Detain License
        </Typography>

        <LicenseFilter
          value={filterInput}
          onChange={(e) => setFilterInput(e.target.value)}
          onSearch={handleSearch}
          error={searchError}
        />

        {committedLicenseId ? (
          <Box className="replace-license-license-info">
            <LicenseInfoContent licenseId={committedLicenseId} />
          </Box>
        ) : (
          <Typography className="replace-license-placeholder">
            ابحث برقم الرخصة أولاً
          </Typography>
        )}

        {committedLicenseId && (
          <DetainInfo
            detainID={detainedResult?.detainID}
            licenseID={committedLicenseId}
            detainDate={detainedResult?.detainDate ?? new Date().toISOString()}
            fineFees={fineFees}
            onFineFeesChange={setFineFees}
            createdByLabel={currentUser?.user_name ?? currentUser?.userID}
          />
        )}

        {detainStatus === "succeeded" && (
          <Alert severity="success" variant="filled" sx={{ mt: 2 }}>
            License detained successfully ✅
          </Alert>
        )}

        {detainStatus === "failed" && detainError && (
          <Alert severity="error" variant="filled" sx={{ mt: 2 }}>
            {typeof detainError === "string"
              ? detainError
              : "فشل احتجاز الرخصة"}
          </Alert>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button
          variant="contained"
          color="error"
          startIcon={<CloseIcon />}
          onClick={handleClose}
          className="modal-btn-cancel"
        >
          Close
        </Button>
        <Button
          variant="contained"
          startIcon={
            isLoading ? (
              <CircularProgress size={16} color="inherit" />
            ) : (
              <LockIcon />
            )
          }
          onClick={handleDetain}
          disabled={!canDetain}
          className="modal-btn-save"
        >
          Detain
        </Button>
      </DialogActions>
    </Dialog>
  );
}
