import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  addStatus: "idle",
  error: null,
};

export const getAllDrivers = createAsyncThunk(
  "Driver/getAllDrivers",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/Drivers",
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { driver } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (driver.status === "loading" || driver.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);
export const AddDriverAsync = createAsyncThunk(
  "Driver/AddDriverAsync",
  async (driver, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/Drivers",
        driver,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message ||
          err.response?.data ||
          "Add driver failed",
      );
    }
  },
);
const DriverSlice = createSlice({
  name: "Driver",
  initialState,
  reducers: {
    addDriver: (state, action) => {
      // action.payload لازم يكون object للشخص المراد إضافته
      state.list.push(action.payload);
    },
  },
  // extraReducers: هون بنتعامل مع الأكشنز اللي جاية من الـ thunk (خارجية عن reducers العادية)
  extraReducers: (builder) => {
    builder
      .addCase(getAllDrivers.pending, (state) => {
        state.status = "loading";
        console.log("Im Driver and im in the way to come");
        state.error = null;
      })
      .addCase(getAllDrivers.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im Driver and im coming ");
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getAllDrivers.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(AddDriverAsync.pending, (state) => {
        state.addStatus = "loading";
        state.error = null;
      })
      .addCase(AddDriverAsync.fulfilled, (state, action) => {
        state.addStatus = "succeeded";
        // ⚠️ رد POST بيرجع كلاس الـ Driver الخام بصيغة camelCase (driverID, personID...)
        // بينما getAllDrivers() view بيرجع snake_case + حقول مجمّعة (full_name, number_of_active_licenses...)
        // ما موجودة أصلاً بالكلاس الخام. نطبّع الحقول المتوفرة فقط، والباقي بيضل فاضي
        // لحد ما تنعمل getAllDrivers() تانية (refetch) لجلب الاسم الكامل ورقم الرخص الفعلية.
        const p = action.payload;
        const normalized = {
          driver_id: p.driverID,
          person_id: p.personID,
          national_no: null,
          full_name: null,
          created_date: p.createdDate ?? p.creationDate ?? null,
          number_of_active_licenses: 0,
        };
        state.list.push(normalized);
      })
      .addCase(AddDriverAsync.rejected, (state, action) => {
        state.addStatus = "failed";
        state.error = action.payload;
      });
  },
});

export const { addDriver } = DriverSlice.actions;
export default DriverSlice.reducer;
