import React, { useState, useCallback } from "react";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Button,
  Typography,
} from "@mui/material";

import DriverLicenseInfoPanel from "../Shared/License/DriverLicenseInfoPanel";
import DetainInfoPanel from "../Shared/Application/DetainInfoPanel";

// شاشة "Release Detained License" — بحث برخصة محجوزة ثم عرض كامل تفاصيل
// الحجز (variant="full") مع زر Release. findLicenseById لازم توصل لاحقًا
// من الـ API؛ حاليًا بلا مصدر بيانات حقيقي (بانتظار ربط RESTful API)
export default function ReleaseDetainedLicense({
  open,
  onClose,
  findLicenseById,
}) {
  const [licenseId, setLicenseId] = useState("");
  const [license, setLicense] = useState(null);
  const [searchError, setSearchError] = useState("");

  const handleSearch = useCallback(() => {
    const found = findLicenseById ? findLicenseById(licenseId) : null;
    if (!found) {
      setSearchError("License not found");
      setLicense(null);
      return;
    }
    if (!found.isDetained) {
      setSearchError("This license is not currently detained");
      setLicense(null);
      return;
    }
    setSearchError("");
    setLicense(found);
  }, [licenseId, findLicenseById]);

  const handleClose = useCallback(() => {
    setLicenseId("");
    setLicense(null);
    setSearchError("");
    onClose();
  }, [onClose]);

  const handleRelease = useCallback(() => {
    if (!license) return;
    // لاحقاً هنا فقط: dispatch(releaseDetainedLicense(license.id))
    console.log("Release detained license:", license.id);
    handleClose();
  }, [license, handleClose]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          Release Detained License
        </Typography>

        {searchError && (
          <Typography className="modal-error-text">{searchError}</Typography>
        )}

        <DriverLicenseInfoPanel
          licenseId={licenseId}
          onLicenseIdChange={(e) => setLicenseId(e.target.value)}
          onSearch={handleSearch}
          license={license}
          personName={license?.personName}
        />

        <DetainInfoPanel variant="full" detainInfo={license?.detainInfo} />
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button onClick={handleClose} className="modal-btn-cancel">
          Cancel
        </Button>
        <Button
          onClick={handleRelease}
          className="modal-btn-save"
          variant="contained"
          disabled={!license}
        >
          Release
        </Button>
      </DialogActions>
    </Dialog>
  );
}
