import React from "react";
import { TextField, Box } from "@mui/material";
import AssignmentIcon from "@mui/icons-material/Assignment";
import BadgeIcon from "@mui/icons-material/Badge";
import EventIcon from "@mui/icons-material/Event";
import EventBusyIcon from "@mui/icons-material/EventBusy";
import PaidIcon from "@mui/icons-material/Paid";
import PersonIcon from "@mui/icons-material/Person";
import NoteIcon from "@mui/icons-material/Note";
import AutorenewIcon from "@mui/icons-material/Autorenew";

import InfoCard from "../InfoCard";
import Field from "../Field";

const formatDate = (isoDate) => {
  if (!isoDate) return "";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

export default function ApplicationNewLicenseInfo({
  applicationID,
  renewedLicenseID,
  oldLicenseID,
  applicationDate,
  issueDate,
  expirationDate,
  applicationFees,
  licenseFees,
  createdByLabel,
  notes,
  onNotesChange,
  notesReadOnly,
}) {
  const totalFees =
    applicationFees != null && licenseFees != null
      ? Number(applicationFees) + Number(licenseFees)
      : null;

  return (
    <InfoCard icon={AutorenewIcon} title="APPLICATION NEW LICENSE INFO">
      <Field
        icon={AssignmentIcon}
        label="R.L. Application ID"
        value={applicationID}
      />
      <Field
        icon={BadgeIcon}
        label="Renewed License ID"
        value={renewedLicenseID}
      />
      <Field
        icon={EventIcon}
        label="Application Date"
        value={formatDate(applicationDate)}
      />
      <Field icon={BadgeIcon} label="Old License ID" value={oldLicenseID} />
      <Field
        icon={EventIcon}
        label="Issue Date"
        value={formatDate(issueDate)}
      />
      <Field
        icon={EventBusyIcon}
        label="Expiration Date"
        value={formatDate(expirationDate)}
      />
      <Field icon={PaidIcon} label="Application Fees" value={applicationFees} />
      <Field icon={PaidIcon} label="License Fees" value={licenseFees} />
      <Field icon={PaidIcon} label="Total Fees" value={totalFees} />
      <Field icon={PersonIcon} label="Created By" value={createdByLabel} />

      <Box className="license-info-field" sx={{ gridColumn: "1 / -1" }}>
        <Box className="license-info-field-label">
          <NoteIcon className="license-info-field-icon" />
          Notes
        </Box>
        <TextField
          multiline
          minRows={3}
          fullWidth
          size="small"
          value={notes}
          onChange={(e) => onNotesChange(e.target.value)}
          disabled={notesReadOnly}
          className="modal-textfield"
        />
      </Box>
    </InfoCard>
  );
}
