import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  error: null,
};

export const getCountry = createAsyncThunk(
  "Country/getCountry",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/Countries",
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { Country } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (Country.status === "loading" || Country.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);

const testTypesSlice = createSlice({
  name: "Country",
  initialState,
  reducers: {},
  // extraReducers: هون بنتعامل مع الأكشنز اللي جاية من الـ thunk (خارجية عن reducers العادية)
  extraReducers: (builder) => {
    builder
      .addCase(getCountry.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getCountry.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im here country ");
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getCountry.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

export default testTypesSlice.reducer;
