import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [], // هنا رح تنخزن قائمة الـ tests
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  addStatus: "idle",
  updatingstatus: "idle",
  error: null,
};

// createAsyncThunk بيولّد تلقائياً 3 حالات (actions):
// tests/getAllTests/pending
// tests/getAllTests/fulfilled
// tests/getAllTests/rejected

export const getAllTests = createAsyncThunk(
  "tests/getAllTests",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/Tests",
    );
    return response.data; // array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { tests } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (tests.status === "loading" || tests.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);

export const getTestByID = createAsyncThunk(
  "tests/getTestByID",
  async (testId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Tests/${testId}`,
    );
    return response.data; // object مباشرة حسب الـ Swagger
  },
  {
    condition: (testId, { getState }) => {
      const { tests } = getState();
      // إذا موجود أصلاً بالـ list، ما في داعي نجيبه من جديد
      const alreadyInList = tests.list.some((t) => t.testID === testId);
      if (tests.status === "loading" || alreadyInList) {
        return false;
      }
      return true;
    },
  },
);

export const addTest = createAsyncThunk(
  "tests/addTest",
  async (test, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/Tests",
        test,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Add test failed",
      );
    }
  },
);

export const updateTest = createAsyncThunk(
  "tests/updateTest",
  async (test, { rejectWithValue }) => {
    try {
      const response = await axios.put(
        `https://idnan820-001-site1.ltempurl.com/api/Tests/${test.testID}`,
        test,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message ||
          err.response?.data ||
          "Update test failed",
      );
    }
  },
);

const testSlice = createSlice({
  name: "tests",
  initialState,
  reducers: {
    resetAddStatus: (state) => {
      state.addStatus = "idle";
    },
    resetUpdateStatus: (state) => {
      state.updatingstatus = "idle";
    },
  },

  extraReducers: (builder) => {
    builder
      .addCase(getAllTests.pending, (state) => {
        state.status = "loading";
        console.log("Im tests Not done yet");
        state.error = null;
      })
      .addCase(getAllTests.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im tests done");
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getAllTests.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })

      .addCase(getTestByID.pending, (state) => {
        state.status = "loading";
        console.log("Current Test has been worked on");
        state.error = null;
      })
      .addCase(getTestByID.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Current Test has arrived");
        const index = state.list.findIndex(
          (t) => t.testID === action.payload.testID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        } else {
          state.list.push(action.payload);
        }
      })
      .addCase(getTestByID.rejected, (state, action) => {
        state.status = "failed";
        console.log("Current Test has Not arrived");
        state.error = action.error.message;
      })

      .addCase(addTest.pending, (state) => {
        state.addStatus = "loading";
        state.error = null;
      })
      .addCase(addTest.fulfilled, (state, action) => {
        state.addStatus = "succeeded";
        console.log("addTest succeeded");
        state.list.push(action.payload);
      })
      .addCase(addTest.rejected, (state, action) => {
        state.addStatus = "failed";
        console.log("addTest has not succeeded");
        state.error = action.payload;
      })

      .addCase(updateTest.pending, (state) => {
        state.updatingstatus = "loading";
        state.error = null;
      })
      .addCase(updateTest.fulfilled, (state, action) => {
        state.updatingstatus = "succeeded";
        console.log("updateTest succeeded");
        const index = state.list.findIndex(
          (t) => t.testID === action.payload.testID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        }
      })
      .addCase(updateTest.rejected, (state, action) => {
        state.updatingstatus = "failed";
        console.log("updateTest has not succeeded");
        state.error = action.payload;
      });
  },
});

export const selectTestById = (state, testId) =>
  state.tests.list.find((t) => t.testID === testId);

export const { resetAddStatus, resetUpdateStatus } = testSlice.actions;
export default testSlice.reducer;
