import React, { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  Box,
  TextField,
  Button,
  Typography,
} from "@mui/material";
import SmsIcon from "@mui/icons-material/Sms";
import SendIcon from "@mui/icons-material/Send";

export default function SendSmsDialog({
  open,
  onClose,
  recipientName,
  recipientPhone,
}) {
  const [body, setBody] = useState("");
  const [status, setStatus] = useState("idle");

  const handleClose = () => {
    setBody("");
    setStatus("idle");
    onClose();
  };

  const handleSend = () => {
    setStatus("sending");
    // لاحقاً هنا فقط: dispatch(sendSms({ to: recipientPhone, body }))
    setTimeout(() => {
      setStatus("success");
      setTimeout(() => {
        handleClose();
      }, 900);
    }, 1200);
  };

  return (
    <Dialog open={open} onClose={handleClose} fullWidth maxWidth="sm">
      <DialogTitle sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        <SmsIcon /> Send SMS {recipientName ? `to ${recipientName}` : ""}
      </DialogTitle>

      <DialogContent
        sx={{ display: "flex", flexDirection: "column", gap: 2, pt: 1 }}
      >
        <Typography variant="body2" color="text.secondary">
          {recipientPhone || "—"}
        </Typography>

        <TextField
          label="Message"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          fullWidth
          multiline
          rows={4}
        />

        {status === "success" && (
          <Typography color="success.main">SMS sent successfully!</Typography>
        )}

        <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 2 }}>
          <Button onClick={handleClose}>Close</Button>
          <Button
            variant="contained"
            startIcon={<SendIcon />}
            onClick={handleSend}
            disabled={status === "sending" || !body}
          >
            {status === "sending" ? "Sending..." : "Send"}
          </Button>
        </Box>
      </DialogContent>
    </Dialog>
  );
}
