import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  issueStatus: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  error: null,
};

export const getAllInternationalDrivingLicenses = createAsyncThunk(
  "InternationalDrivingLicense/getAllInternationalDrivingLicenses",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/InternationalLicenses",
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { InternationalDrivingLicense } = getState();
      if (
        InternationalDrivingLicense.status === "loading" ||
        InternationalDrivingLicense.list.length > 0
      ) {
        return false;
      }
      return true;
    },
  },
);

// ✅ إصدار International License جديد — الـ body كامل JSON object (مو query params
// متل replaceLicense)، حسب ما موضح بالـ Swagger
export const issueInternationalLicense = createAsyncThunk(
  "InternationalDrivingLicense/issueInternationalLicense",
  async (payload, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/InternationalLicenses",
        payload,
      );
      return response.data; // الـ object الكامل مع IDs الحقيقية بعد الإصدار
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Issue failed",
      );
    }
  },
);

const InternationalDrivingLicenseSlice = createSlice({
  name: "InternationalDrivingLicense",
  initialState,
  reducers: {
    addInternationalDrivingLicense: (state, action) => {
      state.list.push(action.payload);
    },
    resetIssueStatus: (state) => {
      state.issueStatus = "idle";
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(getAllInternationalDrivingLicenses.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(
        getAllInternationalDrivingLicenses.fulfilled,
        (state, action) => {
          state.status = "succeeded";
          state.list = action.payload;
        },
      )
      .addCase(getAllInternationalDrivingLicenses.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })

      .addCase(issueInternationalLicense.pending, (state) => {
        state.issueStatus = "loading";
        state.error = null;
      })
      .addCase(issueInternationalLicense.fulfilled, (state, action) => {
        state.issueStatus = "succeeded";
        state.list.push(action.payload);
      })
      .addCase(issueInternationalLicense.rejected, (state, action) => {
        state.issueStatus = "failed";
        state.error = action.payload;
      });
  },
});

export const { addInternationalDrivingLicense, resetIssueStatus } =
  InternationalDrivingLicenseSlice.actions;
export default InternationalDrivingLicenseSlice.reducer;
