import React from "react";
import AssignmentIcon from "@mui/icons-material/Assignment";
import BadgeIcon from "@mui/icons-material/Badge";
import PublicIcon from "@mui/icons-material/Public";
import EventIcon from "@mui/icons-material/Event";
import EventBusyIcon from "@mui/icons-material/EventBusy";
import PaidIcon from "@mui/icons-material/Paid";
import PersonIcon from "@mui/icons-material/Person";
import FlightIcon from "@mui/icons-material/Flight";

import InfoCard from "../InfoCard";
import Field from "../Field";

const formatDate = (isoDate) => {
  if (!isoDate) return "";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

export default function InternationalApplicationInfo({
  applicationID,
  internationalLicenseID,
  localLicenseID,
  applicationDate,
  issueDate,
  expirationDate,
  fees,
  createdByLabel,
}) {
  return (
    <InfoCard icon={FlightIcon} title="INTERNATIONAL LICENSE APPLICATION INFO">
      <Field
        icon={AssignmentIcon}
        label="I.L. Application ID"
        value={applicationID}
      />
      <Field
        icon={PublicIcon}
        label="I.L. License ID"
        value={internationalLicenseID}
      />
      <Field
        icon={EventIcon}
        label="Application Date"
        value={formatDate(applicationDate)}
      />
      <Field icon={BadgeIcon} label="Local License ID" value={localLicenseID} />
      <Field
        icon={EventIcon}
        label="Issue Date"
        value={formatDate(issueDate)}
      />
      <Field
        icon={EventBusyIcon}
        label="Expiration Date"
        value={formatDate(expirationDate)}
      />
      <Field icon={PaidIcon} label="Fees" value={fees} />
      <Field icon={PersonIcon} label="Created By" value={createdByLabel} />
    </InfoCard>
  );
}
