import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [], // هنا رح تنخزن قائمة الـ licenses
  currentLicense: null, // لتخزين بيانات الرخصة الحالية بعد جلبها بالـ ID
  driverLicenses: [], // نتيجة get license by driver ID (رخص سائق معيّن)
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  replaceStatus: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  driverStatus: "idle",
  addStatus: "idle",
  updateStatus: "idle",
  releaseStatus: "idle",
  renewStatus: "idle",
  error: null,
};

export const releaseDetainedLicense = createAsyncThunk(
  "licenses/releaseDetainedLicense",
  async ({ licenseId, releasedByUserId }, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        `https://idnan820-001-site1.ltempurl.com/api/Licenses/${licenseId}/release`,
        null,
        { params: { releasedByUserId } },
      );
      return response.data; // { applicationId: number }
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Release failed",
      );
    }
  },
);

export const getLicenses = createAsyncThunk(
  "licenses/getLicenses",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/Licenses",
    );
    return response.data; // array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { licenses } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (licenses.status === "loading" || licenses.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً، ورح تعتمد الكومبوننت على list الموجودة
      }
      return true;
    },
  },
);
export const replaceLicense = createAsyncThunk(
  "licenses/replaceLicense",
  async (
    { oldLicenseId, issueReason, createdByUserId },
    { rejectWithValue },
  ) => {
    try {
      const response = await axios.post(
        `https://idnan820-001-site1.ltempurl.com/api/Licenses/${oldLicenseId}/replace`,
        null,
        { params: { issueReason, createdByUserId } },
      );
      return response.data; // الرخصة الجديدة كاملة (فيها applicationID و licenseID الجديدين)
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Replace failed",
      );
    }
  },
);
export const getLicenseById = createAsyncThunk(
  "licenses/getLicenseById",
  async (licenseId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Licenses/${licenseId}`,
    );
    return response.data; // object مباشرة حسب الـ Swagger
  },
  {
    condition: (licenseId, { getState }) => {
      const { licenses } = getState();
      if (
        licenses.currentLicense !== null &&
        licenses.currentLicense.licenseID === licenseId
      ) {
        return false; // ✅ نفس الرخصة موجودة أصلاً، لا تكمل
      }
      return true;
    },
  },
);

export const getLicensesByDriverId = createAsyncThunk(
  "licenses/getLicensesByDriverId",
  async (driverId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Licenses/driver/${driverId}`,
    );
    return response.data; // array مباشرة حسب الـ Swagger
  },
  // ما حطيت condition هون لأن السائق ممكن يتغير من طلب لطلب،
  // فما رح نعتمد على "list فيها بيانات" كمقياس للإلغاء
);
export const renewLicense = createAsyncThunk(
  "licenses/renewLicense",
  async ({ licenseId, notes, createdByUserId }, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        `https://idnan820-001-site1.ltempurl.com/api/Licenses/${licenseId}/renew`,
        null,
        { params: { notes, createdByUserId } },
      );
      return response.data; // camelCase خام، فيه licenseID جديد مختلف عن القديم
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Renew failed",
      );
    }
  },
);

export const AddLicense = createAsyncThunk(
  "licenses/AddLicense",
  async (license, { dispatch, rejectWithValue }) => {
    const tempId = `temp-${Date.now()}-${Math.random()}`;
    dispatch(addLicenseToList({ ...license, _tempId: tempId }));

    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/Licenses",
        license,
      );
      return { data: response.data, tempId };
    } catch (err) {
      return rejectWithValue({
        message:
          err.response?.data?.message || err.response?.data || "Add failed",
        tempId,
      });
    }
  },
);

export const UpdateLicense = createAsyncThunk(
  "licenses/UpdateLicense",
  async (license, { dispatch, rejectWithValue }) => {
    dispatch(updateLicenseLocally(license)); // تحديث مؤقت عالـ list قبل استلام رد السيرفر

    try {
      const response = await axios.put(
        `https://idnan820-001-site1.ltempurl.com/api/Licenses/${license.licenseID}`,
        license,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Update failed",
      );
    }
  },
);

const normalizeLicense = (l) => ({
  license_id: l.licenseID,
  application_id: l.applicationID,
  driver_id: l.driverID,
  license_class: l.licenseClass,
  issue_date: l.issueDate,
  expiration_date: l.expirationDate,
  paid_fees: l.paidFees,
  is_active: l.isActive,
  issue_reason: l.issueReason,
  notes: l.notes,
  created_by_user_id: l.createdByUserID,
});

const licenseSlice = createSlice({
  name: "licenses",
  initialState,
  reducers: {
    addLicenseToList: (state, action) => {
      // action.payload لازم يكون object للرخصة المراد إضافتها
      state.list.push(action.payload);
    },
    updateLicenseLocally: (state, action) => {
      const index = state.list.findIndex(
        (l) => l.license_id === action.payload.licenseID,
      );
      if (index !== -1) {
        state.list[index] = {
          ...state.list[index],
          ...normalizeLicense(action.payload),
        };
      }
    },
    resetAddStatus: (state) => {
      state.addStatus = "idle";
    },
    resetUpdateStatus: (state) => {
      state.updateStatus = "idle";
    },
  },

  extraReducers: (builder) => {
    builder
      .addCase(getLicenses.pending, (state) => {
        state.status = "loading";
        console.log("Im licenses Not done yet");
        state.error = null;
      })
      .addCase(getLicenses.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im licenses done");
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getLicenses.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })

      .addCase(getLicenseById.pending, (state) => {
        state.status = "loading";
        console.log("Current License has been worked on");
        state.error = null;
      })
      .addCase(getLicenseById.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Current License has arrived");
        state.currentLicense = action.payload;

        // نحدث نفس الرخصة بالـ list إذا موجودة (بصيغة snake_case المطبّعة)، أو نضيفها إذا مش موجودة
        const normalized = normalizeLicense(action.payload);
        const index = state.list.findIndex(
          (l) => l.license_id === normalized.license_id,
        );
        if (index !== -1) {
          state.list[index] = { ...state.list[index], ...normalized };
        } else {
          state.list.push(normalized);
        }
      })
      .addCase(getLicenseById.rejected, (state, action) => {
        state.status = "failed";
        console.log("Current License has Not arrived");
        state.error = action.error.message;
      })

      .addCase(getLicensesByDriverId.pending, (state) => {
        state.driverStatus = "loading";
        console.log("Driver Licenses Not done yet");
        state.error = null;
      })
      .addCase(getLicensesByDriverId.fulfilled, (state, action) => {
        state.driverStatus = "succeeded";
        console.log("Driver Licenses done");
        state.driverLicenses = action.payload;
      })
      .addCase(getLicensesByDriverId.rejected, (state, action) => {
        state.driverStatus = "failed";
        state.error = action.error.message;
      })

      .addCase(AddLicense.pending, (state) => {
        state.addStatus = "loading";
        state.error = null;
      })
      .addCase(AddLicense.fulfilled, (state, action) => {
        state.addStatus = "succeeded";
        console.log("AddLicense succeeded");

        // نستبدل الصف المؤقت (المعلّم بـ _tempId) بالرد الحقيقي المطبّع من السيرفر
        const { data, tempId } = action.payload;
        const normalized = normalizeLicense(data);
        const pendingIndex = state.list.findIndex((l) => l._tempId === tempId);
        if (pendingIndex !== -1) {
          state.list[pendingIndex] = normalized;
        } else {
          state.list.push(normalized);
        }
      })
      .addCase(AddLicense.rejected, (state, action) => {
        state.addStatus = "failed";
        console.log("AddLicense has not succeeded");
        const { message, tempId } = action.payload || {};
        state.error = message;

        // نرجع نشيل الصف اللي ضفناه optimistically (بالـ _tempId) بما إنه فشل
        const pendingIndex = state.list.findIndex((l) => l._tempId === tempId);
        if (pendingIndex !== -1) {
          state.list.splice(pendingIndex, 1);
        }
      })

      .addCase(UpdateLicense.pending, (state) => {
        state.updateStatus = "loading";
        state.error = null;
      })
      .addCase(UpdateLicense.fulfilled, (state, action) => {
        state.updateStatus = "succeeded";
        console.log("UpdateLicense succeeded");

        // نأكد إن الـ list فيها آخر نسخة حقيقية مطبّعة جاية من السيرفر (مش بس النسخة المؤقتة)
        const normalized = normalizeLicense(action.payload);
        const index = state.list.findIndex(
          (l) => l.license_id === normalized.license_id,
        );
        if (index !== -1) {
          state.list[index] = { ...state.list[index], ...normalized };
        }
      })
      .addCase(UpdateLicense.rejected, (state, action) => {
        state.updateStatus = "failed";
        console.log("UpdateLicense has not succeeded");
        state.error = action.payload;
      })
      .addCase(replaceLicense.pending, (state) => {
        state.replaceStatus = "loading";
        state.error = null;
      })
      .addCase(replaceLicense.fulfilled, (state, action) => {
        state.replaceStatus = "succeeded";

        // إضافة/تحديث الرخصة الجديدة بالـ list
        const normalized = normalizeLicense(action.payload);
        const newIndex = state.list.findIndex(
          (l) => l.license_id === normalized.license_id,
        );
        if (newIndex !== -1) {
          state.list[newIndex] = { ...state.list[newIndex], ...normalized };
        } else {
          state.list.push(normalized);
        }

        // تعطيل الرخصة القديمة محلياً (نفس نمط incrementPassedTestCount سابقاً)
        const { oldLicenseId } = action.meta.arg;
        const oldIndex = state.list.findIndex(
          (l) => l.license_id === oldLicenseId,
        );
        if (oldIndex !== -1) {
          state.list[oldIndex] = { ...state.list[oldIndex], is_active: false };
        }
      })
      .addCase(replaceLicense.rejected, (state, action) => {
        state.replaceStatus = "failed";
        state.error = action.payload;
      })
      .addCase(renewLicense.pending, (state) => {
        state.renewStatus = "loading";
        state.error = null;
      })
      .addCase(renewLicense.fulfilled, (state, action) => {
        state.renewStatus = "succeeded";

        const normalized = normalizeLicense(action.payload);
        const newIndex = state.list.findIndex(
          (l) => l.license_id === normalized.license_id,
        );
        if (newIndex !== -1) {
          state.list[newIndex] = { ...state.list[newIndex], ...normalized };
        } else {
          state.list.push(normalized);
        }

        // تعطيل الرخصة القديمة محلياً (نفس نمط replaceLicense)
        const { licenseId } = action.meta.arg;
        const oldIndex = state.list.findIndex(
          (l) => l.license_id === licenseId,
        );
        if (oldIndex !== -1) {
          state.list[oldIndex] = { ...state.list[oldIndex], is_active: false };
        }
      })
      .addCase(renewLicense.rejected, (state, action) => {
        state.renewStatus = "failed";
        state.error = action.payload;
      })
      .addCase(releaseDetainedLicense.pending, (state) => {
        state.releaseStatus = "loading";
        state.error = null;
      })
      .addCase(releaseDetainedLicense.fulfilled, (state) => {
        state.releaseStatus = "succeeded";
      })
      .addCase(releaseDetainedLicense.rejected, (state, action) => {
        state.releaseStatus = "failed";
        state.error = action.payload;
      });
  },
});

export const selectLicenseById = (state, licenseId) =>
  state.licenses.list.find((l) => l.license_id === licenseId);

export const {
  addLicenseToList,
  updateLicenseLocally,
  resetAddStatus,
  resetUpdateStatus,
} = licenseSlice.actions;

export default licenseSlice.reducer;
