import React, { useState } from "react";
import Dialog from "@mui/material/Dialog";
import DialogTitle from "@mui/material/DialogTitle";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import TextField from "@mui/material/TextField";
import Button from "@mui/material/Button";
import { useSelector, useDispatch } from "react-redux";

import ShowApplicationInfo from "../Application/Showapplicationinfo";
import { updateApplicationStatus } from "../../Store/features/Application/ApplicationSlice";
import { setApplicationStatusLocally } from "../../Store/features/LocalDrivingLicense/LocalDrivingLicenseSlice";
import { AddLicense } from "../../Store/features/Licenses/LicensesSlice";
import { AddDriverAsync } from "../../Store/features/Drivers/DriverSlice";

/**
 * IssueDrivingLicense
 * Shared component — لإصدار الرخصة لأول مرة (issueReason: 1).
 * يستقبل localApplicationId + open + onClose فقط.
 *
 * تسلسل الحفظ عند الضغط على Issue:
 * 1) إنشاء Driver جديد (personID + createdByUserID) — خاص بأول إصدار فقط
 * 2) إصدار الرخصة باستخدام driverID الحقيقي القادم من رد إنشاء الـ Driver
 * 3) تحديث application_status إلى 3 (Completed) على السيرفر
 * 4) تحديث محلي فوري لـ application_status بشاشة الإدارة الرئيسية
 */
const IssueDrivingLicense = ({ localApplicationId, open, onClose }) => {
  const dispatch = useDispatch();

  const currentUserID = useSelector(
    (state) => state.users?.currentUser?.userID,
  );

  const selectedInfo = useSelector(
    (state) => state.LocalDrivingLicense.selectedInfo,
  );

  const application = useSelector((state) =>
    state.applications.list.find(
      (a) => a.applicationID === selectedInfo?.applicationID,
    ),
  );

  const licenseClass = useSelector((state) =>
    state.LicenseClass.list.find(
      (c) => c.licenseClassID === selectedInfo?.licenseClassID,
    ),
  );

  const [notes, setNotes] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");

  const handleClose = () => {
    setNotes("");
    setError("");
    onClose();
  };

  const handleIssue = async () => {
    if (!application || !selectedInfo) return;

    setIsSaving(true);
    setError("");

    const issueDate = new Date();
    const validityYears = licenseClass?.default_validity_length ?? 1;
    const expirationDate = new Date(issueDate);
    expirationDate.setFullYear(issueDate.getFullYear() + validityYears);

    try {
      // 1) إنشاء Driver جديد أول (خاص بأول إصدار فقط)
      const newDriver = await dispatch(
        AddDriverAsync({
          personID: selectedInfo.applicantPersonID,
          createdByUserID: currentUserID,
        }),
      ).unwrap();

      // 2) إصدار الرخصة بالـ driverID الحقيقي القادم من السيرفر
      await dispatch(
        AddLicense({
          applicationID: selectedInfo.applicationID,
          driverID: newDriver.driverID,
          licenseClass: selectedInfo.licenseClassID,
          issueDate: issueDate.toISOString(),
          expirationDate: expirationDate.toISOString(),
          notes,
          paidFees: licenseClass?.class_fees ?? 0,
          isActive: true,
          issueReason: 1,
          createdByUserID: currentUserID,
        }),
      ).unwrap();

      // 3) تحديث application_status إلى 3 (Completed) بالسيرفر
      await dispatch(
        updateApplicationStatus({
          ...application,
          applicationStatus: 3,
          lastStatusDate: new Date().toISOString(),
        }),
      ).unwrap();

      // 4) تحديث محلي فوري لشاشة الإدارة الرئيسية
      dispatch(
        setApplicationStatusLocally({
          localDrivingLicenseApplicationID: localApplicationId,
          statusText: "Completed",
        }),
      );

      setIsSaving(false);
      setNotes("");
      onClose();
    } catch (err) {
      setIsSaving(false);
      setError("Failed to issue the license. Please try again.");
    }
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          p: 1,
        }}
      >
        <DialogTitle sx={{ p: 1 }}>
          Issue Driver License For The First Time
        </DialogTitle>
        <IconButton onClick={handleClose} size="small" disabled={isSaving}>
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>

      <DialogContent sx={{ pt: 0 }}>
        <ShowApplicationInfo localApplicationId={localApplicationId} />

        <Typography sx={{ fontWeight: 600, mt: 2, mb: 1 }}>Notes:</Typography>
        <TextField
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          multiline
          rows={4}
          fullWidth
          disabled={isSaving}
        />

        {error && (
          <Typography color="error" sx={{ mt: 1 }}>
            {error}
          </Typography>
        )}
      </DialogContent>

      <DialogActions sx={{ justifyContent: "flex-end", gap: 2, p: 2 }}>
        <Button variant="outlined" onClick={handleClose} disabled={isSaving}>
          Close
        </Button>
        <Button variant="contained" onClick={handleIssue} disabled={isSaving}>
          {isSaving ? "Issuing..." : "Issue"}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default IssueDrivingLicense;
