import React from "react";
import { CssBaseline, ThemeProvider, createTheme } from "@mui/material";
import { HashRouter, Routes, Route, Navigate } from "react-router-dom";
import Login from "./Login/LoginPage";
import MainScreen from "./MainScreen/MainScreen";
import Banner from "./MainScreen/Banner";
import ProtectedRoute from "./ProtectedRoute";
import ManagePeopleScreen from "./Screens/ManagePeopleScreen";
import ManageAllAppointments from "./Screens/ManageAllAppointments";
import ManageUsersScreen from "./Screens/ManageUsersScreen";
import ManageDriverScreen from "./Screens/ManageDriverScreen";
import ManageDetainedLicensesScreen from "./Screens/ManageDetainedLicensesScreen";
import ManageInternationalLicenseApplicationsScreen from "./Screens/ManageInternationalLicenseApplicationsScreen";
import ManageLocalDrivingLicenseApplicationsScreen from "./Screens/ManageLocalDrivingLicenseApplicationsScreen";
import MangeAllLicenses from "./Screens/MangeAllLicenses";

import "./styles/MainStyle.css";

const darkTheme = createTheme({
  palette: {
    mode: "dark",
    background: { default: "#0b0c10", paper: "#1f2833" },
    primary: { main: "#66fcf1" },
    text: { primary: "#ffffff", secondary: "#c5c6c7" },
  },
  typography: { fontFamily: "Roboto, Arial, sans-serif" },
});

function App() {
  return (
    <HashRouter>
      <ThemeProvider theme={darkTheme}>
        <CssBaseline />

        <Routes>
          <Route path="/" element={<Login />} />

          <Route element={<MainScreen />}>
            <Route path="/Home" element={<Banner />} />
            <Route
              path="/manage-AllAppointments"
              element={<ManageAllAppointments />}
            />
            <Route path="/manage-Licenses" element={<MangeAllLicenses />} />
            <Route path="/manage-people" element={<ManagePeopleScreen />} />
            <Route
              path="/manage-DetainedLicensesS"
              element={<ManageDetainedLicensesScreen />}
            />
            <Route path="/manage-users" element={<ManageUsersScreen />} />
            <Route
              path="/manage-International"
              element={<ManageInternationalLicenseApplicationsScreen />}
            />
            <Route
              path="/manage-Local"
              element={<ManageLocalDrivingLicenseApplicationsScreen />}
            />
            <Route path="/manage-drivers" element={<ManageDriverScreen />} />
          </Route>
        </Routes>
      </ThemeProvider>
    </HashRouter>
  );
}

export default App;
