import { configureStore } from "@reduxjs/toolkit";
import peopleReducer from "./features/people/peopleSlice";
import UsersReducer from "./features/Users/userSlice";
import DriverReducer from "./features/Drivers/DriverSlice";
import ApplicationTypeReducer from "./features/ApplicationType/ApplicationTypeSlice";
import TestTypesReducer from "./features/TestType/TestTypesSlice";
import DetainedLicensesReducer from "./features/DetainedLicenses/DetainedLicensesSlice";
import LocalDrivingLicenseReducer from "./features/LocalDrivingLicense/LocalDrivingLicenseSlice";
import InternationalDrivingLicenseReducer from "./features/InternationalDrivingLicense/InternationalDrivingLicenseSlice";
import CountryReducer from "./features/Country/countrySlice";
import LicenseClassReducer from "./features/licenseClass/licenseClassSlice";
import applicationsReducer from "./features/Application/ApplicationSlice";
import testappointmentReducer from "./features/TestAppointments/TestAppointmentsSlice";
import testReducer from "./features/tests/testsSlice";
import LicenseReducer from "./features/Licenses/LicensesSlice";
import { loadSession } from "../utils/session";

const reducers = {
  people: peopleReducer,
  users: UsersReducer,
  driver: DriverReducer,
  ApplicationType: ApplicationTypeReducer,
  applications: applicationsReducer,
  TestTypes: TestTypesReducer,
  DetainedLicenses: DetainedLicensesReducer,
  LocalDrivingLicense: LocalDrivingLicenseReducer,
  InternationalDrivingLicense: InternationalDrivingLicenseReducer,
  Country: CountryReducer,
  LicenseClass: LicenseClassReducer,
  testAppointments: testappointmentReducer,
  tests: testReducer,
  licenses: LicenseReducer,
};

// ✅ نبني preloadedState فقط لو فيه جلسة محفوظة، بدون أي افتراض لشكل باقي
// الحقول جوا كل slice — نستدعي الـ reducer نفسه بـ action وهمي ليرجّع
// initialState الحقيقي، وبعدين نتفوّق فقط على currentUser/currentPerson
const session = loadSession();

const preloadedState = session
  ? {
      users: {
        ...UsersReducer(undefined, { type: "@@INIT" }),
        currentUser: session.user,
        status: "succeeded",
      },
      people: {
        ...peopleReducer(undefined, { type: "@@INIT" }),
        currentPerson: session.person,
        status: "succeeded",
      },
    }
  : undefined;

const store = configureStore({
  reducer: reducers,
  preloadedState,
});

export default store;
