import React, { useState } from "react";
import { Dialog, DialogContent, Box, Button } from "@mui/material";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import EmailIcon from "@mui/icons-material/Email";
import SmsIcon from "@mui/icons-material/Sms";
import { useSelector } from "react-redux";

import PersonInfoPanel from "../Shared/Person/PersonInfoPanel";
import SendEmailDialog from "../Shared/Sends/SendEmailDialog";
import SendSmsDialog from "../Shared/Sends/SendSmsDialog";
import { selectPersonById } from "../Store/features/people/peopleSlice";

// تظهر عند: ManagePeopleScreen → double-click على صف بالجدول
// personId: يُمرَّر فقط، البيانات تُقرأ من Redux (نفس نمط UserDetailsModal)
// onUpdate(personId), onDelete(personId): يُمرَّران فقط الـID، المنطق يُبنى بالأب
export default function PersonDetailsModal({
  open,
  onClose,
  personId,
  onUpdate,
  onDelete,
}) {
  const person = useSelector((state) => selectPersonById(state, personId));

  // state خاص بفتح/إغلاق نوافذ الإرسال — منفصل عن حالة الـ modal الرئيسي
  const [emailOpen, setEmailOpen] = useState(false);
  const [smsOpen, setSmsOpen] = useState(false);

  const fullName =
    `${person?.first_name || ""} ${person?.last_name || ""}`.trim();

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="lg"
      className="modal-dialog"
    >
      <DialogContent
        className="modal-content"
        sx={{ px: { xs: 3, md: 6 }, py: 4 }}
      >
        <PersonInfoPanel personId={personId} />

        <Box
          className="modal-actions"
          sx={{
            display: "flex",
            justifyContent: "center",
            gap: 2,
            mt: 3,
            flexWrap: "wrap",
          }}
        >
          <Button
            className="modal-btn-save"
            startIcon={<EditIcon />}
            onClick={() => onUpdate && onUpdate(personId)}
          >
            Update
          </Button>
          <Button
            className="modal-btn-cancel"
            startIcon={<DeleteIcon />}
            sx={{ color: "var(--color-danger-alt) !important" }}
            onClick={() => onDelete && onDelete(personId)}
          >
            Delete
          </Button>
          <Button
            className="modal-btn-cancel"
            startIcon={<EmailIcon />}
            onClick={() => setEmailOpen(true)}
          >
            Send Email
          </Button>
          <Button
            className="modal-btn-cancel"
            startIcon={<SmsIcon />}
            onClick={() => setSmsOpen(true)}
          >
            Send SMS
          </Button>
        </Box>
      </DialogContent>

      <SendEmailDialog
        open={emailOpen}
        onClose={() => setEmailOpen(false)}
        recipientName={fullName}
        recipientEmail={person?.email}
      />
      <SendSmsDialog
        open={smsOpen}
        onClose={() => setSmsOpen(false)}
        recipientName={fullName}
        recipientPhone={person?.phone}
      />
    </Dialog>
  );
}
