import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import PublishIcon from "@mui/icons-material/Publish";

import LicenseFilter from "../License/LicenseFilter";
import { LicenseInfoContent } from "../License/Showlicenseinfo";
import InternationalApplicationInfo from "./InternationalApplicationInfo";
import { getLicenses } from "../../Store/features/Licenses/LicensesSlice";
import { getApplicationTypes } from "../../Store/features/ApplicationType/ApplicationTypeSlice";
import { issueInternationalLicense } from "../../Store/features/InternationalDrivingLicense/InternationalDrivingLicenseSlice"; // ⚠️ عدّل المسار حسب مكان الملف الفعلي عندك

const INTERNATIONAL_APPLICATION_TYPE_ID = 6;
const FALLBACK_FEES = 300;

export default function IssueInternationalLicenseModal({ open, onClose }) {
  const dispatch = useDispatch();

  const [filterInput, setFilterInput] = useState("");
  const [committedLicenseId, setCommittedLicenseId] = useState(null);
  const [searchError, setSearchError] = useState(null);
  const [issuedResult, setIssuedResult] = useState(null);

  const currentUser = useSelector((state) => state.users.currentUser);
  const licensesList = useSelector((state) => state.licenses.list);
  const applicationTypes = useSelector((state) => state.ApplicationType.list);
  const applications = useSelector((state) => state.applications.list);
  const issueStatus = useSelector(
    (state) => state.InternationalDrivingLicense.issueStatus, // ⚠️ عدّل اسم الـ slice لو مختلف
  );
  const issueError = useSelector(
    (state) => state.InternationalDrivingLicense.error,
  );
  const selectedLicenseForIssue = licensesList.find(
    (l) => l.license_id === committedLicenseId,
  );
  const selectedApplication = applications.find(
    (a) => a.applicationID === selectedLicenseForIssue?.application_id,
  );
  const applicantPersonId = selectedApplication?.applicantPersonID ?? null;

  const isLoading = issueStatus === "loading";
  const alreadyIssued = Boolean(issuedResult);
  const canIssue = Boolean(committedLicenseId) && !isLoading && !alreadyIssued;

  const fees =
    applicationTypes.find(
      (t) => t.application_type_id === INTERNATIONAL_APPLICATION_TYPE_ID,
    )?.application_fees ?? FALLBACK_FEES;

  useEffect(() => {
    if (!open) return;
    dispatch(getLicenses());
    dispatch(getApplicationTypes());
  }, [open, dispatch]);

  const resetAll = () => {
    setFilterInput("");
    setCommittedLicenseId(null);
    setSearchError(null);
    setIssuedResult(null);
  };

  const handleClose = () => {
    resetAll();
    onClose();
  };

  const handleSearch = () => {
    const idNum = Number(filterInput);
    if (!idNum) {
      setSearchError("الرجاء إدخال رقم رخصة صحيح");
      setCommittedLicenseId(null);
      return;
    }

    const foundLicense = licensesList.find((l) => l.license_id === idNum);

    if (!foundLicense) {
      setSearchError("لا توجد رخصة بهذا الرقم");
      setCommittedLicenseId(null);
      return;
    }

    if (!foundLicense.is_active) {
      setSearchError(
        "هذه الرخصة غير مفعّلة (Inactive) — الرجاء اختيار رخصة Active فقط",
      );
      setCommittedLicenseId(null);
      return;
    }

    setSearchError(null);
    setCommittedLicenseId(idNum);
    setIssuedResult(null);
  };

  const handleIssue = async () => {
    if (!committedLicenseId) return;

    const license = licensesList.find(
      (l) => l.license_id === committedLicenseId,
    );

    const now = new Date();
    const oneYearLater = new Date(now);
    oneYearLater.setFullYear(oneYearLater.getFullYear() + 1);
    const nowISO = now.toISOString();
    const expirationISO = oneYearLater.toISOString();

    const payload = {
      applicationID: 0,
      applicantPersonID: applicantPersonId,
      applicationDate: nowISO,
      applicationTypeID: INTERNATIONAL_APPLICATION_TYPE_ID,
      applicationStatus: 1,
      lastStatusDate: nowISO,
      paidFees: fees,
      createdByUserID: currentUser?.userID,
      internationalLicenseID: 0,
      driverID: license?.driver_id,
      issuedUsingLocalLicenseID: committedLicenseId,
      issueDate: nowISO,
      expirationDate: expirationISO,
      isActive: true,
    };

    try {
      const result = await dispatch(
        issueInternationalLicense(payload),
      ).unwrap();
      setIssuedResult(result);
    } catch (err) {
      console.error("Issue international license failed:", err);
    }
  };

  useEffect(() => {
    if (issueStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [issueStatus]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          International License Application
        </Typography>

        <LicenseFilter
          value={filterInput}
          onChange={(e) => setFilterInput(e.target.value)}
          onSearch={handleSearch}
          error={searchError}
        />

        {committedLicenseId ? (
          <Box className="replace-license-license-info">
            <LicenseInfoContent licenseId={committedLicenseId} />
          </Box>
        ) : (
          <Typography className="replace-license-placeholder">
            ابحث برقم الرخصة أولاً
          </Typography>
        )}

        {committedLicenseId && (
          <InternationalApplicationInfo
            applicationID={issuedResult?.applicationID}
            internationalLicenseID={issuedResult?.internationalLicenseID}
            localLicenseID={committedLicenseId}
            applicationDate={issuedResult?.applicationDate}
            issueDate={issuedResult?.issueDate}
            expirationDate={issuedResult?.expirationDate}
            fees={fees}
            createdByLabel={currentUser?.user_name ?? currentUser?.userID}
          />
        )}

        {issueStatus === "succeeded" && (
          <Alert severity="success" variant="filled" sx={{ mt: 2 }}>
            International license issued successfully ✅
          </Alert>
        )}

        {issueStatus === "failed" && issueError && (
          <Alert severity="error" variant="filled" sx={{ mt: 2 }}>
            {typeof issueError === "string"
              ? issueError
              : "فشل إصدار الرخصة الدولية"}
          </Alert>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button
          variant="contained"
          color="error"
          startIcon={<CloseIcon />}
          onClick={handleClose}
          className="modal-btn-cancel"
        >
          Close
        </Button>
        <Button
          variant="contained"
          startIcon={
            isLoading ? (
              <CircularProgress size={16} color="inherit" />
            ) : (
              <PublishIcon />
            )
          }
          onClick={handleIssue}
          disabled={!canIssue}
          className="modal-btn-save"
        >
          Issue
        </Button>
      </DialogActions>
    </Dialog>
  );
}
