// src/Shared/RetakeTest.js
import React from "react";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import Paper from "@mui/material/Paper";

const RETAKE_APPLICATION_TYPE_ID = 8;

const RetakeTest = ({ retakeFees, testFees }) => {
  const totalFees = (testFees ?? 0) + (retakeFees ?? 0);

  return (
    <Paper
      variant="outlined"
      sx={{
        p: 2,
        mb: 2,
        borderColor: "warning.main",
        bgcolor: "warning.50",
      }}
    >
      <Typography sx={{ fontWeight: "bold", mb: 1 }} color="warning.dark">
        Retake Test
      </Typography>
      <Box sx={{ display: "flex", gap: 2, flexWrap: "wrap" }}>
        <TextField
          label="Retake Fees"
          value={retakeFees ?? 0}
          InputProps={{ readOnly: true }}
          size="small"
        />
        <TextField
          label="Total Fees"
          value={totalFees}
          InputProps={{ readOnly: true }}
          size="small"
        />
      </Box>
    </Paper>
  );
};

export default RetakeTest;
export { RETAKE_APPLICATION_TYPE_ID };
