import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle",
  addStatus: "idle",
  selectedInfoStatus: "idle",
  deleteStatus: "idle",
  lastRequestedId: null,
  error: null,
  selectedInfo: null,
};

export const getAllLocalDrivingLicenses = createAsyncThunk(
  "LocalDrivingLicense/getAllLocalDrivingLicenses",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/LocalDrivingLicenseApplications",
    );
    return response.data;
  },
  {
    condition: (_, { getState }) => {
      const { LocalDrivingLicense } = getState();
      if (
        LocalDrivingLicense.status === "loading" ||
        LocalDrivingLicense.list.length > 0
      ) {
        return false;
      }
      return true;
    },
  },
);

export const addLocalDrivingLicenseAsync = createAsyncThunk(
  "LocalDrivingLicense/addLocalDrivingLicenseAsync",
  async (application, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        "https://idnan820-001-site1.ltempurl.com/api/LocalDrivingLicenseApplications",
        application,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || "Add application failed",
      );
    }
  },
);

export const getLocalDrivingLicenseByApplicationId = createAsyncThunk(
  "LocalDrivingLicense/getLocalDrivingLicenseByApplicationId",
  async (applicationId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/LocalDrivingLicenseApplications/by-application/${applicationId}`,
    );
    return response.data;
  },
  {
    condition: (applicationId, { getState }) => {
      const { LocalDrivingLicense } = getState();

      if (LocalDrivingLicense.list && LocalDrivingLicense.list.length > 0) {
        const existingLicense = LocalDrivingLicense.list.find(
          (license) => license.applicationID === applicationId,
        );

        if (existingLicense) {
          return false;
        }
      }
      return true;
    },
  },
);

export const getLocalDrivingLicenseById = createAsyncThunk(
  "LocalDrivingLicense/getLocalDrivingLicenseById",
  async (Id) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/LocalDrivingLicenseApplications/${Id}`,
    );
    return response.data;
  },
  {
    condition: (Id, { getState }) => {
      const { LocalDrivingLicense } = getState();

      if (
        LocalDrivingLicense.selectedInfoStatus === "loading" &&
        LocalDrivingLicense.lastRequestedId === Id
      ) {
        return false;
      }

      if (
        LocalDrivingLicense.selectedInfo &&
        LocalDrivingLicense.selectedInfo.localDrivingLicenseApplicationID === Id
      ) {
        return false;
      }

      return true;
    },
  },
);

export const deleteLocalDrivingLicenseApplication = createAsyncThunk(
  "LocalDrivingLicense/deleteLocalDrivingLicenseApplication",
  async (Id) => {
    await axios.delete(
      `https://idnan820-001-site1.ltempurl.com/api/LocalDrivingLicenseApplications/${Id}`,
    );
  },
);

const LocalDrivingLicenseSlice = createSlice({
  name: "LocalDrivingLicense",
  initialState,
  reducers: {
    addLocalDrivingLicense: (state, action) => {
      state.list.push(action.payload);
    },
    resetAddStatus: (state) => {
      state.addStatus = "idle";
    },
    // ✅ جديد: تحديث محلي فوري لـ passed_test_count بعد إضافة Test بنتيجة Pass
    // (بدون هذا، الرقم بيضل قديم لحد ما تعمل refresh، لأن الـ view/count
    // بيتحسب بالباك اند وقت الـ fetch الأول فقط، ومافي ربط تلقائي مع tests slice)
    incrementPassedTestCount: (state, action) => {
      const row = state.list.find(
        (l) => l.local_driving_license_application_id === action.payload,
      );
      if (row) {
        row.passed_test_count = (row.passed_test_count ?? 0) + 1;
      }
    },
    setApplicationStatusLocally: (state, action) => {
      const { localDrivingLicenseApplicationID, statusText } = action.payload;
      const row = state.list.find(
        (l) =>
          l.local_driving_license_application_id ===
          localDrivingLicenseApplicationID,
      );
      if (row) {
        row.application_status = statusText;
      }
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(getAllLocalDrivingLicenses.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getAllLocalDrivingLicenses.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im LocalDrivingLicense and im coming ");
        state.list = action.payload;
      })
      .addCase(getAllLocalDrivingLicenses.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(addLocalDrivingLicenseAsync.pending, (state) => {
        state.addStatus = "loading";
        state.error = null;
      })
      .addCase(addLocalDrivingLicenseAsync.fulfilled, (state, action) => {
        state.addStatus = "succeeded";
        // ⚠️ رد POST بيرجع كلاس LocalDrivingLicenseApplication الخام (camelCase)
        // بينما getAllLocalDrivingLicenses() view بيرجع snake_case + حقول join
        // (class_name, full_name, application_status) مش موجودة بالكلاس الخام.
        // نطبّع الحقول المتوفرة، والباقي بيضل فاضي لحد ما ينعمل refetch حقيقي.
        const p = action.payload;
        const normalized = {
          local_driving_license_application_id:
            p.localDrivingLicenseApplicationID,
          application_id: p.applicationID,
          license_class_id: p.licenseClassID,
          passed_test_count: p.passedTestCount ?? 0,
          class_name: null,
          full_name: null,
          application_status: "New",
        };
        state.list.push(normalized);
      })
      .addCase(addLocalDrivingLicenseAsync.rejected, (state, action) => {
        state.addStatus = "failed";
        state.error = action.payload;
      })
      .addCase(getLocalDrivingLicenseByApplicationId.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(
        getLocalDrivingLicenseByApplicationId.fulfilled,
        (state, action) => {
          state.status = "succeeded";
          state.selectedInfo = action.payload;
        },
      )
      .addCase(
        getLocalDrivingLicenseByApplicationId.rejected,
        (state, action) => {
          state.status = "failed";
          state.error = action.payload;
          console.error(
            "Error fetching local driving license:",
            action.payload,
          );
        },
      )
      .addCase(getLocalDrivingLicenseById.pending, (state, action) => {
        state.selectedInfoStatus = "loading";
        state.lastRequestedId = action.meta.arg;
        state.error = null;
      })
      .addCase(getLocalDrivingLicenseById.fulfilled, (state, action) => {
        state.selectedInfoStatus = "succeeded";
        state.selectedInfo = action.payload;
      })
      .addCase(getLocalDrivingLicenseById.rejected, (state, action) => {
        state.selectedInfoStatus = "failed";
        state.error = action.error.message;
      })
      .addCase(deleteLocalDrivingLicenseApplication.pending, (state) => {
        state.deleteStatus = "loading";
        state.error = null;
      })
      .addCase(deleteLocalDrivingLicenseApplication.fulfilled, (state) => {
        state.deleteStatus = "succeeded";
        state.error = null;
      })
      .addCase(
        deleteLocalDrivingLicenseApplication.rejected,
        (state, action) => {
          state.deleteStatus = "failed";
          state.error = action.error.message;
        },
      );
  },
});

export const {
  addLocalDrivingLicense,
  resetAddStatus,
  incrementPassedTestCount,
  setApplicationStatusLocally,
} = LocalDrivingLicenseSlice.actions;
export default LocalDrivingLicenseSlice.reducer;
