import React, { useState, useEffect } from "react";
import Dialog from "@mui/material/Dialog";
import DialogTitle from "@mui/material/DialogTitle";
import DialogContent from "@mui/material/DialogContent";
import DialogActions from "@mui/material/DialogActions";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import Button from "@mui/material/Button";
import Typography from "@mui/material/Typography";
import Paper from "@mui/material/Paper";
import { useSelector, useDispatch } from "react-redux";
import {
  AddTestAppointment,
  getTestAppointmentsByLocalDrivingLicenseApplicationID,
  selectTestAppointmentsByLocalDrivingLicenseApplicationID,
} from "../Store/features/TestAppointments/TestAppointmentsSlice";
import { getTestTypes } from "../Store/features/TestType/TestTypesSlice";
import { getApplicationTypes } from "../Store/features/ApplicationType/ApplicationTypeSlice";
import { addApplication } from "../Store/features/Application/ApplicationSlice";
import { validateAppointmentDate } from "../validations/validation";
import { TEST_SECTIONS } from "../constants/testSections";
import RetakeTest, {
  RETAKE_APPLICATION_TYPE_ID,
} from "../Shared/Tests/RetakeTest";
import getPersonById from "../Store/features/people/peopleSlice";

const AddTest = ({
  localDrivingLicenseApplicationID,
  open,
  onClose,
  PersonId,
}) => {
  const dispatch = useDispatch();

  const applicationRow = useSelector((state) =>
    state.LocalDrivingLicense.list.find(
      (l) =>
        l.local_driving_license_application_id ===
        localDrivingLicenseApplicationID,
    ),
  );

  // const PersonID = useSelector((state) => state.people.SelectedPerson);
  const testTypesList = useSelector((state) => state.TestTypes.list);
  const applicationTypesList = useSelector(
    (state) => state.ApplicationType.list,
  );
  const priorAppointmentsForActiveType = useSelector(
    selectTestAppointmentsByLocalDrivingLicenseApplicationID,
  );
  // console.log(PersonID);
  const currentUserID = useSelector((state) => state.users.currentUser?.userID);
  console.log(currentUserID);
  const testCount = applicationRow?.passed_test_count ?? 0;
  const activeSectionIndex = testCount < TEST_SECTIONS.length ? testCount : -1;
  const activeSection = TEST_SECTIONS[activeSectionIndex];

  const [date, setDate] = useState("");
  const [dateError, setDateError] = useState("");
  const [isSaving, setIsSaving] = useState(false);

  const todayStr = new Date().toISOString().split("T")[0];

  useEffect(() => {
    if (open) {
      dispatch(getTestTypes());
      dispatch(getApplicationTypes());
      // dispatch(getPersonById(PersonId));
    }
  }, [open, dispatch]);

  // نشيك فقط على القسم النشط الحالي: هل يوجد موعد سابق لنفس النوع؟
  useEffect(() => {
    if (open && activeSection) {
      dispatch(
        getTestAppointmentsByLocalDrivingLicenseApplicationID({
          localDrivingLicenseApplicationID,
          testType: activeSection.testTypeId,
        }),
      );
    }
  }, [open, activeSection, localDrivingLicenseApplicationID, dispatch]);

  // إن وُجد أي موعد سابق مسجّل لهذا النوع تحديداً => هذا القسم retake
  const isRetake =
    activeSection &&
    Array.isArray(priorAppointmentsForActiveType) &&
    priorAppointmentsForActiveType.length > 0;

  const retakeApplicationType = applicationTypesList?.find(
    (a) => a.application_type_id === RETAKE_APPLICATION_TYPE_ID,
  );
  const retakeFees = retakeApplicationType?.application_fees ?? 0;

  const handleCancel = () => {
    setDate("");
    setDateError("");
    onClose();
  };

  const handleSave = async () => {
    if (!activeSection) return;

    const error = validateAppointmentDate(date);
    if (error) {
      setDateError(error);
      return;
    }
    setDateError("");

    const testTypeInfo = testTypesList?.find(
      (t) => t.test_type_id === activeSection.testTypeId,
    );

    setIsSaving(true);
    try {
      let retakeTestApplicationID = null;

      if (isRetake) {
        console.log("1");
        const nowISO = new Date().toISOString();
        console.log("11");

        console.log("1", PersonId);
        console.log(RETAKE_APPLICATION_TYPE_ID);
        const retakeApp = await dispatch(
          addApplication({
            applicantPersonID: PersonId,
            applicationDate: nowISO,
            applicationTypeID: RETAKE_APPLICATION_TYPE_ID,
            applicationStatus: 1,
            lastStatusDate: nowISO,
            paidFees: retakeFees,
          }),
        ).unwrap();
        console.log(retakeApp);
        retakeTestApplicationID = retakeApp.applicationID;
      }
      console.log("2");

      const totalFees = isRetake
        ? (testTypeInfo?.test_fees ?? 0) + retakeFees
        : (testTypeInfo?.test_fees ?? 0);
      console.log("3");

      const payload = {
        testTypeID: activeSection.testTypeId,
        localDrivingLicenseApplicationID,
        appointmentDate: new Date(date).toISOString(),
        paidFees: totalFees,
        isLocked: false,
        createdByUserID: currentUserID,
        ...(retakeTestApplicationID != null && { retakeTestApplicationID }),
      };
      console.log("4");

      console.log(payload);

      await dispatch(AddTestAppointment(payload)).unwrap();
      setDate("");
      setIsSaving(false);
      onClose();
    } catch (err) {
      setIsSaving(false);
      setDateError("Failed to save the appointment. Please try again.");
      console.log(err);
    }
  };

  const renderSection = (section, index) => {
    const Icon = section.icon;
    const isActive = index === activeSectionIndex;
    const testTypeInfo = testTypesList?.find(
      (t) => t.test_type_id === section.testTypeId,
    );

    return (
      <React.Fragment key={section.testTypeId}>
        <Paper
          variant="outlined"
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 2,
            p: 2,
            mb: isActive && isRetake ? 0 : 2,
            opacity: isActive ? 1 : 0.5,
            pointerEvents: isActive ? "auto" : "none",
          }}
        >
          <Box
            sx={{
              width: 64,
              height: 64,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <Icon
              sx={{ fontSize: 40 }}
              color={isActive ? "primary" : "disabled"}
            />
          </Box>

          <Box
            sx={{
              flex: 1,
              display: "flex",
              flexWrap: "wrap",
              alignItems: "center",
              gap: 2,
            }}
          >
            <Typography sx={{ width: "100%", fontWeight: "bold" }}>
              {testTypeInfo?.test_type_title ?? section.label}
              {isActive && isRetake ? " (Retake)" : ""}
            </Typography>
            <TextField
              label="D.L.App.ID"
              value={localDrivingLicenseApplicationID ?? ""}
              InputProps={{ readOnly: true }}
              size="small"
            />
            <TextField
              label="D.Class"
              value={applicationRow?.class_name ?? ""}
              InputProps={{ readOnly: true }}
              size="small"
            />
            <TextField
              label="Name"
              value={applicationRow?.full_name ?? ""}
              InputProps={{ readOnly: true }}
              size="small"
            />
            <TextField
              label="Trial"
              value={testCount}
              InputProps={{ readOnly: true }}
              size="small"
              sx={{ width: 80 }}
            />
            <TextField
              label="Date"
              type="date"
              value={isActive ? date : ""}
              onChange={(e) => setDate(e.target.value)}
              size="small"
              InputLabelProps={{ shrink: true }}
              disabled={!isActive || isSaving}
              inputProps={{ min: todayStr }}
              error={isActive && !!dateError}
              helperText={isActive ? dateError : ""}
            />
            <TextField
              label="Fees"
              value={testTypeInfo?.test_fees ?? ""}
              InputProps={{ readOnly: true }}
              size="small"
              sx={{ width: 100 }}
            />
          </Box>
        </Paper>

        {isActive && isRetake && (
          <RetakeTest
            retakeFees={retakeFees}
            testFees={testTypeInfo?.test_fees}
          />
        )}
      </React.Fragment>
    );
  };

  return (
    <Dialog open={open} onClose={handleCancel} maxWidth="md" fullWidth>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          p: 1,
        }}
      >
        <DialogTitle sx={{ p: 1 }}>Add Test</DialogTitle>
        <IconButton onClick={handleCancel} size="small" disabled={isSaving}>
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>

      <DialogContent>
        {TEST_SECTIONS.map((section, index) => renderSection(section, index))}
      </DialogContent>

      <DialogActions sx={{ justifyContent: "center", gap: 2, p: 2 }}>
        <Button variant="outlined" onClick={handleCancel} disabled={isSaving}>
          Cancel
        </Button>
        <Button
          variant="contained"
          onClick={handleSave}
          disabled={activeSectionIndex === -1 || !date || isSaving}
        >
          {isSaving ? "Saving..." : "Save"}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default AddTest;
