import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  error: null,
};

export const getLicenseClasses = createAsyncThunk(
  "LicenseClass/getLicenseClasses",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/LicenseClasses",
    );
    return response.data;
  },
  {
    condition: (_, { getState }) => {
      const { LicenseClass } = getState();
      if (LicenseClass.status === "loading" || LicenseClass.list.length > 0) {
        return false;
      }
      return true;
    },
  },
);

// ✅ جديد: جلب صنف واحد بالـ id — إذا موجود أصلاً بالـ list ما بيعمل request
export const getLicenseClassByID = createAsyncThunk(
  "LicenseClass/getLicenseClassByID",
  async (licenseClassId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/LicenseClasses/${licenseClassId}`,
    );
    return response.data;
  },
  {
    condition: (licenseClassId, { getState }) => {
      const { LicenseClass } = getState();

      if (LicenseClass.list && LicenseClass.list.length > 0) {
        const existingClass = LicenseClass.list.find(
          (c) => c.license_class_id === licenseClassId,
        );

        if (existingClass) {
          return false; // موجود أصلاً بالـ list، ما في داعي لطلب جديد
        }
      }
      return true;
    },
  },
);

const LicenseClassSlice = createSlice({
  name: "LicenseClass",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(getLicenseClasses.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getLicenseClasses.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.list = action.payload;
      })
      .addCase(getLicenseClasses.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(getLicenseClassByID.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getLicenseClassByID.fulfilled, (state, action) => {
        state.status = "succeeded";
        const normalized = {
          license_class_id: action.payload.licenseClassID,
          class_name: action.payload.className,
          class_description: action.payload.classDescription,
          class_fees: action.payload.classFees,
          minimum_allowed_age: action.payload.minimumAllowedAge,
          default_validity_length: action.payload.defaultValidityLength,
        };
        const index = state.list.findIndex(
          (c) => c.license_class_id === normalized.license_class_id,
        );
        if (index !== -1) {
          state.list[index] = normalized;
        } else {
          state.list.push(normalized);
        }
      })
      .addCase(getLicenseClassByID.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

export default LicenseClassSlice.reducer;
