import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [], // هنا رح تنخزن قائمة الـ people
  SelectedPerson: [], // هنا رح تنخزن قائمة الـ people
  currentPerson: null, // لتخزين بيانات الشخص الحالي بعد تسجيل الدخول
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  addStatus: "idel",
  updatingingstatus: "idel",
  deletingstatus: "idle",
  error: null,
};

// createAsyncThunk بيولّد تلقائياً 3 حالات (actions):
// people/getPeople/pending  -> قبل ما يوصل الرد
// people/getPeople/fulfilled -> لما يوصل الرد بنجاح
// people/getPeople/rejected  -> لما يصير خطأ
export const getPeople = createAsyncThunk(
  "people/getPeople",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/Persons",
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (_, { getState }) => {
      const { people } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (people.status === "loading" || people.list.length > 0) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);
export const getPersonById = createAsyncThunk(
  "people/getPersonById",
  async (personId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Persons/${personId}`,
    );
    return response.data; // الـ response عبارة عن object مباشرة حسب الـ Swagger
  },
  {
    condition: (personId, { getState }) => {
      const { people } = getState();
      const exists = people.list.some((p) => p.person_id === personId);
      return !exists;
    },
  },
);
export const getPersonByNoId = createAsyncThunk(
  "people/getPersonByNoId",
  async (NID) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Persons/national/${NID}`,
    );
    return response.data; // الـ response عبارة عن object مباشرة حسب الـ Swagger
  },
  {
    condition: (NID, { getState }) => {
      const { people } = getState();
      const exists = people.list.some((p) => p.person_id === NID);
      return !exists;
    },
  },
);
export const GetCurrentPerson = createAsyncThunk(
  "people/getCurrentPerson",
  async (personId) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Persons/${personId}`,
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
  {
    condition: (personId, { getState }) => {
      const { people } = getState();
      if (
        people.currentPerson !== null &&
        people.currentPerson.personID === personId
      ) {
        return false; // ✅ نفس الشخص موجود أصلاً، لا تكمل
      }
      return true; // غير هيك، لازم تجيب البيانات
    },
  },
);
export const AddPerson = createAsyncThunk(
  "people/AddPerson",
  async (person) => {
    const response = await axios.post(
      `https://idnan820-001-site1.ltempurl.com/api/Persons/`,
      person,
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
);
export const DeletPerson = createAsyncThunk(
  "people/DeletPerson",
  async (personId, { rejectWithValue }) => {
    try {
      const response = await axios.delete(
        `https://idnan820-001-site1.ltempurl.com/api/Persons/${personId}`,
      );
      return response.data;
    } catch (err) {
      // نلتقط رسالة السيرفر الحقيقية من body الاستجابة
      return rejectWithValue(
        err.response?.data?.message || err.response?.data || "Delete failed",
      );
    }
  },
);
export const UpdatePerson = createAsyncThunk(
  "people/UpdatePerson",
  async (person) => {
    const response = await axios.put(
      `https://idnan820-001-site1.ltempurl.com/api/Persons/${person.personID}`,
      person,
    );
    return response.data; // الـ response عبارة عن array مباشرة حسب الـ Swagger
  },
);
const peopleSlice = createSlice({
  name: "people",
  initialState,
  reducers: {
    addPersonTolist: (state, action) => {
      // action.payload لازم يكون object للشخص المراد إضافته
      state.list.push(action.payload);
    },
    updatePersonLocally: (state, action) => {
      const index = state.list.findIndex(
        (p) => p.person_id === action.payload.person_id,
      );
      if (index !== -1) {
        state.list[index] = action.payload;
      }
    },
    resetAddStatus: (state) => {
      // ✅ جديد
      state.addStatus = "idle";
    },
    resetUpdateStatus: (state) => {
      // ✅ جديد
      state.updatingingstatus = "idle";
    },
    resetDeleteStatus: (state) => {
      state.deletingstatus = "idle";
    },
  },

  // extraReducers: هون بنتعامل مع الأكشنز اللي جاية من الـ thunk (خارجية عن reducers العادية)
  extraReducers: (builder) => {
    builder
      .addCase(getPeople.pending, (state) => {
        state.status = "loading";
        console.log("Im pepole Not done yet");
        state.error = null;
      })
      .addCase(getPeople.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Im pepole done");
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getPeople.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(GetCurrentPerson.pending, (state, action) => {
        state.status = "loading";
        console.log("Cureent User Full Info has been work on it");
        state.error = null;
      })
      .addCase(GetCurrentPerson.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("Cureent User Full Info has arive");
        state.currentPerson = action.payload;
      })
      .addCase(GetCurrentPerson.rejected, (state, action) => {
        state.status = "failed";
        console.log("Cureent User Full Info has Not arive");
        state.error = action.error.message;
      })
      .addCase(AddPerson.fulfilled, (state, action) => {
        state.addStatus = "succeeded";

        const newPerson = {
          person_id: action.payload.personID,
          first_name: action.payload.firstName,
          second_name: action.payload.secondName,
          third_name: action.payload.thirdName,
          last_name: action.payload.lastName,
          national_no: action.payload.nationalNo,
          date_of_birth: action.payload.dateOfBirth,
          gendor_caption: action.payload.gendor === 1 ? "Male" : "Female",
          phone: action.payload.phone,
          email: action.payload.email,
          nationality_country_id: action.payload.nationalityCountryID,
          address: action.payload.address,
          image_path: action.payload.imagePath,
        };

        // نستبدل بس أول صف لسه من غير id حقيقي، مش نمسحهم كلهم
        const pendingIndex = state.list.findIndex(
          (p) => p.person_id === undefined,
        );

        if (pendingIndex !== -1) {
          state.list[pendingIndex] = newPerson;
        } else {
          state.list.push(newPerson);
        }
      })
      .addCase(AddPerson.rejected, (state, action) => {
        state.addStatus = "faild";
        console.log("Person has not succeeded");
        state.error = action.error.message;
      })
      .addCase(UpdatePerson.fulfilled, (state, action) => {
        state.updatingingstatus = "succeeded";
        console.log("UpdatePerson  succeeded");
      })
      .addCase(UpdatePerson.rejected, (state, action) => {
        state.updatingingstatus = "faild";
        console.log("UpdatePerson has not succeeded");
        state.error = action.error.message;
        console.log(state.error);
      })
      .addCase(DeletPerson.pending, (state, action) => {
        state.deletingstatus = "loading";
        console.log("Delet Prson work on it ");
        state.error = null;
      })
      .addCase(DeletPerson.fulfilled, (state, action) => {
        state.deletingstatus = "succeeded";
        console.log("Delet Prson succeeded ");
        state.list = state.list.filter((p) => p.person_id !== action.meta.arg);
        state.error = null;
      })
      .addCase(DeletPerson.rejected, (state, action) => {
        state.deletingstatus = "failed";
        console.log("action.payload:", action.payload);
        console.log("action.error:", action.error);
        console.log("Delet Prson have faild");
        state.error = action.payload;
      })
      .addCase(getPersonById.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("getPersonById succeeded");
        const person = action.payload;
        state.SelectedPerson = action.payload;
        const index = state.list.findIndex(
          (p) => p.person_id === person.personID,
        );
        if (index !== -1) {
          state.list[index] = person;
        }
      })
      .addCase(getPersonById.rejected, (state, action) => {
        console.error("Failed to fetch person by ID:", action.error);
      })
      .addCase(getPersonByNoId.fulfilled, (state, action) => {
        state.status = "succeeded";
        console.log("getPersonById succeeded");
        const person = action.payload;
        const index = state.list.findIndex(
          (p) => p.person_id === person.personID,
        );
        if (index !== -1) {
          state.list[index] = person;
        }
      })
      .addCase(getPersonByNoId.rejected, (state, action) => {
        console.error("Failed to fetch person by ID:", action.error);
      });
  },
});

export const selectPersonById = (state, personId) =>
  state.people.list.find((p) => p.person_id === personId);
export const {
  addPersonTolist,
  updatePersonLocally,
  resetAddStatus,
  resetUpdateStatus,
  resetDeleteStatus,
} = peopleSlice.actions;
export default peopleSlice.reducer;
