import React from "react";
import { useEffect } from "react";
import { Box, Typography, Button, Avatar } from "@mui/material";
import PersonIcon from "@mui/icons-material/Person";
import BadgeIcon from "@mui/icons-material/Badge";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import PhoneIcon from "@mui/icons-material/Phone";
import EmailIcon from "@mui/icons-material/Email";
import PublicIcon from "@mui/icons-material/Public";
import HomeIcon from "@mui/icons-material/Home";
import { useSelector, useDispatch } from "react-redux";
import {
  selectPersonById,
  getPersonById,
} from "../../Store/features/people/peopleSlice";
function ReadOnlyRow({ icon: Icon, label, value, highlight }) {
  return (
    <Box className="profile-readonly-row" sx={{ flex: 1, minWidth: 0 }}>
      {Icon && (
        <Icon
          className="profile-readonly-icon"
          sx={{ fontSize: "1.1rem !important" }}
        />
      )}
      <Typography
        className="profile-readonly-label"
        sx={{ fontSize: "0.95rem !important", minWidth: 110 }}
      >
        {label}:
      </Typography>
      <Typography
        className="profile-readonly-value"
        component="span"
        sx={{
          fontSize: "0.95rem !important",
          ...(highlight && {
            color: "var(--color-danger-alt)",
            fontWeight: 700,
          }),
        }}
      >
        {value || "—"}
      </Typography>
    </Box>
  );
}

// ✅ مكوّن "Person Information" القابل لإعادة الاستخدام — مِلك شاشة People فقط.
// Users / Detained License إلهم بانل خاص منفصل، وInternational+Local+Drivers
// إلهم بانل مشترك تاني منفصل عن هذا.
// لا يحتوي منطق فتح/إغلاق ولا جلب بيانات — للعرض فقط (Presentational)
export default function PersonInfoPanel({ personId, onEditPersonInfo }) {
  const person = useSelector((state) => selectPersonById(state, personId));

  if (!person) {
    return null;
    // ✅ لازم يرجع هنا قبل أي استخدام لـ person.xxx
  }
  console.log("PersonInfoPanel RENDER2222222", personId, person); // ✅ ضيف هيك سطر وحيد
  return (
    <Box className="profile-section">
      <Box className="profile-section-header-row">
        <Typography className="profile-section-title">
          Person Information
        </Typography>
        {onEditPersonInfo && (
          <Button
            onClick={onEditPersonInfo}
            className="profile-edit-link"
            size="small"
          >
            Edit Person Info
          </Button>
        )}
      </Box>

      <Box className="profile-person-body">
        <Box className="profile-person-fields" sx={{ gap: "18px !important" }}>
          <ReadOnlyRow
            icon={BadgeIcon}
            label="Person ID"
            value={person.person_id}
          />
          <ReadOnlyRow
            icon={PersonIcon}
            label="Name"
            value={
              person.first_name +
              " " +
              person.second_name +
              " " +
              person.third_name
            }
            highlight
          />

          <Box className="person-form-row" sx={{ gap: "32px !important" }}>
            <ReadOnlyRow
              icon={BadgeIcon}
              label="National No"
              value={person.national_no}
            />
            <ReadOnlyRow
              icon={CalendarTodayIcon}
              label="Date Of Birth"
              value={person.date_of_birth}
            />
          </Box>

          <Box className="person-form-row">
            <ReadOnlyRow
              icon={PersonIcon}
              label="Gender"
              value={person.gendor_caption}
            />
            <ReadOnlyRow icon={PhoneIcon} label="Phone" value={person.phone} />
          </Box>

          <Box className="person-form-row">
            <ReadOnlyRow icon={EmailIcon} label="Email" value={person.email} />
            <ReadOnlyRow
              icon={PublicIcon}
              label="Country"
              value={person.country_name}
            />
          </Box>

          <ReadOnlyRow icon={HomeIcon} label="Address" value={person.address} />
        </Box>

        <Avatar
          src={person.photo}
          className="profile-person-avatar"
          sx={{ width: "120px !important", height: "120px !important" }}
        >
          {!person.photo && <PersonIcon className="profile-avatar-icon" />}
        </Avatar>
      </Box>
    </Box>
  );
}
