import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Snackbar,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import PeopleAltIcon from "@mui/icons-material/PeopleAlt";
import { Box as MuiBox, Typography } from "@mui/material";
//*************Loading Tools */
import CircularProgress from "../Popups/LodaingCircul";
import FeildAlert from "../Popups/FailedAlert";
import Alert from "@mui/material/Alert";
//*************Loading Tools */

// Redux imports
import { useSelector, useDispatch } from "react-redux";
import {
  addPerson,
  getPeople,
  resetAddStatus,
  resetUpdateStatus,
} from "../Store/features/people/peopleSlice";
import { getCountry } from "../Store/features/Country/countrySlice";
import Filter from "../Shared/Filter";
import AddPerson from "../Add/AddPerson";
import UpdatePerson from "../Update/UpdatePerson";
import DeletePerson from "../Delete/DeletePerson";
import PersonDetailsModal from "../Popups/PersonDetailsModal";

// label المعروض في الـ Select -> اسم الـ property الفعلي جوه كل row
const FILTER_FIELD_MAP = {
  PersonID: "id",
  NationalNo: "nationalNo",
  FullName: "fullName",
  Email: "email",
  Phone: "phone",
};

// شاشة Manage People — Component عرض فقط (Logic منفصل لاحقًا عبر Redux)
// لا توجد بيانات وهمية: rows تبدأ فارغة بانتظار ربط الـ API الحقيقي
export default function ManagePeopleScreen() {
  const [filterBy, setFilterBy] = useState("None");
  const [searchValue, setSearchValue] = useState("");
  const [isAddOpen, setIsAddOpen] = useState(false);

  // ── حالة صف مختار / الشاشات المنبثقة المرتبطة به ──
  const [detailsPersonId, setDetailsPersonId] = useState(null);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false);
  const [updatePersonId, setUpdatePersonId] = useState(null);
  const [isUpdateOpen, setIsUpdateOpen] = useState(false);
  const [deletePersonId, setDeletePersonId] = useState(null);
  const [isDeleteOpen, setIsDeleteOpen] = useState(false);

  const dispatch = useDispatch();

  // useSelector: بيقرأ فقط الجزء الخاص بـ people من الـ state الكلي
  const people = useSelector((state) => state.people.list);
  const status = useSelector((state) => state.people.status);
  const Addingstatus = useSelector((state) => state.people.addStatus);
  const Updatingingstatus = useSelector(
    (state) => state.people.updatingingstatus,
  );

  const [showSuccess, setShowSuccess] = useState(false);
  const [showUpdateSuccess, setShowUpdateSuccess] = useState(false); // ✅ جديد

  useEffect(() => {
    if (Addingstatus === "succeeded") {
      setShowSuccess(true);
    }
  }, [Addingstatus]);

  useEffect(() => {
    if (Updatingingstatus === "succeeded") {
      setShowUpdateSuccess(true);
    }
  }, [Updatingingstatus]); // ✅ جديد

  useEffect(() => {
    dispatch(getPeople());
  }, [dispatch]);
  useEffect(() => {
    dispatch(getCountry());
  }, [dispatch]);

  if (status === "loading") {
    return <CircularProgress></CircularProgress>;
  }

  if (status === "failed") {
    return <FeildAlert> No Data Here, pleas call support</FeildAlert>;
  }
  const rows = people.map((person) => ({
    id: person.person_id,
    nationalNo: person.national_no,
    fullName: `${person.first_name} ${person.last_name}`,
    dateOfBirth: person.date_of_birth,
    gender: person.gender === 1 ? "Male" : "Female",
    phone: person.phone,
    email: person.email,
  }));

  // ── الفلترة الفعلية: fieldKey بيترجم الـ label المختار في الـ Select ──
  // ── لاسم الـ property الحقيقي جوه الـ row (مش اسم الـ label نفسه) ──
  const filteredRows =
    filterBy === "None" || !searchValue.trim()
      ? rows
      : rows.filter((row) => {
          const fieldKey = FILTER_FIELD_MAP[filterBy]; // مثلاً "email"
          const cellValue = row[fieldKey];
          return String(cellValue ?? "")
            .toLowerCase()
            .includes(searchValue.trim().toLowerCase());
        });

  // ── معالجات الضغط على صف (double-click) وأزرار PersonDetailsModal ──
  const handleRowDoubleClick = (row) => {
    setDetailsPersonId(row.id);
    setIsDetailsOpen(true);
  };
  const handleSnackbarClose = () => {
    dispatch(resetAddStatus()); // ✅ يرجّع addStatus لـ idle
    setShowSuccess(false);
  };
  const handleUpdateSnackbarClose = () => {
    dispatch(resetUpdateStatus()); // ✅ يرجّع updatingingstatus لـ idle
    setShowUpdateSuccess(false);
  };
  const handleUpdate = (personId) => {
    setIsDetailsOpen(false);
    setUpdatePersonId(personId);
    setIsUpdateOpen(true);
  };

  const handleDelete = (personId) => {
    setIsDetailsOpen(false);
    setDeletePersonId(personId);
    setIsDeleteOpen(true);
  };

  return (
    <Box className="manage-people-page">
      <Paper elevation={0} className="manage-people-paper">
        <MuiBox className="people-header-wrapper">
          <MuiBox className="people-header-icon-wrapper">
            <PeopleAltIcon className="people-header-icon" />
          </MuiBox>
          <Typography variant="h4" className="people-header-title">
            Manage People
          </Typography>
          <Typography variant="h6" className="people-header-title">
            (Select Row and double click on it)
          </Typography>
        </MuiBox>

        <Box className="people-toolbar-row">
          <Filter
            fieldMap={FILTER_FIELD_MAP}
            value={filterBy}
            onChange={(e) => {
              setFilterBy(e.target.value);
              setSearchValue(""); // نفضّي قيمة البحث القديمة لما يغيّر نوع الفلتر
            }}
            searchValue={searchValue}
            onSearchChange={(e) => setSearchValue(e.target.value)}
          />

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => setIsAddOpen(true)}
            className="people-add-btn"
          >
            Add Person
          </Button>
        </Box>

        <TableContainer className="people-table-container">
          <Table className="people-table">
            <TableHead className="people-table-head">
              <TableRow>
                <TableCell className="people-table-head-cell">
                  Person ID
                </TableCell>
                <TableCell className="people-table-head-cell">
                  National No.
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Full Name
                </TableCell>
                <TableCell className="people-table-head-cell">
                  Date Of Birth
                </TableCell>
                <TableCell className="people-table-head-cell">Gender</TableCell>
                <TableCell className="people-table-head-cell">Phone</TableCell>
                <TableCell className="people-table-head-cell">Email</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredRows.map((row) => (
                <TableRow
                  key={row.id}
                  className="people-table-row"
                  onDoubleClick={() => handleRowDoubleClick(row)}
                  sx={{ cursor: "pointer" }}
                >
                  <TableCell className="people-table-cell-id">
                    {row.id}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.nationalNo}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.fullName}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.dateOfBirth}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.gender}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.phone}
                  </TableCell>
                  <TableCell className="people-table-cell">
                    {row.email}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Box className="people-table-footer">
          <Typography className="people-table-footer-count">
            # Records: {filteredRows.length}
          </Typography>
        </Box>
      </Paper>

      <AddPerson open={isAddOpen} onClose={() => setIsAddOpen(false)} />

      <PersonDetailsModal
        open={isDetailsOpen}
        onClose={() => setIsDetailsOpen(false)}
        personId={detailsPersonId}
        onUpdate={handleUpdate}
        onDelete={handleDelete}
      />

      <UpdatePerson
        open={isUpdateOpen}
        onClose={() => setIsUpdateOpen(false)}
        personId={updatePersonId}
      />

      <DeletePerson
        open={isDeleteOpen}
        onClose={() => setIsDeleteOpen(false)}
        personId={deletePersonId}
      />

      <Snackbar
        open={showSuccess}
        autoHideDuration={1000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          onClose={() => setShowSuccess(false)}
          severity="success"
          variant="filled"
        >
          تمت إضافة الشخص بنجاح ✅
        </Alert>
      </Snackbar>

      <Snackbar
        open={showUpdateSuccess}
        autoHideDuration={1000}
        onClose={handleUpdateSnackbarClose}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert
          onClose={() => setShowUpdateSuccess(false)}
          severity="success"
          variant="filled"
        >
          تم تعديل البيانات بنجاح ✅
        </Alert>
      </Snackbar>
    </Box>
  );
}
