import Alert from "@mui/material/Alert";
import Stack from "@mui/material/Stack";

export default function OutlinedAlerts({ children }) {
  return (
    <Stack
      sx={{ width: "100%", justifyContent: "center", display: "flex" }}
      spacing={2}
    >
      <Alert
        sx={{
          justifyContent: "center",
        }}
        variant="outlined"
        severity="error"
      >
        {children}
      </Alert>
    </Stack>
  );
}
