import React, { useState, useCallback } from "react";
import {
  Box,
  Drawer,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider,
  Collapse,
  IconButton,
} from "@mui/material";
import {
  PeopleAlt,
  DriveEta,
  ManageAccounts,
  Close,
  ExpandLess,
  ExpandMore,
  Folder,
  ChevronRight,
  Settings,
  Info,
} from "@mui/icons-material";
import { Link, useNavigate } from "react-router-dom";

import CurrentUserInfoPanel from "../Popups/CurrentUserInfoPanel";
import ManageApplicationTypesScreen from "../Screens/ManageApplicationTypesScreen";
import ManageTestTypesScreen from "../Screens/ManageTestTypesScreen";
import { clearSession } from "../utils/session";
import AddDetainedLicense from "../Add/AddDetainedLicense";
import ReleaseDetainedLicense from "../Update/ReleaseDetainedLicense";

// نسخة الموبايل من التنقّل — كل شيء يعمل بالديسكتوب يعمل هنا أيضًا
// (نفس الربط الموجود في TopBarButtons لكن بواجهة Drawer جانبية)
//
// ملاحظة: Local Driving License Applications / International License
// Applications / Manage Detained Licenses صارت صفحات كاملة (Full Pages)
// تُستدعى عبر Link بنفس أسلوب People/Users/Drivers، بدل فتحها كـ Dialog
// محلي داخل هذا الكومبوننت.
export default function MobileMainScreen({ open, onClose }) {
  const navigate = useNavigate();
  const [appsOpen, setAppsOpen] = useState(false);
  const [manageAppsOpen, setManageAppsOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);

  const [isAppTypesOpen, setIsAppTypesOpen] = useState(false);
  const [isTestTypesOpen, setIsTestTypesOpen] = useState(false);
  const [isDetainOpen, setIsDetainOpen] = useState(false);
  const [isReleaseOpen, setIsReleaseOpen] = useState(false);
  const [isCurrentUserOpen, setIsCurrentUserOpen] = useState(false);

  const toggleApps = useCallback(() => setAppsOpen((v) => !v), []);
  const toggleManageApps = useCallback(() => setManageAppsOpen((v) => !v), []);
  const toggleSettings = useCallback(() => setSettingsOpen((v) => !v), []);

  const handleSignOut = useCallback(() => {
    onClose();
    clearSession();
    // لاحقاً هنا فقط: dispatch(signOut())
    navigate("/login");
  }, [onClose, navigate]);

  return (
    <>
      <Drawer
        anchor="left"
        open={open}
        onClose={onClose}
        sx={{ display: { xs: "block", md: "none" } }}
      >
        <Box className="nav-drawer-content">
          <Box className="nav-drawer-header">
            <IconButton onClick={onClose} className="nav-drawer-close-btn">
              <Close />
            </IconButton>
          </Box>

          <Divider className="nav-drawer-divider" />

          <List component="nav" className="nav-drawer-list">
            {/* ─── Applications ─── */}
            <ListItem disablePadding>
              <ListItemButton onClick={toggleApps}>
                <ListItemIcon className="nav-drawer-icon">
                  <Folder />
                </ListItemIcon>
                <ListItemText primary="Applications" />
                {appsOpen ? <ExpandLess /> : <ExpandMore />}
              </ListItemButton>
            </ListItem>

            <Collapse in={appsOpen} timeout="auto" unmountOnExit>
              <List
                component="div"
                disablePadding
                className="nav-drawer-submenu"
              >
                {/* Manage Applications */}
                <ListItemButton onClick={toggleManageApps}>
                  <ListItemText primary="Manage Applications" />
                  {manageAppsOpen ? <ExpandLess /> : <ExpandMore />}
                </ListItemButton>
                <Collapse in={manageAppsOpen} timeout="auto" unmountOnExit>
                  <List
                    component="div"
                    disablePadding
                    className="nav-drawer-submenu-items"
                  >
                    <ListItemButton
                      component={Link}
                      to="/manage-Local"
                      onClick={onClose}
                    >
                      <ChevronRight fontSize="small" />
                      <ListItemText primary="Local Driving License Applications" />
                    </ListItemButton>
                    <ListItemButton
                      component={Link}
                      to="/manage-International"
                      onClick={onClose}
                    >
                      <ChevronRight fontSize="small" />
                      <ListItemText primary="International License Applications" />
                    </ListItemButton>
                  </List>
                </Collapse>

                <ListItemButton
                  component={Link}
                  to="/manage-DetainedLicensesS"
                  onClick={onClose}
                >
                  <ListItemText primary="Manage Detained Licenses" />
                </ListItemButton>
                <ListItemButton
                  onClick={() => {
                    onClose();
                    setIsDetainOpen(true);
                  }}
                >
                  <ListItemText primary="Detain License" />
                </ListItemButton>
                <ListItemButton
                  onClick={() => {
                    onClose();
                    setIsReleaseOpen(true);
                  }}
                >
                  <ListItemText primary="Release Detained License" />
                </ListItemButton>

                <ListItemButton
                  onClick={() => {
                    onClose();
                    setIsAppTypesOpen(true);
                  }}
                >
                  <ListItemText primary="Manage Application Types" />
                </ListItemButton>
                <ListItemButton
                  onClick={() => {
                    onClose();
                    setIsTestTypesOpen(true);
                  }}
                >
                  <ListItemText primary="Manage Test Types" />
                </ListItemButton>
              </List>
            </Collapse>

            {/* ─── People / Drivers / Users ─── */}
            <ListItem disablePadding>
              <ListItemButton
                component={Link}
                to="/manage-people"
                onClick={onClose}
              >
                <ListItemIcon className="nav-drawer-icon">
                  <PeopleAlt />
                </ListItemIcon>
                <ListItemText primary="People" />
              </ListItemButton>
            </ListItem>

            <ListItem disablePadding>
              <ListItemButton
                component={Link}
                to="/manage-drivers"
                onClick={onClose}
              >
                <ListItemIcon className="nav-drawer-icon">
                  <DriveEta />
                </ListItemIcon>
                <ListItemText primary="Drivers" />
              </ListItemButton>
            </ListItem>

            <ListItem disablePadding>
              <ListItemButton
                component={Link}
                to="/manage-users"
                onClick={onClose}
              >
                <ListItemIcon className="nav-drawer-icon">
                  <ManageAccounts />
                </ListItemIcon>
                <ListItemText primary="Users" />
              </ListItemButton>
            </ListItem>

            <Divider className="nav-drawer-divider" sx={{ my: 1 }} />

            {/* ─── Account Settings ─── */}
            <ListItem disablePadding>
              <ListItemButton onClick={toggleSettings}>
                <ListItemIcon className="nav-drawer-icon">
                  <Settings />
                </ListItemIcon>
                <ListItemText primary="Account Settings" />
                {settingsOpen ? <ExpandLess /> : <ExpandMore />}
              </ListItemButton>
            </ListItem>
            <Collapse in={settingsOpen} timeout="auto" unmountOnExit>
              <List
                component="div"
                disablePadding
                className="nav-drawer-submenu-items"
              >
                <ListItemButton
                  onClick={() => {
                    onClose();
                    setIsCurrentUserOpen(true);
                  }}
                >
                  <ListItemIcon className="nav-drawer-icon-white">
                    <Info fontSize="small" />
                  </ListItemIcon>
                  <ListItemText primary="Current User Info" />
                </ListItemButton>
                <ListItemButton onClick={handleSignOut}>
                  <ListItemIcon className="nav-drawer-icon-danger">
                    <Close fontSize="small" />
                  </ListItemIcon>
                  <ListItemText
                    primary="Sign Out"
                    className="nav-drawer-item-danger"
                  />
                </ListItemButton>
              </List>
            </Collapse>
          </List>
        </Box>
      </Drawer>

      <CurrentUserInfoPanel
        open={isCurrentUserOpen}
        onClose={() => setIsCurrentUserOpen(false)}
        person={null}
      />
      <ManageApplicationTypesScreen
        open={isAppTypesOpen}
        onClose={() => setIsAppTypesOpen(false)}
      />
      <ManageTestTypesScreen
        open={isTestTypesOpen}
        onClose={() => setIsTestTypesOpen(false)}
      />
      <AddDetainedLicense
        open={isDetainOpen}
        onClose={() => setIsDetainOpen(false)}
      />
      <ReleaseDetainedLicense
        open={isReleaseOpen}
        onClose={() => setIsReleaseOpen(false)}
      />
    </>
  );
}
