import React from "react";
import { Box, Typography, TextField, Button, Avatar } from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import PersonIcon from "@mui/icons-material/Person";
import BadgeIcon from "@mui/icons-material/Badge";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import DirectionsCarIcon from "@mui/icons-material/DirectionsCar";
import DescriptionIcon from "@mui/icons-material/Description";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import BadgeOutlinedIcon from "@mui/icons-material/BadgeOutlined";

function Field({ icon: Icon, label, value }) {
  const isEmpty = value === undefined || value === null || value === "";
  return (
    <Box className="license-info-field">
      <Box className="license-info-field-label">
        {Icon && <Icon className="license-info-field-icon" />}
        {label}
      </Box>
      <Typography
        className={
          isEmpty
            ? "license-info-field-value license-info-field-value-empty"
            : "license-info-field-value"
        }
      >
        {isEmpty ? "Not searched yet" : value}
      </Typography>
    </Box>
  );
}

// ✅ مكوّن "Driver License Info" + Filter القابل لإعادة الاستخدام —
// بطاقة منظّمة بشبكة عمودين بدل قائمة مضغوطة
export default function DriverLicenseInfoPanel({
  licenseId,
  onLicenseIdChange,
  onSearch,
  license,
  personName,
}) {
  return (
    <>
      <Box className="license-filter-row">
        <TextField
          label="License ID"
          placeholder="Enter license ID..."
          value={licenseId}
          onChange={onLicenseIdChange}
          className="modal-textfield"
          fullWidth
        />
        <Button
          onClick={onSearch}
          variant="outlined"
          startIcon={<SearchIcon />}
          className="user-verify-btn"
        >
          Search
        </Button>
      </Box>

      <Box className="license-info-card">
        <Box className="license-info-card-header">
          <BadgeOutlinedIcon className="license-info-card-header-icon" />
          <Typography className="license-info-card-title">
            DRIVER LICENSE INFO
          </Typography>
        </Box>

        <Box className="license-info-body">
          <Box className="license-info-fields-grid">
            <Field
              icon={DirectionsCarIcon}
              label="Class"
              value={license?.licenseClass}
            />
            <Field icon={PersonIcon} label="Name" value={personName} />
            <Field icon={BadgeIcon} label="License ID" value={license?.id} />
            <Field
              icon={CheckCircleIcon}
              label="Is Active?"
              value={license ? (license.isActive ? "Yes" : "No") : undefined}
            />
            <Field
              icon={CalendarTodayIcon}
              label="Date Of Birth"
              value={license?.dateOfBirth}
            />
            <Field
              icon={BadgeIcon}
              label="Driver ID"
              value={license?.driverId}
            />
            <Field
              icon={CalendarTodayIcon}
              label="Issue Date"
              value={license?.issueDate}
            />
            <Field
              icon={CalendarTodayIcon}
              label="Expiration Date"
              value={license?.expirationDate}
            />
            <Field
              icon={DescriptionIcon}
              label="Issue Reason"
              value={license?.issueReason}
            />
            <Field
              icon={CheckCircleIcon}
              label="Is Detained?"
              value={license ? (license.isDetained ? "Yes" : "No") : undefined}
            />
            <Field
              icon={DescriptionIcon}
              label="Notes"
              value={license?.notes}
            />
          </Box>

          <Avatar src={license?.photo} className="license-info-avatar">
            {!license?.photo && (
              <PersonIcon className="license-info-avatar-icon" />
            )}
          </Avatar>
        </Box>
      </Box>
    </>
  );
}
