import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import LockOpenIcon from "@mui/icons-material/LockOpen";

import LicenseFilter from "../License/LicenseFilter";
import { LicenseInfoContent } from "../License/Showlicenseinfo";
import DTNInfo from "./DTNInfo";
import {
  getLicenses,
  releaseDetainedLicense,
} from "../../Store/features/Licenses/LicensesSlice";
import {
  getDetainedLicenses,
  markDetainReleasedLocally,
} from "../../Store/features/DetainedLicenses/DetainedLicensesSlice"; // ⚠️ عدّل المسار حسب مكان الملف عندك
import { getApplicationTypes } from "../../Store/features/ApplicationType/ApplicationTypeSlice";

const RELEASE_APPLICATION_TYPE_ID = 5;
const FALLBACK_APPLICATION_FEES = 50;

export default function ReleaseDetainedLicenseModal({ open, onClose }) {
  const dispatch = useDispatch();

  const [filterInput, setFilterInput] = useState("");
  const [committedLicenseId, setCommittedLicenseId] = useState(null);
  const [searchError, setSearchError] = useState(null);
  const [releasedApplicationId, setReleasedApplicationId] = useState(null);
  const [foundDetainRecord, setFoundDetainRecord] = useState(null);

  const currentUser = useSelector((state) => state.users.currentUser);
  const licensesList = useSelector((state) => state.licenses.list);
  const detainedList = useSelector((state) => state.DetainedLicenses.list); // ⚠️ عدّل اسم الـ slice لو مختلف
  const applicationTypes = useSelector((state) => state.ApplicationType.list);
  const releaseStatus = useSelector((state) => state.licenses.releaseStatus);
  const releaseError = useSelector((state) => state.licenses.error);

  const isLoading = releaseStatus === "loading";
  const alreadyReleased = Boolean(releasedApplicationId);
  const canRelease =
    Boolean(committedLicenseId) &&
    Boolean(foundDetainRecord) &&
    !isLoading &&
    !alreadyReleased;

  const applicationFees =
    applicationTypes.find(
      (t) => t.application_type_id === RELEASE_APPLICATION_TYPE_ID,
    )?.application_fees ?? FALLBACK_APPLICATION_FEES;

  useEffect(() => {
    if (!open) return;
    dispatch(getLicenses());
    dispatch(getDetainedLicenses());
    dispatch(getApplicationTypes());
  }, [open, dispatch]);

  const resetAll = () => {
    setFilterInput("");
    setCommittedLicenseId(null);
    setSearchError(null);
    setReleasedApplicationId(null);
    setFoundDetainRecord(null);
  };

  const handleClose = () => {
    resetAll();
    onClose();
  };

  const handleSearch = () => {
    const idNum = Number(filterInput);
    if (!idNum) {
      setSearchError("الرجاء إدخال رقم رخصة صحيح");
      setCommittedLicenseId(null);
      return;
    }

    const foundLicense = licensesList.find((l) => l.license_id === idNum);

    if (!foundLicense) {
      setSearchError("لا توجد رخصة بهذا الرقم");
      setCommittedLicenseId(null);
      return;
    }

    const activeRecord = detainedList.find(
      (d) => d.licenseID === idNum && !d.isReleased,
    );

    if (!activeRecord) {
      setSearchError("هذه الرخصة غير محتجزة (Detained) حاليًا");
      setCommittedLicenseId(null);
      setFoundDetainRecord(null);
      return;
    }

    setSearchError(null);
    setCommittedLicenseId(idNum);
    setFoundDetainRecord(activeRecord);
    setReleasedApplicationId(null);
  };

  const handleRelease = async () => {
    if (!committedLicenseId || !foundDetainRecord) return;
    try {
      const result = await dispatch(
        releaseDetainedLicense({
          licenseId: committedLicenseId,
          releasedByUserId: currentUser?.userID,
        }),
      ).unwrap();

      setReleasedApplicationId(result.applicationId);

      dispatch(
        markDetainReleasedLocally({
          detainID: foundDetainRecord.detainID,
          releasedByUserId: currentUser?.userID,
        }),
      );
    } catch (err) {
      console.error("Release detained license failed:", err);
    }
  };

  useEffect(() => {
    if (releaseStatus === "succeeded") {
      const timer = setTimeout(() => {
        handleClose();
      }, 2000);
      return () => clearTimeout(timer);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [releaseStatus]);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="modal-red-title">
          Release Detained License
        </Typography>

        <LicenseFilter
          value={filterInput}
          onChange={(e) => setFilterInput(e.target.value)}
          onSearch={handleSearch}
          error={searchError}
        />

        {committedLicenseId ? (
          <Box className="replace-license-license-info">
            <LicenseInfoContent licenseId={committedLicenseId} />
          </Box>
        ) : (
          <Typography className="replace-license-placeholder">
            ابحث برقم الرخصة أولاً
          </Typography>
        )}

        {committedLicenseId && foundDetainRecord && (
          <DTNInfo
            detainID={foundDetainRecord.detainID}
            licenseID={committedLicenseId}
            detainDate={foundDetainRecord.detainDate}
            createdByLabel={
              foundDetainRecord.createdByUserInfo?.userName ??
              foundDetainRecord.createdByUserID
            }
            applicationFees={applicationFees}
            fineFees={foundDetainRecord.fineFees}
            applicationID={releasedApplicationId}
          />
        )}

        {releaseStatus === "succeeded" && (
          <Alert severity="success" variant="filled" sx={{ mt: 2 }}>
            License released successfully ✅
          </Alert>
        )}

        {releaseStatus === "failed" && releaseError && (
          <Alert severity="error" variant="filled" sx={{ mt: 2 }}>
            {typeof releaseError === "string"
              ? releaseError
              : "فشل الإفراج عن الرخصة"}
          </Alert>
        )}
      </DialogContent>

      <DialogActions className="modal-actions">
        <Button
          variant="contained"
          color="error"
          startIcon={<CloseIcon />}
          onClick={handleClose}
          className="modal-btn-cancel"
        >
          Close
        </Button>
        <Button
          variant="contained"
          startIcon={
            isLoading ? (
              <CircularProgress size={16} color="inherit" />
            ) : (
              <LockOpenIcon />
            )
          }
          onClick={handleRelease}
          disabled={!canRelease}
          className="modal-btn-save"
        >
          Release
        </Button>
      </DialogActions>
    </Dialog>
  );
}
