import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [],
  status: "idle",
  error: null,
};

export const getApplicationByApplicationId = createAsyncThunk(
  "applications/getApplicationByApplicationId",
  async (applicationID) => {
    const response = await axios.get(
      `https://idnan820-001-site1.ltempurl.com/api/Applications/${applicationID}`,
    );
    return response.data;
  },
  {
    condition: (applicationId, { getState }) => {
      const { applications } = getState();

      if (applications.list && applications.list.length > 0) {
        const existingApplication = applications.list.find(
          (app) => app.applicationID === applicationId,
        );

        if (existingApplication) {
          return false; // موجود أصلاً، ألغِ الطلب
        }
      }
      return true; // ✅ غير موجود (أو الـ list فاضية) → كمّل الطلب
    },
  },
);

export const addApplication = createAsyncThunk(
  "applications/addApplication",
  async (applicationData, { getState }) => {
    const { users } = getState();

    const payload = {
      applicantPersonID: applicationData.applicantPersonID,
      applicationDate: applicationData.applicationDate,
      applicationTypeID: applicationData.applicationTypeID,
      applicationStatus: applicationData.applicationStatus,
      lastStatusDate: applicationData.lastStatusDate,
      paidFees: applicationData.paidFees,
      createdByUserID: users.currentUser.userID,
    };

    const response = await axios.post(
      "https://idnan820-001-site1.ltempurl.com/api/Applications",
      payload,
    );

    return response.data;
  },
);
export const updateApplicationStatus = createAsyncThunk(
  "applications/updateApplicationStatus",
  async (application, { rejectWithValue }) => {
    try {
      const response = await axios.put(
        `https://idnan820-001-site1.ltempurl.com/api/Applications/${application.applicationID}`,
        application,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || "Update application status failed",
      );
    }
  },
);
export const CanseldApplicationStatus = createAsyncThunk(
  "applications/CanseldApplicationStatus",
  async (id, { rejectWithValue }) => {
    try {
      const response = await axios.post(
        `https://idnan820-001-site1.ltempurl.com/api/Applications/${id}/cancel`,
      );
      return response.data;
    } catch (err) {
      return rejectWithValue(
        err.response?.data?.message || "Update application status failed",
      );
    }
  },
);
const applicationsSlice = createSlice({
  name: "applications",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(getApplicationByApplicationId.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getApplicationByApplicationId.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.list.push(action.payload);
      })
      .addCase(getApplicationByApplicationId.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(addApplication.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(addApplication.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.list.push(action.payload);
      })
      .addCase(addApplication.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      })
      .addCase(updateApplicationStatus.fulfilled, (state, action) => {
        state.status = "succeeded";
        const index = state.list.findIndex(
          (a) => a.applicationID === action.payload.applicationID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        }
      })
      .addCase(updateApplicationStatus.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.payload;
      })
      .addCase(CanseldApplicationStatus.fulfilled, (state, action) => {
        state.status = "succeeded";
        const index = state.list.findIndex(
          (a) => a.applicationID === action.payload.applicationID,
        );
        if (index !== -1) {
          state.list[index] = action.payload;
        }
      })
      .addCase(CanseldApplicationStatus.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.payload;
      });
  },
});

export default applicationsSlice.reducer;
