import React from "react";
import { Drawer, Box, Typography, IconButton } from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import CircularProgress from "./LodaingCircul";
import UserInfoPanel from "../Shared/Users/UserInfoPanel";
import { useSelector, useDispatch } from "react-redux";
import { GetCurrentPerson } from "../Store/features/people/peopleSlice";
import { useEffect } from "react";
import { getCountry } from "../Store/features/Country/countrySlice";

// شاشة منبثقة (Popup) — تظهر عند: Account Settings → Current User Info
// person/user فاضيين افتراضيًا (وليس null) حتى تظهر بنية الشاشة كاملة
// بحقول فاضية (—) بانتظار ربط الجلسة الحقيقية
export default function CurrentUserInfoPanel({
  open,
  onClose,
  person,
  onEditPerson,
}) {
  const user = useSelector((state) => state.users.currentUser);
  const statu = useSelector((state) => state.people.status);
  const dispatch = useDispatch();

  useEffect(() => {
    if (!open) return;
    dispatch(getCountry());

    const fetchPerson = async () => {
      try {
        await dispatch(GetCurrentPerson(user.personID)).unwrap();
      } catch (error) {
        console.log("so Bad, theres a bug in MainScreen.js", error);
      }
    };

    fetchPerson(); // استدعاء الدالة
  }, [open, dispatch]);

  // if (statu === "loading") {
  //   return <CircularProgress />;
  // }

  // if (statu === "failed") {
  //   return <div>يتمجلب البيانات لم تعمل</div>;
  // }

  return (
    <Drawer
      anchor="right"
      open={open}
      onClose={onClose}
      className="profile-drawer"
    >
      <Box className="profile-drawer-content">
        <Box className="profile-drawer-header">
          <Typography className="profile-drawer-title" variant="h6">
            Current User Info{" "}
          </Typography>
          <IconButton onClick={onClose}>
            <CloseIcon />
          </IconButton>
        </Box>

        <UserInfoPanel
          person={person || {}}
          onEditPerson={onEditPerson}
          onClose={onClose}
        />
      </Box>
    </Drawer>
  );
}
