import React from "react";
import {
  Dialog,
  DialogContent,
  DialogActions,
  Button,
  Typography,
} from "@mui/material";
import PersonInfoPanel from "./PersonInfoPanel";

// ✅ يُستدعى من أي شاشة عبر رابط "Show Licenses Info" أو مشابه —
// يعيد استخدام PersonInfoPanel نفسه دون أي تكرار للحقول
export default function PersonInfoModal({ open, onClose, person }) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="sm"
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <Typography variant="h5" className="person-details-title">
          Person Details
        </Typography>
        <PersonInfoPanel person={person} />
      </DialogContent>
      <DialogActions className="modal-actions">
        <Button onClick={onClose} className="modal-btn-cancel">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}
