import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const initialState = {
  list: [], //
  status: "idle", // 'idle' | 'loading' | 'succeeded' | 'failed'
  error: null,
};

export const getApplicationTypes = createAsyncThunk(
  "applicationTypes/getApplicationTypes",
  async () => {
    const response = await axios.get(
      "https://idnan820-001-site1.ltempurl.com/api/ApplicationTypes",
    );
    return response.data;
  },
  {
    condition: (_, { getState }) => {
      const { ApplicationType } = getState();
      // لو فيه بيانات محملة أصلاً، أو فيه طلب شغال حالياً، لا تكمل التنفيذ
      if (
        ApplicationType.status === "loading" ||
        ApplicationType.list.length > 0
      ) {
        return false; // 👈 هذا بيلغي تنفيذ الـ thunk كلياً
      }
      return true;
    },
  },
);

const ApplicationTypeSlice = createSlice({
  name: "ApplicationType",
  initialState,
  reducers: {},

  extraReducers: (builder) => {
    builder
      .addCase(getApplicationTypes.pending, (state) => {
        state.status = "loading";
        state.error = null;
      })
      .addCase(getApplicationTypes.fulfilled, (state, action) => {
        state.status = "succeeded";
        state.list = action.payload; // نستبدل القائمة بالبيانات الحقيقية القادمة من الـ API
      })
      .addCase(getApplicationTypes.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

export default ApplicationTypeSlice.reducer;
