import React from "react";
import AssignmentIcon from "@mui/icons-material/Assignment";
import BadgeIcon from "@mui/icons-material/Badge";
import EventIcon from "@mui/icons-material/Event";
import PaidIcon from "@mui/icons-material/Paid";
import PersonIcon from "@mui/icons-material/Person";
import LockClockIcon from "@mui/icons-material/LockClock";

import InfoCard from "../InfoCard";
import Field from "../Field";

const formatDate = (isoDate) => {
  if (!isoDate) return "";
  const d = new Date(isoDate);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
};

export default function DTNInfo({
  detainID,
  licenseID,
  detainDate,
  createdByLabel,
  applicationFees,
  fineFees,
  applicationID,
}) {
  const totalFees =
    applicationFees != null && fineFees != null
      ? Number(applicationFees) + Number(fineFees)
      : null;

  return (
    <InfoCard icon={LockClockIcon} title="DTN INFO">
      <Field icon={AssignmentIcon} label="Detain ID" value={detainID} />
      <Field icon={BadgeIcon} label="License ID" value={licenseID} />
      <Field
        icon={EventIcon}
        label="Detain Date"
        value={formatDate(detainDate)}
      />
      <Field icon={PersonIcon} label="Created By" value={createdByLabel} />
      <Field icon={PaidIcon} label="Application Fees" value={applicationFees} />
      <Field icon={PaidIcon} label="Fine Fees" value={fineFees} />
      <Field icon={PaidIcon} label="Total Fees" value={totalFees} />
      <Field
        icon={AssignmentIcon}
        label="Application ID"
        value={applicationID}
      />
    </InfoCard>
  );
}
