import React from "react";
import { Box, TextField, Button } from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";

export default function LicenseFilter({
  value,
  onChange,
  onSearch,
  error,
  label = "License ID",
}) {
  return (
    <>
      <Box className="license-filter-row">
        <TextField
          label={label}
          placeholder="Enter license ID..."
          value={value}
          onChange={onChange}
          onKeyDown={(e) => e.key === "Enter" && onSearch()}
          className="modal-textfield"
          fullWidth
        />
        <Button
          onClick={onSearch}
          variant="outlined"
          startIcon={<SearchIcon />}
          className="user-verify-btn"
        >
          Search
        </Button>
      </Box>
      {error && <Box className="modal-error-text">{error}</Box>}
    </>
  );
}
