import React, { useEffect, useState } from "react";
import { Dialog, DialogContent } from "@mui/material";
import PersonFormPanel from "../Shared/Person/PersonFormPanel";
import { useSelector, useDispatch } from "react-redux";
import { selectPersonById } from "../Store/features/people/peopleSlice";
// personId فقط — الفورم يُعبَّى من بيانات حقيقية تُجلب بالـID
export default function UpdatePerson({ open, onClose, personId, onSave }) {
  // const [person, setPerson] = useState(null);
  const person = useSelector((state) => selectPersonById(state, personId));

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="md"
      className="modal-dialog"
    >
      <DialogContent className="modal-content">
        <PersonFormPanel
          mode="update"
          person={person}
          onClose={onClose}
          onSave={onSave}
        />
      </DialogContent>
    </Dialog>
  );
}
